INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_edumic_1792151537391','EduMic','EduMic','','','Operating System: Other','Operating System: Other','','','EduMic is a versatile hearing aid accessory. In remote microphone mode, it helps you when distance and noise make it difficult to hear the person speaking – in the classroom, in work situations, during sports, and more. EduMic can also plug in to devices via a standard 3.5mm headphone jack, to stream audio wirelessly to Oticon Bluetooth hearing aids. It also picks up audio from public hearing loop systems.

Manufacturer: Oticon (https://www.oticon.global/hearing-aid-users)

EduMic Support: https://www.oticon.com/support/how-to/use-edumic

','hearing','Oticon','','','https://at.mada.org.qa/technology/edumic/','https://at.mada.org.qa/technology/edumic/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/Oticon-EduMic.png','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:52:17.394Z','2026-10-23T08:17:11.389Z','EduMic is a versatile hearing aid accessory. In remote microphone mode, it helps you when distance and noise make it difficult to hear the person speaking – in the classroom, in work situations, during sports, and more. EduMic can also plug in to devices via a standard 3.5mm headphone jack, to stream audio wirelessly to Oticon Bluetooth hearing aids. It also picks up audio from public hearing loop systems.

Manufacturer: Oticon (https://www.oticon.global/hearing-aid-users)

EduMic Support: https://www.oticon.com/support/how-to/use-edumic

