INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_oticon-amigo-t31-t30_1792151539430','Oticon Amigo T31, T30','Oticon Amigo T31, T30','','','Operating System: Other','Operating System: Other','','','Teachers want to spend their time teaching – not trying to decipher complex FM systems. Amigo transmitters make life easy. They simply turn on the transmitter, clip on the microphone and begin teaching. The transmitters send the teacher’s voice directly to the pupil, overcoming the effects of noise, distance and reverberation that can make it hard for children to hear.
There’s always lots of activity taking place in a classroom, and background noise in any form can be extremely distracting to children – but particularly to those with listening difficulties.
Amigo Star has the ability to help children conserve some of their resources to concentrate on what matters most: their learning.
Amigo Star is the latest evolution of the Amigo FM family – designed to help normal hearing children with listening difficulties concentrate better in class.
• Smooth integration: integrates with the Amigo FM system or any FM system already in place
• Comfortable and discreet: available in a range of colours with tubes and domes in various sizes
• Easy and intuitive to use: fit it to the ear, switch on, sync and start
• Robust: drop- and water- resistant

User Support: https://www.oticon.com/-/media/oticon-us/main/download-center/amigo/ifu/108616us-instructions-for-use—amigo-t30-t31.pdf

','hearing','Oticon','','','https://at.mada.org.qa/technology/oticon-amigo-t31-t30/','https://at.mada.org.qa/technology/oticon-amigo-t31-t30/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Oticon-Amigo-T31T30.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:52:19.431Z','2026-10-23T08:17:29.183Z','Teachers want to spend their time teaching – not trying to decipher complex FM systems. Amigo transmitters make life easy. They simply turn on the transmitter, clip on the microphone and begin teaching. The transmitters send the teacher’s voice directly to the pupil, overcoming the effects of noise, distance and reverberation that can make it hard for children to hear.
There’s always lots of activity taking place in a classroom, and background noise in any form can be extremely distracting to children – but particularly to those with listening difficulties.
Amigo Star has the ability to help children conserve some of their resources to concentrate on what matters most: their learning.
Amigo Star is the latest evolution of the Amigo FM family – designed to help normal hearing children with listening difficulties concentrate better in class.
• Smooth integration: integrates with the Amigo FM system or any FM system already in place
• Comfortable and discreet: available in a range of colours with tubes and domes in various sizes
• Easy and intuitive to use: fit it to the ear, switch on, sync and start
• Robust: drop- and water- resistant

User Support: https://www.oticon.com/-/media/oticon-us/main/download-center/amigo/ifu/108616us-instructions-for-use—amigo-t30-t31.pdf

',NULL,NULL);
