Manufacture: Oticon
https://www.oticon.com/solutions/for-children/amigo-fmIntroduction

',NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_chatpack-desktop-sound-field-system-model-ta-1_1792151556509','Chatpack Desktop Sound Field System (Model TA-1)','Chatpack Desktop Sound Field System (Model TA-1)','','','Operating System: Other','Operating System: Other','','','Chatpack Desktop Sound Field System, model TA-1, is an FM amplification device designed for people with hearing impairments. The device helps people with hearing difficulties to link with the outside world whether at home or at school. The device increases the teacher voice over the background noise for example. The device combines digitally synthesized receiver, transmitter, headset, ChatPack carrying pouch, and convenient system carrying case. Furthermore, the receiver can be removed which allows the user to use it as personal FM receiver with earphones, neck-loop, or direct audio input cards.

Manufacture: Comtek Communications Technology, Inc. (https://comtek.com)

