Manufacture: Comtek Communications Technology, Inc. (https://comtek.com)

',NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_comfort-contego-with-headphone-or-neck-loop_1792151558897','Comfort Contego with Headphone or Neck Loop','Comfort Contego with Headphone or Neck Loop','','','Operating System: Other','Operating System: Other','','','Comfort Contego is a high definition, digital wireless FM communication system designed for people with hearing impairments. The device transmits encrypted signal over secure coded channels. It also can be used at work, school or public places as well as it can be connected directly to television, and sound system audio. Furthermore, it has a built-in zoom microphones which allows the user to adjust the sound. Moreover, when the device is used with the neck loop extension cord, the receiver can be placed on a tabletop to provide a second directional microphone and that helps users in conference room or meeting setting. Also, the device allows users to hear their own voices or voices around them while watching the TV for example.

Manufacture: Comfort Audio (https://teltex.com/content/userguides/Comfort-Audio-Contego-User-Guide.pdf)

