INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_braillesense-6_1792151570518','BrailleSense 6','BrailleSense 6','','','Operating System: Android','Operating System: Android','','','BrailleSense 6 is an innovative collaboration of Braille and mainstream technology, offering the blind and visually impaired unprecedented accessible and intuitive productivity in today’s tablet-based world.

With its built-in apps for document creation, e-mail, Web browsing, media and DAISY playback, contacts, calendar and database management, and book search and download, BrailleSense 6 is a powerful productivity tool that promotes Braille literacy through its Braille-centric command structure; while supporting Google Apps such as Google Drive, Google Docs, Google Sheets, Google Slides and Google Classroom; ensuring students and professionals can be intuitively productive and efficiently collaborative in the contemporary world.

Manufacturer: SELVAS BLV (product page, support page)

','vision','SELVAS BLV','','','https://at.mada.org.qa/technology/braillesense-6/','https://at.mada.org.qa/technology/braillesense-6/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/BrailleSesnse-6.png','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:52:50.518Z','2026-10-23T08:21:40.755Z','BrailleSense 6 is an innovative collaboration of Braille and mainstream technology, offering the blind and visually impaired unprecedented accessible and intuitive productivity in today’s tablet-based world.

With its built-in apps for document creation, e-mail, Web browsing, media and DAISY playback, contacts, calendar and database management, and book search and download, BrailleSense 6 is a powerful productivity tool that promotes Braille literacy through its Braille-centric command structure; while supporting Google Apps such as Google Drive, Google Docs, Google Sheets, Google Slides and Google Classroom; ensuring students and professionals can be intuitively productive and efficiently collaborative in the contemporary world.

Manufacturer: SELVAS BLV (product page, support page)

',NULL,NULL);
