INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_grid-pad-10s_1792151604132','Grid Pad 10s','Grid Pad 10s','','','Operating System: Other','Operating System: Other','','','Grid Pad 10s is a dedicated, multi-access device designed for users who want a portable and rugged communication aid. The high-quality engineering and unique set of features bring you a next generation AAC device designed with independence and durability in mind.

The second screen adds a whole new way to communicate by showing your message on the front of your device. This can be helpful in noisy environments in addition to using your Grid voice, helping you get your message across clearly to the person you’re communicating with.

Grid Pad 10s is a multi-access device, so there are lots of ways to interact with it. There is a touch screen which you can use with a keyguard, two switch ports for use with switches, two USB ports for use with USB access devices like joysticks, and
a headphone and mic combo port. You can also connect Bluetooth devices to your Grid Pad such as wireless switches, pointers, headphones and more.

GEWA infrared Environment Control allows you to operate devices around your home, like your TV and other remote controlled gadgets. The front facing IR learning window provides ease of programming, and the multi-directional infrared LEDs give you a powerful 10m range signal.

Grid Pad 10s User Guide: https://thinksmartbox.com/product/grid-pad-10s/

','voice-and-speech','SmartBox','','','https://at.mada.org.qa/technology/grid-pad-10s/','https://at.mada.org.qa/technology/grid-pad-10s/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Grid-Pad-10s.png','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:53:24.133Z','2026-10-23T09:44:17.996Z','Grid Pad 10s is a dedicated, multi-access device designed for users who want a portable and rugged communication aid. The high-quality engineering and unique set of features bring you a next generation AAC device designed with independence and durability in mind.

The second screen adds a whole new way to communicate by showing your message on the front of your device. This can be helpful in noisy environments in addition to using your Grid voice, helping you get your message across clearly to the person you’re communicating with.

Grid Pad 10s is a multi-access device, so there are lots of ways to interact with it. There is a touch screen which you can use with a keyguard, two switch ports for use with switches, two USB ports for use with USB access devices like joysticks, and
a headphone and mic combo port. You can also connect Bluetooth devices to your Grid Pad such as wireless switches, pointers, headphones and more.

GEWA infrared Environment Control allows you to operate devices around your home, like your TV and other remote controlled gadgets. The front facing IR learning window provides ease of programming, and the multi-directional infrared LEDs give you a powerful 10m range signal.

Grid Pad 10s User Guide: https://thinksmartbox.com/product/grid-pad-10s/

',NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_gotalk-now_1792151606057','GoTalk Now','GoTalk Now','','','Operating System: iOS','Operating System: iOS','','','GoTalk Now provides all the tools you’ll need in an AAC app, plus so much more! Newly included with NOW are the Core word communication pages. Core vocabulary refer to a small collection of words that make up the majority of words used in daily communication. Now you have instant access to a set of pages, field-tested and created by SLP Gisele Morin-Connolly, based on Project CORE research from UNC Center for Literacy and Disability Studies. These Core pages will be a great starting point and will have you communicating in no time. Communicate using one word to 36 words enhanced with these core pages and more! Create and add new pages that suit your personality too. Choose from four mix-and-match page styles: Standard, Express, Visual Scene, and Keyboard.

GoTalk Now user guide: https://www.attainmentcompany.com/gotalk-now

','voice-and-speech','Attainment Company','','','https://at.mada.org.qa/technology/gotalk-now/','https://at.mada.org.qa/technology/gotalk-now/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/GoTalk-Nowjpg.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:53:26.058Z','2026-10-23T09:42:20.215Z','GoTalk Now provides all the tools you’ll need in an AAC app, plus so much more! Newly included with NOW are the Core word communication pages. Core vocabulary refer to a small collection of words that make up the majority of words used in daily communication. Now you have instant access to a set of pages, field-tested and created by SLP Gisele Morin-Connolly, based on Project CORE research from UNC Center for Literacy and Disability Studies. These Core pages will be a great starting point and will have you communicating in no time. Communicate using one word to 36 words enhanced with these core pages and more! Create and add new pages that suit your personality too. Choose from four mix-and-match page styles: Standard, Express, Visual Scene, and Keyboard.

GoTalk Now user guide: https://www.attainmentcompany.com/gotalk-now

',NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_proloquo2go_1792151608199','Proloquo2Go','Proloquo2Go','','','Operating System: iOS','Operating System: iOS','','','Proloquo2Go is a symbol-based app helps users learn how to express themselves. Proloquo2Go puts the user’s development first, with innovative features based on clinical knowledge and user research.

It’s also one of the few AAC apps designed to support all users, from beginning to advanced. Completely customizable and designed for a range of fine-motor and visual skills, the app’s versatility makes it useful for non-verbal people with autism, Down syndrome, cerebral palsy, and a range of other diagnoses or speech impediments like apraxia and dysarthria.

Manufacturer: Assistiveware (https://www.assistiveware.com)

','voice-and-speech','Assistiveware','','','https://at.mada.org.qa/technology/proloquo2go/','https://at.mada.org.qa/technology/proloquo2go/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Proloquo2Go.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:53:28.199Z','2026-10-23T09:42:32.281Z','Proloquo2Go is a symbol-based app helps users learn how to express themselves. Proloquo2Go puts the user’s development first, with innovative features based on clinical knowledge and user research.

It’s also one of the few AAC apps designed to support all users, from beginning to advanced. Completely customizable and designed for a range of fine-motor and visual skills, the app’s versatility makes it useful for non-verbal people with autism, Down syndrome, cerebral palsy, and a range of other diagnoses or speech impediments like apraxia and dysarthria.

Manufacturer: Assistiveware (https://www.assistiveware.com)

',NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_proloquo4text_1792151610328','Proloquo4Text','Proloquo4Text','','','Operating System: iOS','Operating System: iOS','','','This Text to Speech app is for literate AAC users looking for an efficient text based communication app.

Type less and react quickly to the conversation at hand with smart features and a handy layout.

Prediction learns from how you write to give you suggestions for the next thing to say.
Create your own phrases, group them for fast access, and easily find things you’ve said before with history.
Access the keyboard, words and phrases from a single screen

Proloquo4Text lets you be you. Choose from more than 130 voices in 18 languages including English, Arabic, Catalan, Czech Danish, Dutch, Finnish, French, German, Greek, Italian, Norwegian, Polish, Portuguese, Russian, Spanish, Swedish, and Turkish.

These voices range from friendly adult voices to genuine children’s voices. The voices are created using real recorded speech, making them feel surprisingly natural. For some languages, you even have multiple options.

Manufacturer: Assistiveware (https://www.assistiveware.com/products/proloquo4text)

','voice-and-speech','Assistiveware','','','https://at.mada.org.qa/technology/proloquo4text/','https://at.mada.org.qa/technology/proloquo4text/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Proloquo4text.png','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:53:30.329Z','2026-10-23T09:42:34.122Z','This Text to Speech app is for literate AAC users looking for an efficient text based communication app.

Type less and react quickly to the conversation at hand with smart features and a handy layout.

Prediction learns from how you write to give you suggestions for the next thing to say.
Create your own phrases, group them for fast access, and easily find things you’ve said before with history.
Access the keyboard, words and phrases from a single screen

Proloquo4Text lets you be you. Choose from more than 130 voices in 18 languages including English, Arabic, Catalan, Czech Danish, Dutch, Finnish, French, German, Greek, Italian, Norwegian, Polish, Portuguese, Russian, Spanish, Swedish, and Turkish.

These voices range from friendly adult voices to genuine children’s voices. The voices are created using real recorded speech, making them feel surprisingly natural. For some languages, you even have multiple options.

Manufacturer: Assistiveware (https://www.assistiveware.com/products/proloquo4text)

',NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_coughdrop-aac_1792151612761','CoughDrop AAC','CoughDrop AAC','','','Operating System: Windows, iOS, Android, Chrome','Operating System: Windows, iOS, Android, Chrome','','','CoughDrop is an open, flexible augmentative and alternative communication (AAC) app for people with complex communication needs, that can grow and expand with the user, make it easier to provide meaningful supports, and provide useful insights, all in a clean, cross-platform package.

CoughDrop is built to run on all major devices, including desktop computers and laptops, iPads and iPhones, Android tablets and phones, Kindles, Chromebooks, and Windows devices. The interface stays consistent across devices so that users can swap out devices with minimal interruption or confusion. CoughDrop is built on modern web standards and offers an open API and integration points to try to work with as many existing systems as possible.

CoughDrop has vocabulary sets for many different levels, with built-in supports and vocabulary progression tools to start basic and grow over time. It has support for eye tracking and switches, and also new input methods like joysticks and gesture control, to give the user more flexibility.

','voice-and-speech','CoughDrop','','','https://at.mada.org.qa/technology/coughdrop-aac/','https://at.mada.org.qa/technology/coughdrop-aac/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/CoughDrop.png','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:53:32.761Z','2026-10-23T09:42:14.139Z','CoughDrop is an open, flexible augmentative and alternative communication (AAC) app for people with complex communication needs, that can grow and expand with the user, make it easier to provide meaningful supports, and provide useful insights, all in a clean, cross-platform package.

CoughDrop is built to run on all major devices, including desktop computers and laptops, iPads and iPhones, Android tablets and phones, Kindles, Chromebooks, and Windows devices. The interface stays consistent across devices so that users can swap out devices with minimal interruption or confusion. CoughDrop is built on modern web standards and offers an open API and integration points to try to work with as many existing systems as possible.

CoughDrop has vocabulary sets for many different levels, with built-in supports and vocabulary progression tools to start basic and grow over time. It has support for eye tracking and switches, and also new input methods like joysticks and gesture control, to give the user more flexibility.

',NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_tobii-dynavox-i-series_1792151615020','Tobii Dynavox I-Series','Tobii Dynavox I-Series','','','Operating System: Windows','Operating System: Windows','','','The I-Series is an eye gaze-enabled speech generating device featuring the world’s leading eye tracker. Purpose-built for people with conditions such as cerebral palsy, Rett syndrome or ALS, this Windows-based device is controlled completely with your eyes to communicate and live more independently.

The I-16 is a custom-built AAC devices that enable communication and independence for people with disabilities via eye control and other access methods.

It is the lightest, fastest and most durable integrated eye tracking device available and is packed with ground breaking innovations such as a partner window and industry-leading eye tracking performance using Tobii’s latest eye tracking sensor IS5. The partner window is a second screen, located on the back of the device, which mirrors the phrases being typed and enables true face-to-face communication

More information at https://www.tobiidynavox.com/products/i-series/

','voice-and-speech','Tobii Dynavox','','','https://at.mada.org.qa/technology/tobii-dynavox-i-series/','https://at.mada.org.qa/technology/tobii-dynavox-i-series/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Tobii-Dynavox-I-16.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:53:35.021Z','2026-10-23T09:42:54.062Z','The I-Series is an eye gaze-enabled speech generating device featuring the world’s leading eye tracker. Purpose-built for people with conditions such as cerebral palsy, Rett syndrome or ALS, this Windows-based device is controlled completely with your eyes to communicate and live more independently.

The I-16 is a custom-built AAC devices that enable communication and independence for people with disabilities via eye control and other access methods.

It is the lightest, fastest and most durable integrated eye tracking device available and is packed with ground breaking innovations such as a partner window and industry-leading eye tracking performance using Tobii’s latest eye tracking sensor IS5. The partner window is a second screen, located on the back of the device, which mirrors the phrases being typed and enables true face-to-face communication

More information at https://www.tobiidynavox.com/products/i-series/

',NULL,NULL);
