INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_skwitch_1792151623691','Skwitch','Skwitch','','','Operating System: iOS','Operating System: iOS','','','Skwitch is a clever new music-making gadget & app. It clips straight on to your iPhone and uses the onboard sensors to create a one-button musical instrument that is responsive, expressive and amazingly versatile. Just press the button to play notes. It’s that easy.

Skwitch is for anyone looking to build confidence in their musical abilities; from aspiring musicians looking for a fun, portable way to get into music-making, to music technologists looking for ways to bring new life to their compositions and live sets. Skwitch makes it fun and easy to get started and doesn’t require an in-depth understanding of music theory or technique. With Skwitch you can just dive right in.

','cognition','Skoogmusic Ltd. Defunct','','','https://at.mada.org.qa/technology/skwitch/','https://at.mada.org.qa/technology/skwitch/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Skwitch.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:53:43.692Z','2026-10-23T08:14:30.721Z','Skwitch is a clever new music-making gadget & app. It clips straight on to your iPhone and uses the onboard sensors to create a one-button musical instrument that is responsive, expressive and amazingly versatile. Just press the button to play notes. It’s that easy.

Skwitch is for anyone looking to build confidence in their musical abilities; from aspiring musicians looking for a fun, portable way to get into music-making, to music technologists looking for ways to bring new life to their compositions and live sets. Skwitch makes it fun and easy to get started and doesn’t require an in-depth understanding of music theory or technique. With Skwitch you can just dive right in.

',NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_xbox-adaptive-controller_1792151627759','Xbox Adaptive Controller','Xbox Adaptive Controller','','','Operating System: Windows','Operating System: Windows','','','Xbox Adaptive Controller creates a custom controller experience that makes gaming more accessible. Connect external switches, buttons, mounts and joysticks.

Designed primarily to meet the needs of gamers with limited mobility, the Xbox Adaptive Controller features large programmable buttons and connects to external switches, buttons, mounts and joysticks to help make gaming more accessible. Requires external devices for gameplay.

Manufacturer: Xbox ( https://www.xbox.com/en-US/accessories/controllers/xbox-adaptive-controller)

','mobility','Xbox','','','https://at.mada.org.qa/technology/xbox-adaptive-controller/','https://at.mada.org.qa/technology/xbox-adaptive-controller/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Xbox-accessible-game-controller.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:53:47.759Z','2026-10-23T08:21:21.653Z','Xbox Adaptive Controller creates a custom controller experience that makes gaming more accessible. Connect external switches, buttons, mounts and joysticks.

Designed primarily to meet the needs of gamers with limited mobility, the Xbox Adaptive Controller features large programmable buttons and connects to external switches, buttons, mounts and joysticks to help make gaming more accessible. Requires external devices for gameplay.

Manufacturer: Xbox ( https://www.xbox.com/en-US/accessories/controllers/xbox-adaptive-controller)

',NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_animated-sandbox_1792151629867','Animated SandBox','Animated SandBox','','','Operating System: Other','Operating System: Other','','','The Animated Sandbox is an educational interactive experience in which users can change and redesign habitats and topography. Users will explore, create, and learn by using their imaginations and our augmented reality sandbox.

Users will pile up and dig out sand, while an interactive sensor detects the changes made to the sand and the projection adjusts accordingly in real time. Augmented reality layers will make mountains, plains, and bodies of water, teaching users about topography and different environments. Animals and objects will react to the changes and roam where they are found in their natural habitats. This interactive tabletop sandbox is perfect for schools, museums, science centers, and more!

','mobility','Breeze Creative LLC.','','','https://at.mada.org.qa/technology/animated-sandbox/','https://at.mada.org.qa/technology/animated-sandbox/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Sandbox.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:53:49.868Z','2026-10-23T11:36:25.346Z','The Animated Sandbox is an educational interactive experience in which users can change and redesign habitats and topography. Users will explore, create, and learn by using their imaginations and our augmented reality sandbox.

Users will pile up and dig out sand, while an interactive sensor detects the changes made to the sand and the projection adjusts accordingly in real time. Augmented reality layers will make mountains, plains, and bodies of water, teaching users about topography and different environments. Animals and objects will react to the changes and roam where they are found in their natural habitats. This interactive tabletop sandbox is perfect for schools, museums, science centers, and more!

',NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_hopspot_1792151632163','Hopspot','Hopspot','','','Operating System: iOS','Operating System: iOS','','','Hopspots is an interactive learning tool designed to make it easy to create active learning. Hopspots challenges in movement, cognitive training, language learning, collaboration etc., and makes it possible for children to become digital co-creators of learning content when they produce games in the app.

Hopspots trains body and memory whilst playing and learning. Thus, Hopspots can be used at all ages. For instance, Hopspots can help 3-year-old children recognize animal sounds, 7-year-old children with learning the alphabet, 10-year-old children with multiplication and division, 15-year-old children with collaboration and discussion, and help elderly citizens with having fun while preventing dementia and other age-related illnesses.

Hopspot How-to guides: https://www.hopspots.dk/en/get-started/

','cognition','Hopspot','','','https://at.mada.org.qa/technology/hopspot/','https://at.mada.org.qa/technology/hopspot/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Hopspot.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:53:52.163Z','2026-10-23T08:13:44.990Z','Hopspots is an interactive learning tool designed to make it easy to create active learning. Hopspots challenges in movement, cognitive training, language learning, collaboration etc., and makes it possible for children to become digital co-creators of learning content when they produce games in the app.

Hopspots trains body and memory whilst playing and learning. Thus, Hopspots can be used at all ages. For instance, Hopspots can help 3-year-old children recognize animal sounds, 7-year-old children with learning the alphabet, 10-year-old children with multiplication and division, 15-year-old children with collaboration and discussion, and help elderly citizens with having fun while preventing dementia and other age-related illnesses.

Hopspot How-to guides: https://www.hopspots.dk/en/get-started/

',NULL,NULL);
