INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_amazon-alexa-app_1792151640824','Amazon Alexa','Amazon Alexa','','','Operating System: Other','Operating System: Other','','','Use the Amazon Alexa App to set up your Alexa-enabled devices, listen to music, create shopping lists, get news updates, and much more. The more you use Alexa, the more she adapts to your voice, vocabulary, and personal preferences.

Show and Tell is designed to help people who are blind or have low vision. Show and Tell identifies common grocery items and other products by using your Echo Show’s camera. Hold up a product such as a canned good in front of your Echo Show’s camera and say, “Alexa, what am I holding?“

Amazon announces accessibility upgrades to Alexa app for people with vision impairments.

Light and dark modes: Using their mobile device settings, users can choose between light and dark modes for benefits like increased readability and colour contrast. Dark mode will offer benefits such as screen viewing comfort in low-light environments and improved device battery life, while light mode will offer better readability and colour contrast that stands out in high-light environments. The Alexa app will default to light or dark mode, depending on the user’s mobile settings.
Text scaling for improved accessibility: Users can set their device’s font size to be larger than the standard size. This means the individual will see larger text on most screens of the Alexa app proportional to their preferred accessibility setting. This can be especially helpful for people with certain vision impairments.

','cognition','Amazon Mobile LLC','','','https://at.mada.org.qa/technology/amazon-alexa-app/','https://at.mada.org.qa/technology/amazon-alexa-app/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Amazon-Alexa.png','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:54:00.824Z','2026-10-23T08:13:00.721Z','Use the Amazon Alexa App to set up your Alexa-enabled devices, listen to music, create shopping lists, get news updates, and much more. The more you use Alexa, the more she adapts to your voice, vocabulary, and personal preferences.

Show and Tell is designed to help people who are blind or have low vision. Show and Tell identifies common grocery items and other products by using your Echo Show’s camera. Hold up a product such as a canned good in front of your Echo Show’s camera and say, “Alexa, what am I holding?“

Amazon announces accessibility upgrades to Alexa app for people with vision impairments.

Light and dark modes: Using their mobile device settings, users can choose between light and dark modes for benefits like increased readability and colour contrast. Dark mode will offer benefits such as screen viewing comfort in low-light environments and improved device battery life, while light mode will offer better readability and colour contrast that stands out in high-light environments. The Alexa app will default to light or dark mode, depending on the user’s mobile settings.
Text scaling for improved accessibility: Users can set their device’s font size to be larger than the standard size. This means the individual will see larger text on most screens of the Alexa app proportional to their preferred accessibility setting. This can be especially helpful for people with certain vision impairments.

',NULL,NULL);
