INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_amaneo-assistive-mouse-adapter_1792151657001','AMAneo Assistive Mouse Adapter','AMAneo Assistive Mouse Adapter','','','Operating System: Other','Operating System: Other','','','The AMAneo Anti-Tremor Assistive Mouse Adapter enables people with a hand tremor to use a computer mouse. It electronically filters the trembling of the hand, which can be very strong, so that the mouse pointer on the display moves smoothly. With tablets, touchscreen control is replaced by a normal mouse or an alternative mouse such as one offering head or chin control. Not all mice function within the power rating of the AMAneo USB so we now also include a free Logitech wireless mouse to ensure compatibility.

Support Document: https://www.csslabs.de/downloads/CSS_Produktuebersicht_AMAneo_DE_V10-21.pdf

