INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_smyle-mouse_1792151694832','Smyle Mouse','Smyle Mouse','','','Operating System: Windows','Operating System: Windows','','','Smyle Mouse is a head mouse software for hands-free control via head motions & face gestures. Patented head-based mouse control via web camera.

Smyle Mouse is suitable for users with acquired and progressive conditions that limit movement, such as muscular dystrophy, spinal cord injury or MND/ALS.

Smyle Mouse does not require you to be positioned at a certain distance from the screen and can be programmed to detect even the slightest head movements.

Manufacturer: Perceptive Devices LLC (https://smylemouse.com/)

Smyle Mouse User guide and tutorial: https://smylemouse.com/resources/

','mobility','Perceptive Devices LLC','','','https://at.mada.org.qa/technology/smyle-mouse/','https://at.mada.org.qa/technology/smyle-mouse/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/smyle-mouse.png','[]','','','published',1,0,'vi',NULL,'2026-10-16T11:54:54.832Z','2026-10-23T08:20:44.607Z','Smyle Mouse is a head mouse software for hands-free control via head motions & face gestures. Patented head-based mouse control via web camera.

Smyle Mouse is suitable for users with acquired and progressive conditions that limit movement, such as muscular dystrophy, spinal cord injury or MND/ALS.

Smyle Mouse does not require you to be positioned at a certain distance from the screen and can be programmed to detect even the slightest head movements.

Manufacturer: Perceptive Devices LLC (https://smylemouse.com/)

Smyle Mouse User guide and tutorial: https://smylemouse.com/resources/

',NULL,NULL);
