INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_pocket-talker-with-headphones-or-neck-loop_2420072109806','Pocket Talker with Headphones or Neck Loop','Pocket Talker with Headphones or Neck Loop','','','Operating System: Other Pocket Talker Ultra is a device designed for people with hearing impairments which amplifies sounds closest to the listener while reducing background noise. The device allows users to use it for one-on-one conversation, small-group and television listening, or conversing in the car. It also has 200 hours of battery life, adjustable tone and volume control, and support different earphones. The product is also available with neck loop and headphones. Additional Information:','','','','Operating System: Other Pocket Talker Ultra is a device designed for people with hearing impairments which amplifies sounds closest to the listener while reducing background noise. The device allows users to use it for one-on-one conversation, small-group and television listening, or conversing in the car. It also has 200 hours of battery life, adjustable tone and volume control, and support different earphones. The product is also available with neck loop and headphones. Additional Information: Manufacture: Williams Sound https://williamsav.com/personal/ Video:','hearing','','','','https://at.mada.org.qa/technology/pocket-talker-with-headphones-or-neck-loop/','https://at.mada.org.qa/technology/pocket-talker-with-headphones-or-neck-loop/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Pocket-Talker-with-Headphones-or-Neck-Loop.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:13:39.636Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_clarity-alertmaster-al10-visual-alert-system_2420072120644','Clarity AlertMaster AL10 Visual Alert System','Clarity AlertMaster AL10 Visual Alert System','','','Operating System: Other Visual Alert System, AL10, is a device designed for people with hearing impairments. The device alerts users of visitors to your home, telephone calls, activity of babies and young children, and alarm clock functions. Furthermore, it allows users to stay secure and aware of any loud and unusual sounds, unexpected movements, and turn ON/ OFF the lights around the house at selected times. In addition, it has a built-in lamp flasher and powerful vibrating alert that shakes b','','','','Operating System: Other Visual Alert System, AL10, is a device designed for people with hearing impairments. The device alerts users of visitors to your home, telephone calls, activity of babies and young children, and alarm clock functions. Furthermore, it allows users to stay secure and aware of any loud and unusual sounds, unexpected movements, and turn ON/ OFF the lights around the house at selected times. In addition, it has a built-in lamp flasher and powerful vibrating alert that shakes bed or pillow to notify the user while sleeping. Additional Information: Manufacturer: Clarity (product page, user guide','hearing','Clarity','','','https://at.mada.org.qa/technology/clarity-alertmaster-al10-visual-alert-system/','https://at.mada.org.qa/technology/clarity-alertmaster-al10-visual-alert-system/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Clarity-AlertMaster-AL10-Visual-Alert-System.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:17:04.560Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_krown-ra-05-amplified-ringer-with-strobe_242007212561','Krown RA-05 Amplified Ringer with Strobe','Krown RA-05 Amplified Ringer with Strobe','','','Operating System: Other Amplified Ringer 05 is a device designed for people with hearing impairments which notifies them whenever the phone rings. The device is directly connected to the phone line which alerts the user whenever there is an incoming call with an amplified ringer of up to 95 dB and a bright strobe light. As well, it includes wall mount option. Additional Information: Manufacture: Krown (https://krownmfg.com/) Video:','','','','Operating System: Other Amplified Ringer 05 is a device designed for people with hearing impairments which notifies them whenever the phone rings. The device is directly connected to the phone line which alerts the user whenever there is an incoming call with an amplified ringer of up to 95 dB and a bright strobe light. As well, it includes wall mount option. Additional Information: Manufacture: Krown (https://krownmfg.com/) Video:','hearing','','','','https://at.mada.org.qa/technology/krown-ra-05-amplified-ringer-with-strobe/','https://at.mada.org.qa/technology/krown-ra-05-amplified-ringer-with-strobe/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Krown-RA-05-Amplified-Ringer-with-Strobe.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:13:29.488Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_pf200-phone-flasher_2420072129235','PF200 Phone Flasher','PF200 Phone Flasher','','','Operating System: Other PF200 Phone Flasher is a device designed for people with hearing impairments which notifies them whenever the phone rings. The device is powered by the phone line so it does not need battery and can be used anywhere in phone system. It notifies the user by an ultra-bright flash that spreads throughout the room whenever there is an incoming call. Furthermore, it is compatible with most phones and convenient for noisy rooms where people with low hearing cannot hear the phon','','','','Operating System: Other PF200 Phone Flasher is a device designed for people with hearing impairments which notifies them whenever the phone rings. The device is powered by the phone line so it does not need battery and can be used anywhere in phone system. It notifies the user by an ultra-bright flash that spreads throughout the room whenever there is an incoming call. Furthermore, it is compatible with most phones and convenient for noisy rooms where people with low hearing cannot hear the phone ringing. Additional Information: Manufacture: Krown https://krownmfg.com/shop/amplified-ringer-05-with-strobe/ Video:','hearing','','','','https://at.mada.org.qa/technology/pf200-phone-flasher/','https://at.mada.org.qa/technology/pf200-phone-flasher/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/PF200-Phone-Flasher.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:13:35.542Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_powertel-601-wireless-dect-6-0-wrist-shaker-for-powertel-series_2420072135745','PowerTel 601 Wireless DECT 6.0 Wrist Shaker for PowerTel series','PowerTel 601 Wireless DECT 6.0 Wrist Shaker for PowerTel series','','','Operating System: Other PowerTel 601 Wrist Shaker is a device designed for people with hearing impairments which notifies them whenever the phone rings. The device vibrates when there is an incoming call. It also allows users to answer calls in speakerphone mode at the press of a button, and press the emergency button to automatically dial emergency. However, this is only done when PowerTel 601 is used with PowerTel 680. Furthermore, it has up to 50 hours charge, and splash proof design for use ','','','','Operating System: Other PowerTel 601 Wrist Shaker is a device designed for people with hearing impairments which notifies them whenever the phone rings. The device vibrates when there is an incoming call. It also allows users to answer calls in speakerphone mode at the press of a button, and press the emergency button to automatically dial emergency. However, this is only done when PowerTel 601 is used with PowerTel 680. Furthermore, it has up to 50 hours charge, and splash proof design for use in the shower. The product is also available with an additional transmitter for PowerTel 680. Additional Information: Manufacture: Amplicom http://www.amplicomusa.com/site/product/powertel-601-wireless-dect-wrist-shaker-for-powertel-series/','hearing','','','','https://at.mada.org.qa/technology/powertel-601-wireless-dect-6-0-wrist-shaker-for-powertel-series/','https://at.mada.org.qa/technology/powertel-601-wireless-dect-6-0-wrist-shaker-for-powertel-series/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/PowerTel-601-Wireless-DECT-6.0-Wrist-Shaker-for-PowerTel-series.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:13:41.546Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_simplicity-telephone-ring-signaler_2420072140210','Simplicity Telephone Ring Signaler','Simplicity Telephone Ring Signaler','','','Operating System: Other Simplicity Telephone Ring Signaler, LTD model, is a device designed for people with hearing impairments which notifies them whenever the phone rings. The device connects directly to the phone line and that alerts people with low hearing when they receive a call. In addition, it has two models / styles: wall-mount or desktop and both style can flash a plugged-in lamp. It also transmits signal to remote receiver(s) to flash lamps in other rooms. For the wall-mount style, th','','','','Operating System: Other Simplicity Telephone Ring Signaler, LTD model, is a device designed for people with hearing impairments which notifies them whenever the phone rings. The device connects directly to the phone line and that alerts people with low hearing when they receive a call. In addition, it has two models / styles: wall-mount or desktop and both style can flash a plugged-in lamp. It also transmits signal to remote receiver(s) to flash lamps in other rooms. For the wall-mount style, the user can plug in the Add-On Strobe in place of a lamp where for the desktop style, the user can rests the device on a table or countertop. Additional Information: Manufacture: Turning Point Technology (product page)','hearing','','','','https://at.mada.org.qa/technology/simplicity-telephone-ring-signaler/','https://at.mada.org.qa/technology/simplicity-telephone-ring-signaler/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Simplicity-Telephone-Ring-Signaler.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:13:43.505Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_icommunicator_2420072145249','iCommunicator','iCommunicator','','','Operating System: Windows iCommunicator is a software designed for people with hearing impairments which promotes independent communication. The program translates English in real-time/ instantly: Speech to text, Speech/Text to Video Sign-Language, and Speech/Text to Computer Generated Voice. Furthermore, the user can reply using the computer’s keyboard, providing text that can be read or allow iCommunicator to speak for them with the built-in Computer-Generated Voice. In addition, it has built-','','','','Operating System: Windows iCommunicator is a software designed for people with hearing impairments which promotes independent communication. The program translates English in real-time/ instantly: Speech to text, Speech/Text to Video Sign-Language, and Speech/Text to Computer Generated Voice. Furthermore, the user can reply using the computer’s keyboard, providing text that can be read or allow iCommunicator to speak for them with the built-in Computer-Generated Voice. In addition, it has built-in up-to-date dictionary and Thesaurus which allows the user to access them to get definitions, synonyms, etc. Moreover, it allows the user to search the internet, and adjust the software as his needs as well as it supports users with special needs. The product is also available in iCommunicator™ V 4.0 Professional Version Kit. Additional Information: Manufacture: Softway LTD http://www.softway.gr/index1.php?page=basic&category_id=146&subcategory_id=159 Video:','hearing','','','','https://at.mada.org.qa/technology/icommunicator/','https://at.mada.org.qa/technology/icommunicator/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/iCommunicator-.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:13:50.119Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_interact-as-language-modules_2420072150308','Interact-AS Language Modules','Interact-AS Language Modules','','','Operating System: Windows, iOS, Chrome Interact-AS is a software designed for people with hearing impairments, difficulty in writing or typing, and lost the ability to speak. The device allows users to write, type or speak in English and immediately it is translated, voiced out in a second language. It also supports the feature of written or typed words are instantly spoken aloud which allows a nonverbal person to participate in classroom discussions. The product is also available in Professiona','','','','Operating System: Windows, iOS, Chrome Interact-AS is a software designed for people with hearing impairments, difficulty in writing or typing, and lost the ability to speak. The device allows users to write, type or speak in English and immediately it is translated, voiced out in a second language. It also supports the feature of written or typed words are instantly spoken aloud which allows a nonverbal person to participate in classroom discussions. The product is also available in Professional and Consumer editions. Additional Information: Manufacture: AUDITORY SCIENCES, LLC http://www.auditorysciences.com/ Video:','hearing','','','','https://at.mada.org.qa/technology/interact-as-language-modules/','https://at.mada.org.qa/technology/interact-as-language-modules/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Interact-AS-Language-Modules.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:13:25.350Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_interpretype_2420072154586','Interpretype','Interpretype','','','Operating System: Windows, iOS, Chrome Interpretype, also known as ITY, is a communication system that provides “Universal Access to Conversation.” It is a system designed for people with hearing impairments which promotes independent communication. The Interpretype system consists of two preprogramed mini computers that have the ability to communicate with other ITYs and/or Windows computers running ITY Communicator software. The program translates English in real-time/ instantly: Speech to tex','','','','Operating System: Windows, iOS, Chrome Interpretype, also known as ITY, is a communication system that provides “Universal Access to Conversation.” It is a system designed for people with hearing impairments which promotes independent communication. The Interpretype system consists of two preprogramed mini computers that have the ability to communicate with other ITYs and/or Windows computers running ITY Communicator software. The program translates English in real-time/ instantly: Speech to text, Speech/Text to Video Sign-Language, and Speech/Text to Computer Generated Voice. Furthermore, the two laptops have Windows operating system, and virus protection software as well as they are preconfigured to connect to the internet for communication. In addition, on one computer, JAWS Pro Screen Reader software is installed and Freedom Scientific Focus 40 Blue Braille Display is installed on the other. Additional Information: Manufacture: Interpretype LLC (https://www.interpretype.com/) Introduction video:','hearing','','','','https://at.mada.org.qa/technology/interpretype/','https://at.mada.org.qa/technology/interpretype/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Interpretype.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:13:27.435Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_pocket-sign-language-translator_242007215984','Pocket Sign Language Translator','Pocket Sign Language Translator','','','Operating System: Other Pocket Sign Language Translator is a video translator device designed for anyone interested in learning Sign language or improving their signing vocabulary. The device allows users to enter a word using the touch screen keyboard and watch a video clip signed by a live person. In addition, it includes 3,500 signs including numbers letters and pronouns as well as it supports up to 6 hours of continuous use. Moreover, it comes with a pen and can be charged via USB cable. Add','','','','Operating System: Other Pocket Sign Language Translator is a video translator device designed for anyone interested in learning Sign language or improving their signing vocabulary. The device allows users to enter a word using the touch screen keyboard and watch a video clip signed by a live person. In addition, it includes 3,500 signs including numbers letters and pronouns as well as it supports up to 6 hours of continuous use. Moreover, it comes with a pen and can be charged via USB cable. Additional Information: Manufacture: Pocket Talk (https://www.pocketalk.com/)','hearing','','','','https://at.mada.org.qa/technology/pocket-sign-language-translator/','https://at.mada.org.qa/technology/pocket-sign-language-translator/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Pocket-Sign-Language-Translator.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:13:37.585Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_ubiduo-2-wireless_2420072164590','Ubiduo 2 wireless','Ubiduo 2 wireless','','','Operating System: Other The unique patented hinge technology holds the two halves securely in place for easy transportation, and its 8-hour battery life ensures you won’t be left stranded in the middle of those important conversations. Try the new UbiDuo whenever you need a solution to facilitate face-to-face communication between deaf/hard-of-hearing and hearing people. This revolutionary device will help to eliminate bluffing, frustration and Communiphobia, as well as promote communication equ','','','','Operating System: Other The unique patented hinge technology holds the two halves securely in place for easy transportation, and its 8-hour battery life ensures you won’t be left stranded in the middle of those important conversations. Try the new UbiDuo whenever you need a solution to facilitate face-to-face communication between deaf/hard-of-hearing and hearing people. This revolutionary device will help to eliminate bluffing, frustration and Communiphobia, as well as promote communication equality. Use it to empower people to share their thoughts and emotions seamlessly in real time just as in a normal conversation. The Standard Wireless model of the UbiDuo connects each half with a built-in proprietary networking protocol that has a range of up to 300 feet. sComm’s latest UbiDuo model continues to advance the state of the art in face-to-face communication technology with a sleek package that includes a color touch screen and sComm’s patented hinge system. At half the size of the original UbiDuo, the UbiDuo 2 is the world’s foremost independent communication solution for people who are deaf, hard of hearing or hearing. Additional Information: Manufacture: sComm (product page) Video:','hearing','','','','https://at.mada.org.qa/technology/ubiduo-2-wireless/','https://at.mada.org.qa/technology/ubiduo-2-wireless/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Ubiduo-2-wireless.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:13:48.139Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_oticon-amigo-arc_2420072169584','Oticon Amigo Arc','Oticon Amigo Arc','','','Operating System: Other Amigo Arc is a universal neckloop receiver that acts as a bridge between an FM transmitter and the child’s hearing aid. Amigo Arc works with any instrument with a telecoil – including cochlear implants and bone anchored devices. It can also be used with headphones by children with listening or attention difficulties, to help them hear better and concentrate more easily. To the untrained eye, Amigo Arc looks much like an mp3 player. Children can show it off in one of five ','','','','Operating System: Other Amigo Arc is a universal neckloop receiver that acts as a bridge between an FM transmitter and the child’s hearing aid. Amigo Arc works with any instrument with a telecoil – including cochlear implants and bone anchored devices. It can also be used with headphones by children with listening or attention difficulties, to help them hear better and concentrate more easily. To the untrained eye, Amigo Arc looks much like an mp3 player. Children can show it off in one of five trendy colours – from cool white to chilli red – or conceal it completely under a shirt or sweater. Either way, it’s extremely safe to wear, thanks to a safety release that automatically opens if the neckloop should get caught on something. Amigo Arc offers easy connection to mp3 players – with a bass boost that makes music sound richer than ever. When it’s time to watch TV, children will get far more out of their favourite programmes, as the extra FM boost makes the sound quality much clearer. Additional Information: Manufacture: Oticon (https://www.oticon.com) Video:','hearing','','','','https://at.mada.org.qa/technology/oticon-amigo-arc/','https://at.mada.org.qa/technology/oticon-amigo-arc/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Oticon-Amigo-Arc.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:13:33.569Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_geemarc-induction-loop_2420072173117','Geemarc Induction Loop','Geemarc Induction Loop','','','Operating System: Other A portable unit designed for facilitating communication between a speaker and wearer/s of T-coil hearing aids. The loopHEAR™ is ideal for one to one applications such as at service counters, railway stations, banks, in vehicles and at small meetings. This lightweight unit includes, within the casing: an induction loop, a built-in amplifier and an external earpiece. Product Features: The LoopHEAR™ can be used either as a portable unit or in a fixed position Built-in microp','','','','Operating System: Other A portable unit designed for facilitating communication between a speaker and wearer/s of T-coil hearing aids. The loopHEAR™ is ideal for one to one applications such as at service counters, railway stations, banks, in vehicles and at small meetings. This lightweight unit includes, within the casing: an induction loop, a built-in amplifier and an external earpiece. Product Features: The LoopHEAR™ can be used either as a portable unit or in a fixed position Built-in microphone On/Off button Low battery indicator Indicator of emission magnetic field Adjustable receiving volume of the additional earpiece Additional Information: Manufacture: geemarc https://geemarc.com/uk/product/lh102-v2/ Video:','hearing','','','','https://at.mada.org.qa/technology/geemarc-induction-loop/','https://at.mada.org.qa/technology/geemarc-induction-loop/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Geemarc-Induction-Loop.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:13:23.189Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_sonicalert-home-alerting-systems_2420072178224','SonicAlert Home Alerting Systems','SonicAlert Home Alerting Systems','','','Operating System: Other When a phone is ringing or someone is at the door, individuals with hearing impairments or deafness have difficulty determining sounds, emergencies, or communication attempts. We offer a comprehensive selection of deaf alert systems, so you can invest in the quality assistance of technology to keep your students or patients safe. Designed to make sure the user is aware at all times, we proudly offer super bright alarm clocks, extra-loud doorbells, remote receivers, alert ','','','','Operating System: Other When a phone is ringing or someone is at the door, individuals with hearing impairments or deafness have difficulty determining sounds, emergencies, or communication attempts. We offer a comprehensive selection of deaf alert systems, so you can invest in the quality assistance of technology to keep your students or patients safe. Designed to make sure the user is aware at all times, we proudly offer super bright alarm clocks, extra-loud doorbells, remote receivers, alert units, emergency signalers, vibrating accessories, and other convenient deaf products. Alert systems are essential when you are unable to hear. Prepare your classroom, therapeutic listening lab, or home with the latest products in assistive hearing technology. Our wide selection of deaf alert systems includes endless opportunities to provide safer environments and solutions for individuals without hearing. Whether you or your student wears a hearing aid or a cochlear implant, we offer state-of-the-art technology to alert users of emergencies. Our variety of alert units include switch-accessible communication devices with the capacity to add up to four phone numbers to call in the event of an emergency. Many of the products we supply feature vibration mechanisms to shake your bed when you need to wake up, if the telephone’s ringing, or if someone’s at the door. We also supply vibrating pads that can easily be connected to any manufacturer’s phone, alarm clock, or signaling device. We also carry a wide variety of deaf products with strobe lighting effects and sonic alerts. Amplified ringers with strobe lighting amplify your incoming calls and flash brightly so you will never miss another call. Looking for a vibrant, effective way to wake up in the morning? Look no further than our sonic boom alarm clocks. These devices feature multi-colored displays with pulsating alarm lights and bed shaking mechanisms. Keep track of time on-the-go utilizing any of our vibrating wrist watches. They conveniently feature abbreviated text prompts to assist with programming and setting confirmations. EnableMart is the one-stop destination for investing in top deaf alert systems and deaf products. Find safety and improved management in the comfort of your own home, classroom, office, or any environment. If you have any questions or concerns about product availability, we’re here to help! Contact us today for assistance in finding the ideal product for your needs. Additional Information: Manufacture: Sonic Alert (official website)','hearing','','','','https://at.mada.org.qa/technology/sonicalert-home-alerting-systems/','https://at.mada.org.qa/technology/sonicalert-home-alerting-systems/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Puzzle-Set.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:13:45.780Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_lightwriter_2420072183434','Lightwriter','Lightwriter','','','Operating System: Other Lightwriters are text-to-speech devices – the person who cannot speak types a message on the keyboard, and this message is displayed on two displays, one facing the user and a second outfacing display for the communication partner(s). A speech synthesiser is also used to provide speech output. For people who are unable to use a keyboard, some models of Lightwriter offer the option of an on-screen keyboard with selection made by a switch using a scanning technique. Some mo','','','','Operating System: Other Lightwriters are text-to-speech devices – the person who cannot speak types a message on the keyboard, and this message is displayed on two displays, one facing the user and a second outfacing display for the communication partner(s). A speech synthesiser is also used to provide speech output. For people who are unable to use a keyboard, some models of Lightwriter offer the option of an on-screen keyboard with selection made by a switch using a scanning technique. Some models of Lightwriter offer the facility to connect to a printer to provide printed output. Word prediction is included to make a significant reduction in the number of keystrokes. Later models include a built-in mobile phone which provides text messaging and the option of voice telephony with the synthesised speech sent to the person on the other end and the incoming speech message being broadcast through the Lightwriter’s loudspeaker. Additional Information: Manufacturer: Abilia (product page)','hearing','Abilia','','','https://at.mada.org.qa/technology/lightwriter/','https://at.mada.org.qa/technology/lightwriter/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Lightwriter-US.webp','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:17:25.248Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_victor-reader-stratus-mp3-player-series_2420072187830','Victor Reader Stratus MP3 player Series','Victor Reader Stratus MP3 player Series','','','Operating System: Other The Victor Reader Stratus series provide simple, easy-to-use audio book players. All Victor Reader Stratus models feature large, tactile, high-contrast keys, a built-in speaker and headphone jack, and self-voicing controls, making it simply the friendliest audio book player around. All content is organized via the popular Victor Reader bookshelf categories. The bookshelves contain DAISY books, commercial audio books, music files, and text files. Additional Information: Ma','','','','Operating System: Other The Victor Reader Stratus series provide simple, easy-to-use audio book players. All Victor Reader Stratus models feature large, tactile, high-contrast keys, a built-in speaker and headphone jack, and self-voicing controls, making it simply the friendliest audio book player around. All content is organized via the popular Victor Reader bookshelf categories. The bookshelves contain DAISY books, commercial audio books, music files, and text files. Additional Information: Manufacturer: HumanWare Victor Reader Stratus user guide: https://support.humanware.com/en-international/support/victor_reader_stratus Video:','vision','HumanWare','','','https://at.mada.org.qa/technology/victor-reader-stratus-mp3-player-series/','https://at.mada.org.qa/technology/victor-reader-stratus-mp3-player-series/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Victor-Reader-Stratus.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:41:45.809Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_akw-smartcare-lever_2420072192777','AKW SmartCare Lever','AKW SmartCare Lever','','','Operating System: Other AKW has launched the AKW SmartCare Lever, an easy-to-use smart and contemporary electric shower. This product is an easy-to-use lever handle, designed for people with vision impairments and reduced mobility. With a simple and user-friendly design, a large centrally located lever contains a prominent ‘on-off’ switch and the lever can be easily grasped and turned to control the shower’s temperature. For those with visual impairments, the shower has audible temperature contr','','','','Operating System: Other AKW has launched the AKW SmartCare Lever, an easy-to-use smart and contemporary electric shower. This product is an easy-to-use lever handle, designed for people with vision impairments and reduced mobility. With a simple and user-friendly design, a large centrally located lever contains a prominent ‘on-off’ switch and the lever can be easily grasped and turned to control the shower’s temperature. For those with visual impairments, the shower has audible temperature control clicks, large red and blue temperature symbols and a large back-lit power button. It also has a matte anti-glare finish to reduce glare for those with dementia. Additional Information: Manufacturer: AKW (product page)','vision','AKW','','','https://at.mada.org.qa/technology/akw-smartcare-lever/','https://at.mada.org.qa/technology/akw-smartcare-lever/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/AKW-SmartCare.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:21:25.327Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_envision-glasses_2420072196702','Envision Glasses','Envision Glasses','','','Operating System: Other Envision Glasses are AI for your eye. They use the power of speech to make everyday life more accessible for any visual impairment. Turn any text into speech with Scan Text. Be it handwritten notes, books or your favourite recipes. Read any short text that’s in front of you with Instant Text. Find everything from house numbers, the products you love or even your favorite vinyl. Get detailed scene descriptions anywhere. So you know what’s around, every step of the way. Fin','','','','Operating System: Other Envision Glasses are AI for your eye. They use the power of speech to make everyday life more accessible for any visual impairment. Turn any text into speech with Scan Text. Be it handwritten notes, books or your favourite recipes. Read any short text that’s in front of you with Instant Text. Find everything from house numbers, the products you love or even your favorite vinyl. Get detailed scene descriptions anywhere. So you know what’s around, every step of the way. Find your colleagues or friends in an instant, with Face Recognition. Let’s get those conversations started. Additional Information: Manufacturer: Envision (https://www.letsenvision.com/envision-glasses) Video:','vision','Envision','','','https://at.mada.org.qa/technology/envision-glasses/','https://at.mada.org.qa/technology/envision-glasses/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Envision-Glasses.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:40:27.838Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_bdot-wearable-braille-keyboard_2420072201454','Bdot – Wearable Braille Keyboard','Bdot – Wearable Braille Keyboard','','','Operating System: Other Bdot is a wearable Braille Keyboard that connects with smartphones via Bluetooth. It allows users to input texts and navigate without actually touching the screen. Bluetooth Braille keyboard that can control the screen through the keyboard. Users can listen to input text and the contents of a screen in real time with human voice. Additional Information: Manufacturer: Kunyoong IBC (product page) Video:','','','','Operating System: Other Bdot is a wearable Braille Keyboard that connects with smartphones via Bluetooth. It allows users to input texts and navigate without actually touching the screen. Bluetooth Braille keyboard that can control the screen through the keyboard. Users can listen to input text and the contents of a screen in real time with human voice. Additional Information: Manufacturer: Kunyoong IBC (product page) Video:','vision','Kunyoong IBC','','','https://at.mada.org.qa/technology/bdot-wearable-braille-keyboard/','https://at.mada.org.qa/technology/bdot-wearable-braille-keyboard/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Wearable-Braille-Keyboard.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:21:35.124Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_tdot-braille-keyboard_2420072205634','Tdot Braille Keyboard','Tdot Braille Keyboard','','','Operating System: Other Tdot is a foldable braille keyboard. This product combines excellent portability with light weight (59g) and grip by modifying the Perkins-type structure common to Braille keyboards into a T-fold structure, resulting in a reduction of width by about half, weight by about 1/10th, and of the price by about 1/10th. Made with 12 input keys and 1 jog wheel, it is dedicated to boosting the navigating function that allows users to type faster and more conveniently. Additional In','','','','Operating System: Other Tdot is a foldable braille keyboard. This product combines excellent portability with light weight (59g) and grip by modifying the Perkins-type structure common to Braille keyboards into a T-fold structure, resulting in a reduction of width by about half, weight by about 1/10th, and of the price by about 1/10th. Made with 12 input keys and 1 jog wheel, it is dedicated to boosting the navigating function that allows users to type faster and more conveniently. Additional Information: Manufacturer: KUNYOONG IBC Co., Ltd. (https://eng.kunyoong.com/) Video:','vision','KUNYOONG IBC Co., Ltd.','','','https://at.mada.org.qa/technology/tdot-braille-keyboard/','https://at.mada.org.qa/technology/tdot-braille-keyboard/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Tdot.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T11:37:45.929Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_supernova_2420072210544','SuperNova','SuperNova','','','Operating System: Windows, iOS, Chrome SuperNova is the screen magnifier and screen reader software, delivering unparalleled access to Windows: Available in 3 editions to suit different types of sight loss Suitable for Windows tablets, laptops and desktops Choose your perfect blend of magnification, colours, speech and braille SuperNova Magnifier has crystal-clear magnification that enables you to easily browse websites, email your contacts and read printed letters. SuperNova Magnifier can enlar','','','','Operating System: Windows, iOS, Chrome SuperNova is the screen magnifier and screen reader software, delivering unparalleled access to Windows: Available in 3 editions to suit different types of sight loss Suitable for Windows tablets, laptops and desktops Choose your perfect blend of magnification, colours, speech and braille SuperNova Magnifier has crystal-clear magnification that enables you to easily browse websites, email your contacts and read printed letters. SuperNova Magnifier can enlarge and enhance everything on screen. Choose high-contrast colours, large mouse pointers and highlights to help you track and navigate each page. SuperNova Magnifier & Speech allows you browsing the web, emailing your contacts or reading your print letters with the combination of magnification, colours and speech. If you have a bad eye day or your sight changes, SuperNova Magnifier & Speech grows and evolves with you: Boost magnification, announce punctuation, replace difficult colours, hear webpages or listen as you type. SuperNove Magnifier & Screen Reader: Whether shopping online with the latest web browsers, creating spreadsheets and slideshows in Microsoft Office, or reading your letters and other hard copy documents, with SuperNova Magnifier & Screen Reader you can find your perfect blend of magnification, screen reading and braille to get the job done. If your sight deteriorates, or your task requires greater detail, with SuperNova you can: boost magnification, announce punctuation, replace difficult colours, increase verbosity, hear webpages, turn on braille. Choose the Magnifier & Screen Reader edition and be assured that SuperNova can grow with you and your sight, for life. Additional Information: Manufacturer: Dolphin Computer Access Ltd. SuperNova Documents and support: https://yourdolphin.com/en-gb/products/individuals/families/supernova Introduction video:','vision','Dolphin Computer Access Ltd.','','','https://at.mada.org.qa/technology/supernova/','https://at.mada.org.qa/technology/supernova/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/SuperNova.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T11:37:41.924Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_tactile-braille-tablet-insideone_2420072215937','Tactile Braille Tablet insideONE','Tactile Braille Tablet insideONE','','','Operating System: Other InsideONE is an unique product in the world, combining design, technological performance and haptic ergonomics, dedicated to visual impairment. Discover new ways to interact, through the in.Home© range of tactile softwares. A shared approach between sighted and blind people, in a world we all are concerned in, communication and creation in digital dialog. insideONE is the first braille tactile tablet in the world. Disabled people can’t remain on the fringes of this changi','','','','Operating System: Other InsideONE is an unique product in the world, combining design, technological performance and haptic ergonomics, dedicated to visual impairment. Discover new ways to interact, through the in.Home© range of tactile softwares. A shared approach between sighted and blind people, in a world we all are concerned in, communication and creation in digital dialog. insideONE is the first braille tactile tablet in the world. Disabled people can’t remain on the fringes of this changing. Time for adjustment and ease of use of this product, will transform your world into a deeply personal experience. Laptop becomes a tactile tablet. Additional Information: Manufacturer: InsideVision insideONE Tutorials and User Guide: https://insidevision.fr/tutorials_UK_01.html Video:','vision','InsideVision','','','https://at.mada.org.qa/technology/tactile-braille-tablet-insideone/','https://at.mada.org.qa/technology/tactile-braille-tablet-insideone/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/insidevision.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:41:31.920Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_orcam-myeye_2420072220279','OrCam MyEye','OrCam MyEye','','','Operating System: Other OrCam MyEye is a revolutionary voice activated device that attaches to virtually any glasses. It can instantly read to you text from a book, smartphone screen or any other surface, recognize faces, help you shop on your own, work more efficiently, and live a more independent life! OrCam MyEye conveys visual information audibly, in real-time and offline. Additional Information: Manufacturer: OrCam Tutorials and Video Guide: https://www.orcam.com/en/user-area/ OrCam MyEye I','','','','Operating System: Other OrCam MyEye is a revolutionary voice activated device that attaches to virtually any glasses. It can instantly read to you text from a book, smartphone screen or any other surface, recognize faces, help you shop on your own, work more efficiently, and live a more independent life! OrCam MyEye conveys visual information audibly, in real-time and offline. Additional Information: Manufacturer: OrCam Tutorials and Video Guide: https://www.orcam.com/en/user-area/ OrCam MyEye Introduction Video:','vision','OrCam','','','https://at.mada.org.qa/technology/orcam-myeye/','https://at.mada.org.qa/technology/orcam-myeye/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/OrCam-MyEye.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:41:07.935Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_openbook_2420072225429','OpenBook','OpenBook','','','Operating System: Windows OpenBook converts printed documents or graphic-based text into an electronic text format on your PC, using high-quality speech and the latest optical character recognition (OCR) technology. OpenBook is innovative software designed to enhance success for people who are blind or have low vision who need access to printed and electronic materials. OpenBook and the PEARL document camera create a complete scanning and reading system for work, home, and school. Support for Wi','','','','Operating System: Windows OpenBook converts printed documents or graphic-based text into an electronic text format on your PC, using high-quality speech and the latest optical character recognition (OCR) technology. OpenBook is innovative software designed to enhance success for people who are blind or have low vision who need access to printed and electronic materials. OpenBook and the PEARL document camera create a complete scanning and reading system for work, home, and school. Support for Windows® 8.1 and Windows 10. Convert printed text to natural, human-like speech in many languages. Powerful optical character recognition provides editable text. Scan bound books and maintain pagination. Powerful low vision features tailor the appearance of text on the screen, including font style, size, character spacing, and colors. Lightning-fast OCR with the PEARL document camera. Automatic page capture for efficient document acquisition. Versatile document navigation and management tools maximize your productivity. Additional Information: Manufacture: Freedom Scientific User Guide: https://support.freedomscientific.com/Content/Documents/Manuals/OpenBook/OB9Manual.txt Introduction Video','vision','','','','https://at.mada.org.qa/technology/openbook/','https://at.mada.org.qa/technology/openbook/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/openbook.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:41.016Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_topaz-series_2420072230819','Topaz Series','Topaz Series','','','Operating System: Other Topaz is a series of desktop magnifying system by Freedom Scientific. The TOPAZ OCR combines video magnification and text-to-speech features into a single desktop video magnifier. The high-definition camera produces a clear picture with sharp images and crisp text. The OCR camera displays a document on the touchscreen, and then TOPAZ processes, acquires, and reads aloud the document. The TOPAZ HD video magnifier is the perfect choice for reading and performing daily tasks','','','','Operating System: Other Topaz is a series of desktop magnifying system by Freedom Scientific. The TOPAZ OCR combines video magnification and text-to-speech features into a single desktop video magnifier. The high-definition camera produces a clear picture with sharp images and crisp text. The OCR camera displays a document on the touchscreen, and then TOPAZ processes, acquires, and reads aloud the document. The TOPAZ HD video magnifier is the perfect choice for reading and performing daily tasks, with a wide magnification range, gliding reading table, lots of workspace under the camera, LED lighting, and unique features like Find and Freeze Frame. TOPAZ EZ HD is simply uncomplicated magnification. This economical video magnifier emphasizes ease of use with single-function controls and a high-definition camera. The HD camera provides superior image quality, a wider field of view, and a lower magnification range. The lightweight TOPAZ® PHD offers the comfort and productivity features of a desktop video magnifier but folds away like a laptop. With auto-focus, a wide magnification range, intuitive controls, six default and 27 customizable high-contrast color modes, and adjustable reading lines and masks, the new TOPAZ PHD offers the freedom to independently read and view the details that matter in the home, office, classroom, or on the go. The TOPAZ Ultra is a portable magnifier with a unique folding design, making it extremely easy to take with you wherever you go. With crisp, full-HD images, available in a 15.6-inch or 17.3-inch screen, clearly see what you want, whether across the room or at your desk. The monitor height is fully adjustable, ensuring you always have the right reading angle. And its compact size lets you store it when not in use. The ultimate desktop video magnifier, TOPAZ XL HD provides high-definition magnification with the sharpest image and the crispest text, allowing for low magnification levels that fit more text on the screen for faster reading and better comprehension with less fatigue. With its extra features and computer connectivity, TOPAZ XL HD is the video magnifier of choice for those looking for maximum productivity in work and school environments. Additional Information: Manufacturer: Freedom Scientific Topaz Family User Guide: https://support.freedomscientific.com/Products/LowVision/TOPAZProductDocumentation Video:','vision','Freedom Scientific','','','https://at.mada.org.qa/technology/topaz-series/','https://at.mada.org.qa/technology/topaz-series/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/TOPAZ_OCR.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:41:42.301Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_pearl_2420072235888','Pearl','Pearl','','','Operating System: Other The PEARL, combined with JAWS, Fusion, or OpenBook scanning and reading software, brings blind and low vision users instant portable access to printed material with an array of human-sounding voices. The folding camera deploys in seconds to connect to your PC and snap a picture of your reading material and begins reading it aloud instantly. In automatic mode, the PEARL senses motion, so it knows to snap an image and begin reading again whenever you turn a page. The PEARL ','','','','Operating System: Other The PEARL, combined with JAWS, Fusion, or OpenBook scanning and reading software, brings blind and low vision users instant portable access to printed material with an array of human-sounding voices. The folding camera deploys in seconds to connect to your PC and snap a picture of your reading material and begins reading it aloud instantly. In automatic mode, the PEARL senses motion, so it knows to snap an image and begin reading again whenever you turn a page. The PEARL sets up in seconds and folds into a compact 14”x 3”x 2 1/8” package, and zips into its protective neoprene case for maximum portability. Additional Information: Manufacture: Freedom Scientific User Guide: https://support.freedomscientific.com/downloads/documentation Introduction Video:','vision','','','','https://at.mada.org.qa/technology/pearl/','https://at.mada.org.qa/technology/pearl/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/PEARL.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:50.991Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_onyx-deskset-hd_2420072239752','ONYX® Series','ONYX® Series','','','Operating System: Other The ONYX® by Freedom Scientific is a series of low vision magnifying system. The ONYX Deskset HD is a portable video magnifier that adapts to multiple environments and tasks for productivity at school, work, and at home. The new sleek design integrates a high-definition camera and monitor to let you clearly see what you want, whether it’s across the room or at your desk. The 3-in-1 flexible camera provides document reading, distance viewing, and self-viewing modes with ve','','','','Operating System: Other The ONYX® by Freedom Scientific is a series of low vision magnifying system. The ONYX Deskset HD is a portable video magnifier that adapts to multiple environments and tasks for productivity at school, work, and at home. The new sleek design integrates a high-definition camera and monitor to let you clearly see what you want, whether it’s across the room or at your desk. The 3-in-1 flexible camera provides document reading, distance viewing, and self-viewing modes with versatile controls. The ONYX OCR magnifies and reads aloud any document. The clear voice, magnification and high contrast makes reading so much easier. Comfortably change your focus from reading magnified texts yourself, to letting the ONYX OCR read them to you when reading becomes too tiring. Just place your document under the fixed OCR camera on the left and activate the speech function. Enjoy listening to any document as it is read aloud by a high quality voice, without straining your eyes. This four-in-one solution integrates two separate cameras: one for transforming text to speech output and one for magnifying documents and observing the room around you. This way, you can clearly see what you want, whether it is across the room or at your desk! Turn your Microsoft® Surface Pro 7 into and magnifier and screen reader with the ONYX® Pro. The ONYX® PRO uses a simple USB cable to connect to a Surface Pro 7 and magnifies objects, text, or images. When in OCR mode, you can follow the magnified text in high-contrast colors on the tablet screen. Additional Information: Manufacture: Freedom Scientific ONYX Product Family User Guides and Support: https://support.freedomscientific.com/Products/LowVision/ONYXDocumentation','vision','','','','https://at.mada.org.qa/technology/onyx-deskset-hd/','https://at.mada.org.qa/technology/onyx-deskset-hd/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/ONYX®-Deskset-HD.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:39.003Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_omnireader_2420072244523','omniReader','omniReader','','','Operating System: Other The omniReader® reads printed text to you by pressing a single button. You can follow the magnified text in high-contrast colors on the built-in screen, or simply listen as the omniReader reads text out loud. You can also use the screen to instantly magnify objects and text and display them in high-contrast colors to see them more clearly. Thanks to its lightweight design, built-in handle, and long battery life, you can pick it up and use it wherever user requires includi','','','','Operating System: Other The omniReader® reads printed text to you by pressing a single button. You can follow the magnified text in high-contrast colors on the built-in screen, or simply listen as the omniReader reads text out loud. You can also use the screen to instantly magnify objects and text and display them in high-contrast colors to see them more clearly. Thanks to its lightweight design, built-in handle, and long battery life, you can pick it up and use it wherever user requires including at home, at the office, and even on-the-go. It is a lightweight, portable scanning and reading solution that helps those who are blind or have low vision retain the pleasure of reading. Simply press a button and the omniReader® reads printed text aloud or you can follow along with the magnified text in high-contrast colors on the built-in screen. You can also use the screen to instantly magnify objects to see them more clearly. Additional Information: Manufacture: Freedom Scientific User Guide: https://support.freedomscientific.com/content/Documents/Manuals/omniReader/omniReader_UserGuide.pdf','vision','','','','https://at.mada.org.qa/technology/omnireader/','https://at.mada.org.qa/technology/omnireader/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/omniReader.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:18:26.069Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_focus-14-blue-5th-gen_2420072248994','Focus 14 Blue 5th Gen','Focus 14 Blue 5th Gen','','','Operating System: Other The Focus 14 Blue 5th Generation is a compact and robust 14-cell Braille Display drop tested to MIL-STD-810G and ready to go with you anywhere. It features a comfortable user-friendly 8-dot keyboard and Bluetooth 4.1 and USB-C connectivity so that user can switch between five connected devices. The 5th Generation of the Focus 14 Blue Braille Display is more rugged and stronger than ever. We’ve built the housing from aluminum and steel, added bumpers to absorb shock, and p','','','','Operating System: Other The Focus 14 Blue 5th Generation is a compact and robust 14-cell Braille Display drop tested to MIL-STD-810G and ready to go with you anywhere. It features a comfortable user-friendly 8-dot keyboard and Bluetooth 4.1 and USB-C connectivity so that user can switch between five connected devices. The 5th Generation of the Focus 14 Blue Braille Display is more rugged and stronger than ever. We’ve built the housing from aluminum and steel, added bumpers to absorb shock, and physically isolated the Braille cells to create a Braille Display to meet the demands of the active user. The Focus 14 Blue combines comfort, portability, and advanced features for the ultimate go-anywhere Braille interface device. A highly responsive 8-dot keyboard and seamless USB-C and Bluetooth® 4.1 connectivity make the Focus 14 Blue the ideal companion for smartphones, iPads®, tablets and other mobile devices. The new Scratchpad feature lets user to take notes and read books even when they aren’t connected. Additional Information: Manufacture: Freedom Scientific (https://www.freedomscientific.com/products/blindness/focus14brailledisplay/) User Guide: https://www.freedomscientific.com/Content/Documents/Manuals/Focus/Focus-Blue-Users-Guide.pdf Video:','vision','','','','https://at.mada.org.qa/technology/focus-14-blue-5th-gen/','https://at.mada.org.qa/technology/focus-14-blue-5th-gen/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Focus-14-Blue-5th-Gen.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:20.746Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_elbraille-40-5th-gen_2420072253559','ElBraille 40® 5th Gen','ElBraille 40® 5th Gen','','','Operating System: Other The ElBraille is a portable device designed for users who are blind or deaf-blind and want to stay connected at school, work, or home as well as on the go. This take anywhere replacement for the dedicated notetaker, ElBraille combines the flexibility of a modern mainstream computer running the Windows® 10 operating system with JAWS® and a 40-cell Braille display with a full Braille keyboard to offer a fully accessible compact solution. (JAWS and Braille display sold separ','','','','Operating System: Other The ElBraille is a portable device designed for users who are blind or deaf-blind and want to stay connected at school, work, or home as well as on the go. This take anywhere replacement for the dedicated notetaker, ElBraille combines the flexibility of a modern mainstream computer running the Windows® 10 operating system with JAWS® and a 40-cell Braille display with a full Braille keyboard to offer a fully accessible compact solution. (JAWS and Braille display sold separately.) Students and professionals alike will appreciate being able to run any Windows application such as Microsoft Word®, Excel®, PowerPoint®, or Outlook®. Use FSReader to read DAISY books from sources such as Bookshare.org or browse the internet with Microsoft Internet Explorer®, Google Chrome® or Mozilla® Firefox. Additional Information: Manufacture: Freedom Scientific (https://www.freedomscientific.com/products/blindness/elbraille40/) User Guide: https://support.freedomscientific.com/Content/Documents/Manuals/ElBraille/ElBraille-40-V-Users-Guide.pdf','vision','','','','https://at.mada.org.qa/technology/elbraille-40-5th-gen/','https://at.mada.org.qa/technology/elbraille-40-5th-gen/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/ElBraille-40®-5th-Gen.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:16.691Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_victor-reader-trek-talking-book-player-gps_2420072257110','Victor Reader Trek – talking book player & GPS','Victor Reader Trek – talking book player & GPS','','','Operating System: Other The VictorReader Trek combines the world renowned simple book reading and media playback experience of the VictorReader Stream with the navigation guidance technology found in the Trekker Breeze. With the press of one button, Trek will tell you your current nearest address, the direction you’re travelling and next instructions for the route you’re following. Simply drop a voice-tagged landmark and you can receive turn-by-turn directions to that exact point. Just press the','','','','Operating System: Other The VictorReader Trek combines the world renowned simple book reading and media playback experience of the VictorReader Stream with the navigation guidance technology found in the Trekker Breeze. With the press of one button, Trek will tell you your current nearest address, the direction you’re travelling and next instructions for the route you’re following. Simply drop a voice-tagged landmark and you can receive turn-by-turn directions to that exact point. Just press the toggle button to get back to your reading material exactly where you left off. Trek specialises when you are in open area! Navigating on a college campus or similar areas can be challenging if you are new to the environment. Trek offers options to make you feel immediately more comfortable. Drop voice tagged landmarks at each building you will be returning to and Trek will always provide you with instructions to navigate there, even when no streets are found. Travel with confidence knowing that your landmarks will always be your points of reference. Additional Information: Manufacture: Humanware (https://store.humanware.com/int/victor-reader-trek-talking-book-player-gps.html) User Guides: https://support.humanware.com/en-international/support/victor_reader_trek Victor Reader Trek Introduction Video:','vision','','','','https://at.mada.org.qa/technology/victor-reader-trek-talking-book-player-gps/','https://at.mada.org.qa/technology/victor-reader-trek-talking-book-player-gps/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Victor-Reader-Trek-–-talking-book-player.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:18:17.846Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_taptilo_2420072262145','Taptilo','Taptilo','','','Operating System: Other Taptilo is a smart braille learning device that makes braille learning fun and easy. Braille beginners can learn braille patterns independently with the interactive braille display and audio feedback. Along with the jumbo-sized braille blocks, tactile guidance, and audio guide, braille-beginners can easily follow pre-made curriculums in Taptilo. Braille beginners can learn braille fun and easy along with activities and games in Taptilo. Braille beginners can incorporate a','','','','Operating System: Other Taptilo is a smart braille learning device that makes braille learning fun and easy. Braille beginners can learn braille patterns independently with the interactive braille display and audio feedback. Along with the jumbo-sized braille blocks, tactile guidance, and audio guide, braille-beginners can easily follow pre-made curriculums in Taptilo. Braille beginners can learn braille fun and easy along with activities and games in Taptilo. Braille beginners can incorporate all senses to learn braille. With Self-Study Mode, braille beginners can get started learning braille within a second. Taptilo provides self-guided learning materials. Braille beginners can practice read, trace and write, and dictation systematically. Taptilo includes from dots to words, divided into categories. Taptilo can upload their own word list to the app, personalizing learning material. Taptilo app also offers various teaching options. Taptilo offers various languages (English, Korean, Arabic, Spanish, German and Portuguese). Additional Information: Manufacture: Taptilo (https://www.taptilo.com/taptilo) User Guide: https://www.taptilo.com/user-guide Taptilo Introduction Video','vision','','','','https://at.mada.org.qa/technology/taptilo/','https://at.mada.org.qa/technology/taptilo/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Taptilo.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:18:07.662Z',NULL,NULL,NULL);
