f Video:','vision','','','','https://at.mada.org.qa/technology/panda-hd/','https://at.mada.org.qa/technology/panda-hd/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Panda-HD.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:49.145Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_luna-s_2420072276427','Luna Series','Luna Series','','','Operating System: Other Luna S is a 4.3-inch handheld electronic magnifier upgrade from Snow video magnifier. It brings user crystal-clear images and some other great features in a compact body. Put Luna S in your pocket, and user are good to go: read menu, read books, listen to radio, check price tag up, everything everywhere. Luna S is a handy visual aid for everybody with low vision. Luna S, taking the advanced image processor and auto-focus camera, keeps the display sharp all the time. Even ','','','','Operating System: Other Luna S is a 4.3-inch handheld electronic magnifier upgrade from Snow video magnifier. It brings user crystal-clear images and some other great features in a compact body. Put Luna S in your pocket, and user are good to go: read menu, read books, listen to radio, check price tag up, everything everywhere. Luna S is a handy visual aid for everybody with low vision. Luna S, taking the advanced image processor and auto-focus camera, keeps the display sharp all the time. Even in the high contrast color modes or fast movement, the image is blur-free. As Luna S is used closely on the reading material, there is no light reflection or distortion. Every word displays bigger and clear. With the writing stand on the back of Luna S, you can write diary, sign the contract, bill or other documents. Writing stand can be folded when it’s not needed. Luna 8 is a handheld electronic video magnifier from Zoomax low vision aids. The compact body, lightweight design, and 8 hours extra long battery life is perfect for use everywhere. Whether reading a book or newspaper at home, using it to study for school, or taking it with user to work, Luna 8 is the perfect companion for magnifying things user want to see. Although Luna 8 is easy to use for reading, it is also highly functional for outdoor life. It’s light, and easy to carry around; it has distance viewing that enables you to see the menu board in restaurants, or the slides projected in the conference room. With extraordinary 8 hours battery life, Luna 8 is your perfect portable magnifier for continuous use. Additional Information: Manufacture: Zoomax Luna S User Guide: https://www.zoomax.com/wp-content/uploads/2021/01/Luna-S-brochure-web_version.pdf Luna 8 User Guide: https://www.zoomax.com/wp-content/uploads/2021/07/Luna-8-Electronic-Video-Magnifier-Brochure-web-version.pdf Video:','vision','','','','https://at.mada.org.qa/technology/luna-s/','https://at.mada.org.qa/technology/luna-s/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Luna-S-.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:35.284Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_acesight-vr_2420072280209','Acesight VR','Acesight VR','','','Operating System: Other The Acesight VR is a lightweight, high quality and easy to operate wearable magnifier. With the Acesight VR by Zoomax, you can regain visual independence. The device’s powerful visual technology helps you enjoy favorite indoor activities such as watching television and reading, as well as Acesight VR offers an incredibly smooth and bright image without any lag — perfect for watching your favorite television shows. Thanks to the 48 megapixel camera, the screen resolution i','','','','Operating System: Other The Acesight VR is a lightweight, high quality and easy to operate wearable magnifier. With the Acesight VR by Zoomax, you can regain visual independence. The device’s powerful visual technology helps you enjoy favorite indoor activities such as watching television and reading, as well as Acesight VR offers an incredibly smooth and bright image without any lag — perfect for watching your favorite television shows. Thanks to the 48 megapixel camera, the screen resolution is a remarkable 2340×1080, producing vivid, full HD images in extraordinary detail. Unlike some other wearables, the Acesight VR device stays cool during operation, even after 1-2 hours of continuous use. With the hands-free device, user can enjoy favorite indoor activities such as reading or watching your favorite television programs. Moreover, user will be able to look at the surroundings and see the faces of friends and loved ones with ease Additional Information: Manufacturer: AceSight (product page) User Guide: https://www.acesight.com/faq/faq-functions/ Video:','vision','AceSight','','','https://at.mada.org.qa/technology/acesight-vr/','https://at.mada.org.qa/technology/acesight-vr/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Acesight-VR.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:21:27.024Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_snow-12_2420072284182','Snow 12','Snow 12','','','Operating System: Other Zoomax Snow 12 is a portable electronic video magnifier that delivers true visual independence for people with low vision. With Snow 12, you can more easily read, write, look at objects or even perform full-page content scanning with OCR text-to-speech. With standard features like a 12″ full-HD display, magnification up to 19x, and a simple accessible interface, Snow 12 is perfect for all situations. It is designed to make life easier by adding an analog stick to allow us','','','','Operating System: Other Zoomax Snow 12 is a portable electronic video magnifier that delivers true visual independence for people with low vision. With Snow 12, you can more easily read, write, look at objects or even perform full-page content scanning with OCR text-to-speech. With standard features like a 12″ full-HD display, magnification up to 19x, and a simple accessible interface, Snow 12 is perfect for all situations. It is designed to make life easier by adding an analog stick to allow user to pan around a document without needing to move the reading material flexibilty. The foldable stand lifts Snow 12 off the table for times when user prefer to place reading materials or objects like a medicine bottle or small item underneath. The stand also makes it much easier to see what user is writing. 7 inches of Zoomax Snow 7 HD Plus is also available. Additional Information: Manufacture: ZooMax (https://www.zoomax.com/low-vision-products/12-inch-portable-video-magnifier-snow-12.html) User Guide: https://www.zoomax.com/wp-content/uploads/2019/07/Snow-12-Brochure.pdf Video:','vision','','','','https://at.mada.org.qa/technology/snow-12/','https://at.mada.org.qa/technology/snow-12/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/SNOW-12.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:59.392Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_irisvision-inspire_2420072289853','IrisVision Inspire','IrisVision Inspire','','','Operating System: Other IrisVision Inspire is a revolutionary assistive device designed to enhance independent daily living, facilitate virtual vision rehabilitation, and stay connected to people, doctors, and everyday activities. Inspire leverages IrisVision’s award-winning software in an all-new, lightweight headset designed for anyone with low vision who wants to live their vision for life by fully leveraging the vision they have. Inspire is a low-profile wearable software platform delivering','','','','Operating System: Other IrisVision Inspire is a revolutionary assistive device designed to enhance independent daily living, facilitate virtual vision rehabilitation, and stay connected to people, doctors, and everyday activities. Inspire leverages IrisVision’s award-winning software in an all-new, lightweight headset designed for anyone with low vision who wants to live their vision for life by fully leveraging the vision they have. Inspire is a low-profile wearable software platform delivering functional sight for low vision. From the team that developed the multiple award-winning IrisVision Live headset, Inspire is an all-in-one, all distance, and autofocus solution designed for intuitive ease-of-use. Only Inspire offers a growing software platform with two years of unlimited cellular data to keep users connected and supported wherever they are. Additional Information: Manufacture: IRIS VISION (https://irisvision.com/irisvision-inspire/) User Guide: https://hims-support.com/download-center/ Video:','vision','','','','https://at.mada.org.qa/technology/irisvision-inspire/','https://at.mada.org.qa/technology/irisvision-inspire/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/IV-Inspire-Device.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:29.336Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_blaze-et-reader_2420072294555','Blaze ET Reader','Blaze ET Reader','','','Operating System: Other Blaze ET sets a new standard for portable DAISY players. For the first time, blind and visually impaired consumers have access to pocket-sized book players integrated with OCR text-to-speech to capture and read aloud hardcopy printed documents on-demand. Use Blaze ET to OCR capture a menu, magazine article, library book, and more – all at the touch of a single button. The built-in auto-focus camera ensures a high-quality image for accurate OCR and text-to-speech. Easy to ','','','','Operating System: Other Blaze ET sets a new standard for portable DAISY players. For the first time, blind and visually impaired consumers have access to pocket-sized book players integrated with OCR text-to-speech to capture and read aloud hardcopy printed documents on-demand. Use Blaze ET to OCR capture a menu, magazine article, library book, and more – all at the touch of a single button. The built-in auto-focus camera ensures a high-quality image for accurate OCR and text-to-speech. Easy to find buttons for music, radio, books, OCR and recording give single touch access to each of these popular features. A familiar numeric keypad allows for more advance marking and navigation of files, and easy access controls on the side of the unit allow users to adjust pitch, rate and volume on the fly. Additional Information: Manufacturer: SELVAS BLV (product page, support page)','vision','SELVAS BLV','','','https://at.mada.org.qa/technology/blaze-et-reader/','https://at.mada.org.qa/technology/blaze-et-reader/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Blaze-EZ-Reader.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:21:36.848Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_compact-6-hd-wear_2420072298614','Compact 6 HD Wear','Compact 6 HD Wear','','','Operating System: Other Wearable device by Optelec: the Compact 6 HD Wear. With the Compact 6 HD Wear accessory, you can enjoy a 2-in-1 video magnifier that is both handheld. Use the Compact 6 HD on its own as a handheld magnifier to read texts and magnify objects, and lock it into the Wear to transform it into a wearable magnifier. With the Wear, you keep your hands free to work on daily activities such as writing, cooking and paying bills. The hands-free operation also allows for ultimate rela','','','','Operating System: Other Wearable device by Optelec: the Compact 6 HD Wear. With the Compact 6 HD Wear accessory, you can enjoy a 2-in-1 video magnifier that is both handheld. Use the Compact 6 HD on its own as a handheld magnifier to read texts and magnify objects, and lock it into the Wear to transform it into a wearable magnifier. With the Wear, you keep your hands free to work on daily activities such as writing, cooking and paying bills. The hands-free operation also allows for ultimate relaxation when watching TV, enjoying movies, or viewing photos. When used with the Compact 6 HD Speech, you can even enjoy hands-free text-to-speech! Just take a snapshot and listen as the Compact 6 HD Speech does the work. To start using the Compact 6 HD Wear, simply lock the Compact 6 HD Speech or Compact 6 HD into the Wear, and put it on your head. The Compact 6 HD Wear magnifies the full screen and brings it close to your eyes. It provides an 18” screen at a 25 cm / 10” distance and ensures comfortable viewing and minimal eye strain. Thanks to the full screen projection in both eyes, you will enjoy sharp images and panoramic views. Additional Information: Manufacture: Optelec ( https://in.optelec.com/products/compact-6-hd-wear.html) User Guide: https://in.optelec.com/downloads/IN/Optelec%20Compact%206%20HD% 20Wear%20User%20Manual_English.pdf','vision','','','','https://at.mada.org.qa/technology/compact-6-hd-wear/','https://at.mada.org.qa/technology/compact-6-hd-wear/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Compact-6-HD-Wear.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:10.499Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_optelec-clearreader_2420072302674','Optelec ClearReader+','Optelec ClearReader+','','','Operating System: Other Optelec ClearReader+ and ClearReader+ Basic, combining fast text-to-speech, a choice of high quality naturally sounding voices, and all in an attractive portable design. With the Optelec ClearReader+and ClearReader+ Basic accessing printed documents such as magazines, newspapers, books or a letter from a friend has never been easier. The Optelec ClearReader+ is portable and battery powered and can be used around the home, on holiday, at school or at work, making it ideal ','','','','Operating System: Other Optelec ClearReader+ and ClearReader+ Basic, combining fast text-to-speech, a choice of high quality naturally sounding voices, and all in an attractive portable design. With the Optelec ClearReader+and ClearReader+ Basic accessing printed documents such as magazines, newspapers, books or a letter from a friend has never been easier. The Optelec ClearReader+ is portable and battery powered and can be used around the home, on holiday, at school or at work, making it ideal for reading a recipe in the kitchen, a book in the library, today’s newspaper in the garden or reviewing bills. The Optelec ClearReader+ Basic offers all the benefits of the ClearReader+ without the facility of on-board rechargeable batteries. The Optelec ClearReader+ is easily adjusted to playback at a more comfortable reading speed and volume. You can even connect a separate set of headphones and listen discretely. Additional Information: Manufacture: Optelec (https://in.optelec.com/products/clearreader.html) User Guide: https://in.optelec.com/downloads/IN/Documentation/RFD-05937A_Optelec%20ClearReader%2B%20Advanced%20Features%20and%20Functions%20V1.0%20EN_NL_FR_IT_ES_DE.pdf','vision','','','','https://at.mada.org.qa/technology/optelec-clearreader/','https://at.mada.org.qa/technology/optelec-clearreader/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Optelec-ClearReader.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:43.267Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_clearview-c-24-hd-speech_2420072307979','ClearView C 24 HD Speech','ClearView C 24 HD Speech','','','Operating System: Other The new Optelec ClearView C Speech is a unique desktop video magnifier that is designed to improve your reading experience. Select your preferred reading voice and sit back, relax, and listen to documents as they are read aloud. Combining a clear voice with magnification or high contrast makes reading so much easier. The ClearView C Speech can instantly convert any printed text into speech. It makes it possible to have access to information in a way that is most comfortab','','','','Operating System: Other The new Optelec ClearView C Speech is a unique desktop video magnifier that is designed to improve your reading experience. Select your preferred reading voice and sit back, relax, and listen to documents as they are read aloud. Combining a clear voice with magnification or high contrast makes reading so much easier. The ClearView C Speech can instantly convert any printed text into speech. It makes it possible to have access to information in a way that is most comfortable and easy to you. Especially long texts are now easy to read. The ClearView C Speech displays full pages and automatically identifies the document layout. This ensures that you navigate quickly, you always know where you are and never lose your place. Additional Information: Manufacturer: Optelec (product page) Video:','vision','Optelec','','','https://at.mada.org.qa/technology/clearview-c-24-hd-speech/','https://at.mada.org.qa/technology/clearview-c-24-hd-speech/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/ClearView-C-24-HD-Speech.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:40:08.804Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_optelec-compact-10-hd-with-speech_2420072311442','Optelec Compact Series','Optelec Compact Series','','','Operating System: Other Optelec provides the Compact family of the portable magnifiers. The Compact 7 HD Portable Electronic Video Magnifier is a portable 7-inch widescreen video magnifier with high-definition image quality, extreme simplicity, and an attractive style. Integrating the largest screen available in the Optelec Compact product family, it is still small enough to easily carry from one location to another. The high-contrast widescreen provides an increased field of view and the abilit','','','','Operating System: Other Optelec provides the Compact family of the portable magnifiers. The Compact 7 HD Portable Electronic Video Magnifier is a portable 7-inch widescreen video magnifier with high-definition image quality, extreme simplicity, and an attractive style. Integrating the largest screen available in the Optelec Compact product family, it is still small enough to easily carry from one location to another. The high-contrast widescreen provides an increased field of view and the ability to see even more of the material compared to traditional portable magnifiers. You can rely on the ultra-sharp high definition and auto-focus camera with a patented LED lighting system for even, glare-free illumination to deliver the best available image quality. Reading newspapers and letters or viewing photos at home, in the office, at school, or while traveling has never been easier—just point and snap for instant magnified viewing or capture an image to magnify and view later. The Compact 6 HD Speech is more than just another electronic magnifier. Being only half an inch thick, it is a pocket-sized, 6-inch touch screen magnifier that reads texts aloud, whether it is at your desk, at a store, at home, at school, or at the office. Just point the Compact 6 HD Speech magnifier at your document, take a picture and listen as the text is read aloud. The compact size will capture the image and read you the text in over 25 languages. With the Compact 6 HD Speech magnifier you can read magnified text in high contrast colors and view objects from a short distance. With the 6-inch screen, you can display more on the screen and maximize readability. Comes ready to use out of the box within seconds – magnifies instantly after you turn it on. Easy Mode is user-friendly, easy to use and is the default mode. Users will only see buttons they use the most: contrast, magnification, and camera switch. In Advanced Mode, users have access to more advanced buttons and options in addition to the ‘easy’ buttons, such as the Menu and Clock. In the Settings Menu, users have the option to configure the unit to their needs, for instance, color, buttons, dark or light theme, Miracast, etc. Compact HD is a magnifier with its large 10” screen, customizable features, intuitive operation, and full page Text-to-Speech, the Compact 10 HD Speech offers all benefits of a desktop video magnifier, but in a much smaller, foldable, and portable design. The Compact 10 HD Speech magnifies newspapers, letters, and magazines for viewing of text, pictures, and other details. Its purposely designed swing-out arm opens a whole new range of possibilities. It allows the Compact 10 HD Speech to capture full-page documents and then read them to user with one press on the touchscreen. A convenient indicator at the foot of the Compact 10 HD Speech tells user exactly where to place the document to read. Just place the document, take a snapshot, and relax while the Compact 10 HD Speech reads text to user. With the arm unfolded, user can also look at photos, view packaging and product labels, and read round cans, all while holding objects naturally in the hand. Additional Information: Manufacture: Optelec (https://in.optelec.com/products/optelec-compact-10-hd-speech.html#overview) User Guide: https://in.optelec.com/downloads/IN/Compact%2010%20HD/UDC-02336A_Optelec%20Compact%2010%20HD%20User%20Manual%20EN_NL_FR_IT_ES_DE_V1.4.pdf Video:','vision','','','','https://at.mada.org.qa/technology/optelec-compact-10-hd-with-speech/','https://at.mada.org.qa/technology/optelec-compact-10-hd-with-speech/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/optelec-compact.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:45.321Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_index-braillebox-v5_2420072316621','Index BrailleBox V5','Index BrailleBox V5','','','Operating System: Other BrailleBox is a Braille printer for high volumes of braille production. Create hassle-free braille books instantly with this cut sheet fed embosser. Print braille books with BrailleBox using A3 (or 11×17 inch) paper in booklet format. The pages are printed and pile in page order, fold along the centered braille line and you have a ready braille book. Economically emboss braille using BrailleBox V5’s sheet fed technology. New to BrailleBox V5 the door has shifted from manu','','','','Operating System: Other BrailleBox is a Braille printer for high volumes of braille production. Create hassle-free braille books instantly with this cut sheet fed embosser. Print braille books with BrailleBox using A3 (or 11×17 inch) paper in booklet format. The pages are printed and pile in page order, fold along the centered braille line and you have a ready braille book. Economically emboss braille using BrailleBox V5’s sheet fed technology. New to BrailleBox V5 the door has shifted from manual, to automatic by simply pressing the DOOR key on the front panel of the embosser. The efficient printing speed on this paper is lower than 900 pages per hour. This because less hammers are used and more time are used for paper handling. The control panel is a local user interface which allows the user to interact with the braille embosser and provides complete embosser control. Additional Information: Manufacture: Index (https://www.indexbraille.com/en-us/braille-embossers/braillebox-v5?c=EUR0 User Guide: https://www.indexbraille.com/getmedia/b542b3c3-042f-466c-9ce3-69d13d612d94/Catalogue-V5-Embossers.pdf?ext=.pdf Video:','vision','','','','https://at.mada.org.qa/technology/index-braillebox-v5/','https://at.mada.org.qa/technology/index-braillebox-v5/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Index-BrailleBox.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:27.204Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_humanware-explore-series_2420072320878','HumanWare explorē Magnifiers','HumanWare explorē Magnifiers','','','Operating System: Other The Explorē Series by HumanWare is its most portable line of (HD) High Definition handheld electronic magnifiers: there are 3 versions, the Explorēr 5, 8, and 12. Explorē 5 is a lightweight portable cctv that can be used anywhere to magnify small print or images from 2X up to 22X. This unit will enlarge and sharpen text and it will allow you to change the contrast and color enhancement of whatever you are reading or viewing. This is the lightest and simplest 5″ display po','','','','Operating System: Other The Explorē Series by HumanWare is its most portable line of (HD) High Definition handheld electronic magnifiers: there are 3 versions, the Explorēr 5, 8, and 12. Explorē 5 is a lightweight portable cctv that can be used anywhere to magnify small print or images from 2X up to 22X. This unit will enlarge and sharpen text and it will allow you to change the contrast and color enhancement of whatever you are reading or viewing. This is the lightest and simplest 5″ display portable electronic magnifier available. It has a retractable handle that can be opened sideways so that you can hold this unit in one hand as you would a normal lens magnifier. The Explorē can also be used hands-free if you open the handle vertically and stand the Explorē directly upon your reading or viewing material. For more about Explorer 5, visit this link. Explorē 8 is a smart, portable, touch-screen, two-camera tablet, designed with the user in mind. The unmatched clarity of image with the most powerful camera on the market. Easy to use, intuitive use, and one-touch buttons to activate features. Light, portable, customizable. This is the perfect electronic video magnifier for anyone with low vision and age-related macular degeneration. The explorē 8 features two 21-megapixel cameras—one for things less than 15 cm away like documents, books, and newspapers, and a second camera for distance viewing away to see things like street and store signs. The device boasts the largest screen in the smallest package, designed with the latest technology, innovative features, and an easy to use the touchscreen for unmatched mobility, comfort, and convenience wherever you go. For more about Explore 8, visit this link. Explorē 12 is an easy-to-use, portable electronic magnifier that offers HD image quality for improved near and distance viewing. As the largest portable magnifier in our explorē series, its 12-inch touchscreen is perfect for anyone desiring a larger interface, plus it has the added benefit of a foldable stand enabling easy use for reading, writing, and other manual tasks. For more about Explorer 12, visit this link. Additional Information: Manufacturer: HumanWare (store page) User Guide: https://support.humanware.com/en-international/support/explore Explore 8 Introduction Video:','vision','HumanWare','','','https://at.mada.org.qa/technology/humanware-explore-series/','https://at.mada.org.qa/technology/humanware-explore-series/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Explore-8.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:40:37.395Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_connect-12-electronic-magnifier_2420072324404','Connect 12 electronic magnifier','Connect 12 electronic magnifier','','','Operating System: Other Connect 12 combines a high-performance digital magnifier with the versatility of a tablet, plus unmatched ease of use and integrated access to newspapers or magazines from online libraries. This ideal solution for active seniors, students and professionals, allows free and open access to more than a million apps. Smarter and more connected than all other low-vision products, HumanWare’s Connect 12 is the evolution of the most advanced digital magnifier product line. The n','','','','Operating System: Other Connect 12 combines a high-performance digital magnifier with the versatility of a tablet, plus unmatched ease of use and integrated access to newspapers or magazines from online libraries. This ideal solution for active seniors, students and professionals, allows free and open access to more than a million apps. Smarter and more connected than all other low-vision products, HumanWare’s Connect 12 is the evolution of the most advanced digital magnifier product line. The new simple interface gives you all the tools you need in one place allowing you to choose what you want to do: enlarge a printed document, read a book, newspaper or magazine, adjust for your visual comfort, sign or fill a form and more. Augmenting the Connect’s renowned attributes with a set of outstanding features makes the Connect 12 a powerful tool for low-vision users, whether you’re at home or on the go. Additional Information: Manufacturer: HumanWare (product page, support hub) Video:','vision','HumanWare','','','https://at.mada.org.qa/technology/connect-12-electronic-magnifier/','https://at.mada.org.qa/technology/connect-12-electronic-magnifier/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/connect_12.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:40:17.136Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_reveal-16-full-hd-digital-magnifier-with-xy-table_2420072329700','Reveal 16 Full HD digital magnifier with XY table','Reveal 16 Full HD digital magnifier with XY table','','','Operating System: Other Reveal 16 is an intuitive, easy to use and foldable digital magnifier that offers an unmatched crisp, and crystal-clear image quality thanks to its 10x optical zoom camera. Designed for seniors and elementary students, it enables to read documents, textbooks and newspapers as well as to write down notes. Reveal 16 also allows you to view distant objects like an artwork, your own backyard or even the whiteboard. With only 4 buttons and a user-friendly interface, it is the ','','','','Operating System: Other Reveal 16 is an intuitive, easy to use and foldable digital magnifier that offers an unmatched crisp, and crystal-clear image quality thanks to its 10x optical zoom camera. Designed for seniors and elementary students, it enables to read documents, textbooks and newspapers as well as to write down notes. Reveal 16 also allows you to view distant objects like an artwork, your own backyard or even the whiteboard. With only 4 buttons and a user-friendly interface, it is the simplest magnifying solution. Reveal 16 will make reading enjoyable again, even for long periods of time, without tiring your eyes thanks to its large 16-inch screen delivering an uncompromised image quality. Reveal 16 allows you to clearly see objects at distance like an artwork or your grandchild playing with his friends outside. Simply point the camera in the right direction. Additional Information: Manufacture: Human Ware (https://store.humanware.com/int/reveal-16-full-hd-digital-magnifier-with-xy-table.html) User Guide: https://support.humanware.com/en-international/support/reveal_16','vision','','','','https://at.mada.org.qa/technology/reveal-16-full-hd-digital-magnifier-with-xy-table/','https://at.mada.org.qa/technology/reveal-16-full-hd-digital-magnifier-with-xy-table/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Reveal-16-Full-HD-digital-magnifier.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:55.552Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_piaf-tactile-braille-printer_2420072333506','Piaf Tactile braille printer','Piaf Tactile braille printer','','','Operating System: Other Piaf produces high quality tactile graphics using heat sensitive capsule paper. It is ideal for people who are blind and vision impaired. Piaf’s controlled heat source causes any black lines, letters or shapes that are drawn, printed or copied onto the capsule paper to swell. The result is an instant tactile graphic. It is especially effective when used with the Tangible Magic Paper. This paper with its superb characteristics allows the user to run it through the PIAF mul','','','','Operating System: Other Piaf produces high quality tactile graphics using heat sensitive capsule paper. It is ideal for people who are blind and vision impaired. Piaf’s controlled heat source causes any black lines, letters or shapes that are drawn, printed or copied onto the capsule paper to swell. The result is an instant tactile graphic. It is especially effective when used with the Tangible Magic Paper. This paper with its superb characteristics allows the user to run it through the PIAF multiple times without compromising the quality of what has already been puffed up. This feature makes producing and handling tactile images more interactive and dynamic. Piaf is being used in a variety of educational, employment and personal settings. In early education Piaf can be used to introduce simple shapes and basic concepts; to introduce the concept of drawing and two-dimensional rendering of solid objects; to encourage students in taking the first tentative steps to expressing themselves graphically; and to teach the concepts of handwriting and signatures. Later, Piaf can be used to access graphical information in nearly all subject areas especially Mathematics and Sciences. Additional Information: Manufacture: HARPO PIAF (https://piaf-tactile.com/piaf/) User Guide: https://piaf-tactile.com/docs/Piaf.pdf Video:','vision','','','','https://at.mada.org.qa/technology/piaf-tactile-braille-printer/','https://at.mada.org.qa/technology/piaf-tactile-braille-printer/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Piaf-Tactile-braille-printer.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:53.136Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_code-jumper_2420072338617','Code Jumper','Code Jumper','','','Operating System: Windows Code Jumper is an incredible innovation that teaches students who are blind or visually impaired computer coding. By putting the block code tactually in your hands, all students can learn together in an inclusive setting. Originally designed by Microsoft® and developed by APH, this educational toy bridges the skills gap and opens up the world of coding to every student. Children not only learn basic programming concepts, such as sequence, iteration, selection, and varia','','','','Operating System: Windows Code Jumper is an incredible innovation that teaches students who are blind or visually impaired computer coding. By putting the block code tactually in your hands, all students can learn together in an inclusive setting. Originally designed by Microsoft® and developed by APH, this educational toy bridges the skills gap and opens up the world of coding to every student. Children not only learn basic programming concepts, such as sequence, iteration, selection, and variables, but will also be encouraged to think computationally, such as solving the same challenge in multiple ways. Most important, any teacher can facilitate Code Jumper lessons without prior computer science experience, and Code Jumper is inclusive of all children across the vision spectrum. Specially developed classroom curriculum (19 lessons representing 25 hours of classroom instruction). The lessons include unplugged activities, guided activities, tutorial videos and exploration time. The curriculum also encourages use of a computer science journal. The lessons span a full range of skills from the basics of computer programming to more complex topics, like topographies and binary numbers. Each lesson includes an unguided activity, a Code Jumper guided activity, exploration time, tutorial videos, journaling and an assessment. Additional Information: Manufacturer: APH (official website, APH store page, learning resources) Video:','vision','','','','https://at.mada.org.qa/technology/code-jumper/','https://at.mada.org.qa/technology/code-jumper/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Code-Jumper.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:07.664Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_braillenote-touch-32-plus_2420072342218','BrailleNote Touch 32 Plus','BrailleNote Touch 32 Plus','','','Operating System: Other BrailleNote Touch, the note taker of the future. It is a braille tablet that features a 32-cell braille display along with onboard speech. The BrailleNote Touch interface is easy to learn for both students and teachers, combining the benefits of KeySoft and braille literacy of a traditional note taker with the efficiency and power of a modern tablet. A powerful combination of accessibility and efficiency.The KeySoft user experience with the power of an Android operating s','','','','Operating System: Other BrailleNote Touch, the note taker of the future. It is a braille tablet that features a 32-cell braille display along with onboard speech. The BrailleNote Touch interface is easy to learn for both students and teachers, combining the benefits of KeySoft and braille literacy of a traditional note taker with the efficiency and power of a modern tablet. A powerful combination of accessibility and efficiency.The KeySoft user experience with the power of an Android operating system. Linear, user-friendly menu and interface. Supports perfect braille translation in contracted or uncontracted braille, including UEB and multiple languages. First certified Braille Tablet providing Play Store access. Supports Google Play store for accessible third party apps Additional Information: Manufacturer: HumanWare (product page, support page) Video:','vision','HumanWare','','','https://at.mada.org.qa/technology/braillenote-touch-32-plus/','https://at.mada.org.qa/technology/braillenote-touch-32-plus/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/BrailleNote-Touch-32-Plus.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:21:38.823Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_brailliant-80-braille-display_2420072347159','Brailliant 80 braille display','Brailliant 80 braille display','','','Operating System: Other HumanWare’s Brailliant 80 display is designed for extensive reading with the full comfort and intuitive display navigation of HumanWare’s signature thumb keys. This new generation of Brailliant braille displays features the excellent, sharp and crisp braille cell technology that users have praised on the BrailleNote Apex. Compact, sturdy, and durable, the Brailliant 80 ergonomically fits in front of your laptop or desktop keyboard. Built with lightweight, long lasting alu','','','','Operating System: Other HumanWare’s Brailliant 80 display is designed for extensive reading with the full comfort and intuitive display navigation of HumanWare’s signature thumb keys. This new generation of Brailliant braille displays features the excellent, sharp and crisp braille cell technology that users have praised on the BrailleNote Apex. Compact, sturdy, and durable, the Brailliant 80 ergonomically fits in front of your laptop or desktop keyboard. Built with lightweight, long lasting aluminum housing, the Brailliant 80 will stand up to daily wear and tear. Additional Information: Manufacture: Humanware (https://store.humanware.com/int/brailliant-80.html) User Guides: https://support.humanware.com/en-international/support/brailliant_and_brailleconnect','vision','','','','https://at.mada.org.qa/technology/brailliant-80-braille-display/','https://at.mada.org.qa/technology/brailliant-80-braille-display/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Brailliant-80-braille-display.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:01.572Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_brailliant-bi-20x_2420072351474','Brailliant BI 20X','Brailliant BI 20X','','','Operating System: Other Brailliant BI 20X is a smart and compact 20–cell refreshable braille display designed to bring you mobility, comfort, and efficiency at all times. By allowing you to speak the word under the cursor and announce an unfamiliar word, the text-to-speech feature promotes braille proficiency, making it easier to switch from uncontracted to contracted braille. You can customize the main menu, configure the thumb keys, select the braille table, and adjust the auto-scroll speed to','','','','Operating System: Other Brailliant BI 20X is a smart and compact 20–cell refreshable braille display designed to bring you mobility, comfort, and efficiency at all times. By allowing you to speak the word under the cursor and announce an unfamiliar word, the text-to-speech feature promotes braille proficiency, making it easier to switch from uncontracted to contracted braille. You can customize the main menu, configure the thumb keys, select the braille table, and adjust the auto-scroll speed to suit your reading preferences and maximize your comfort. HumanWare’s signature thumb keys make reading effortless, while the KeySoft Lite editing application makes discreet note taking a pleasure. With 16GB of usable internal storage and the included onboard translation ensuring compatibility with various file types, managing data has never been easier. Once paired with your screen reader via Bluetooth or USB connections, emailing, saving, and transferring documents of various file types couldn’t be easier. Since smart things come in small packages, the Brailliant BI 20X is your ideal braille travel companion. Additional Information: Manufacturer: HumanWare (product page, support page)','vision','HumanWare','','','https://at.mada.org.qa/technology/brailliant-bi-20x/','https://at.mada.org.qa/technology/brailliant-bi-20x/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/brailliant_bi_20x_-_dsc00285-lr.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:40:06.931Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_mantis-q40_2420072356163','Mantis Q40','Mantis Q40','','','Operating System: Other Mantis™ Q40 is a Bluetooth keyboard and 40-cell refreshable braille display. With the Mantis Q40, users no longer need to choose between a keyboard or a braille device – at the same time a student or professional is typing on the Mantis, the refreshable braille below the keyboard is providing a multimodal braille complement to the screen reader, making it easier to participate in, and succeed at, school or work. Additional Information: Manufacture: HumanWare (product page','','','','Operating System: Other Mantis™ Q40 is a Bluetooth keyboard and 40-cell refreshable braille display. With the Mantis Q40, users no longer need to choose between a keyboard or a braille device – at the same time a student or professional is typing on the Mantis, the refreshable braille below the keyboard is providing a multimodal braille complement to the screen reader, making it easier to participate in, and succeed at, school or work. Additional Information: Manufacture: HumanWare (product page) User Guides: https://support.humanware.com/index.php?Action=Page.Link&PageLink=6&ItemLink=5010&To=Site%2FFiles%2Fa%2F06cc20404d351cbaa2520fcd0d5adc3%2Fe18f036980835823aa1d60b08a86f60c%2FBI%252020X%2520EN-GSG%2520Rev-01.docx','vision','','','','https://at.mada.org.qa/technology/mantis-q40/','https://at.mada.org.qa/technology/mantis-q40/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Mantis-Q40.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:37.117Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_desmos-accessible-calculator_2420072361431','Desmos Accessible Calculator','Desmos Accessible Calculator','','','Operating System: Windows, iOS, Android, Chrome Desmos is online calculators, which include a four-function, scientific, and graphing calculator, are available free to the public. The online calculators can be accessed with a computer, tablet, or other personal device. Also Desmos apps can be downloaded to iOS or Android devices. Desmos provides accessibility features, such as accessible by screen readers, audio tracing to hear a single function or the entire equations, or keyboard shortcuts for','','','','Operating System: Windows, iOS, Android, Chrome Desmos is online calculators, which include a four-function, scientific, and graphing calculator, are available free to the public. The online calculators can be accessed with a computer, tablet, or other personal device. Also Desmos apps can be downloaded to iOS or Android devices. Desmos provides accessibility features, such as accessible by screen readers, audio tracing to hear a single function or the entire equations, or keyboard shortcuts for ease access. Additional Information: Manufacturer: Desmos (official website) Desmos Support at https://help.desmos.com/hc/en-us Desmos introduction video','vision','Desmos','','','https://at.mada.org.qa/technology/desmos-accessible-calculator/','https://at.mada.org.qa/technology/desmos-accessible-calculator/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Desmos.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:40:19.476Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_kurzweil-3000_242007236526','Kurzweil 3000','Kurzweil 3000','','','Operating System: Windows, iOS, Chrome Kurzweil 3000 is a software designed for people with visual impairment. The program makes printed or electronic text readily available for people with vision loss. Kurzweil 3000 software can help individuals with ‘early vision loss, computer vision syndrome, and visual impairments such as macular degeneration and glaucoma as well users at home, at school or at work. Kurzweil 3000 provides highlighting a sentence, line or phrase in one color and each word in','','','','Operating System: Windows, iOS, Chrome Kurzweil 3000 is a software designed for people with visual impairment. The program makes printed or electronic text readily available for people with vision loss. Kurzweil 3000 software can help individuals with ‘early vision loss, computer vision syndrome, and visual impairments such as macular degeneration and glaucoma as well users at home, at school or at work. Kurzweil 3000 provides highlighting a sentence, line or phrase in one color and each word in another color as it is read aloud. In addition, it provides quick access to dictionaries, synonyms, and syllables. Furthermore, it has flexiable writing tools which students use while typing such as check-spelling or speak while typing. Moreover, it provides audible and visual access to web pages with Mozilla Firefox. Besides, it has delivery options such as stadalone for singel users, Network for users sharing same network, and USB flash drive. The product is also available in Professional Color or Black/ White as well as Learn Station (Read Only) versions. Additional Information: Manufacturer: Cambium Learning Group Kurzweil 3000 How-to-Guides: https://www.kurzweiledu.com/kurzweil-academy/kurzweil-academy.html','vision','Cambium Learning Group','','','https://at.mada.org.qa/technology/kurzweil-3000/','https://at.mada.org.qa/technology/kurzweil-3000/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Kurzweil-3000.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:40:49.099Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_talking-calculator_2420072370329','Talking Calculator','Talking Calculator','','','Operating System: Other A talking calculator has a built-in speech synthesizer that reads aloud each number, symbol, or operation key a user presses; it also vocalizes the answer to the problem. Additional Information: Manufacturer: Attainment Company (https://www.attainmentcompany.com)','','','','Operating System: Other A talking calculator has a built-in speech synthesizer that reads aloud each number, symbol, or operation key a user presses; it also vocalizes the answer to the problem. Additional Information: Manufacturer: Attainment Company (https://www.attainmentcompany.com)','vision','Attainment Company','','','https://at.mada.org.qa/technology/talking-calculator/','https://at.mada.org.qa/technology/talking-calculator/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Talking-Calculator.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:41:33.906Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_izoom-screen-magnifier-reader_2420072374398','iZoom Screen Magnifier / Reader','iZoom Screen Magnifier / Reader','','','Operating System: Windows iZoom is a software designed for people with visual impairment. The program allows seeing and hearing contents on the computer screen as well as providing access to applications, documents, PDF, email and the Internet. iZoom Screen Magnifier / Reader can help individuals with ‘early vision loss, computer vision syndrome, and visual impairments such as macular degeneration and glaucoma. iZoom has dual monitor support and is capable of magnifying the screen up to 36 times','','','','Operating System: Windows iZoom is a software designed for people with visual impairment. The program allows seeing and hearing contents on the computer screen as well as providing access to applications, documents, PDF, email and the Internet. iZoom Screen Magnifier / Reader can help individuals with ‘early vision loss, computer vision syndrome, and visual impairments such as macular degeneration and glaucoma. iZoom has dual monitor support and is capable of magnifying the screen up to 36 times; it also allows to choose which part of the screen is to be magnified with 8 different zooming modes. Color adaptation controls are available to help improve the clarity of the screen. It also provides enhanced locator capabilities to help the user to find the mouse on the desktop effortlessly. In addition to the screen reader, it has mouse echo which reads the text you point at as well as typing echo which speaks the letter you type. The product is also available in a USB portable version which allows individuals to carry iZoom everywhere. Additional Information: Manufacturer: trysight User Manual: https://trysight.com/wp-content/uploads/2019/08/a2d13c_d5eab4c38a4a47a9b58be832ec0d6923-1.pdf','vision','trysight','','','https://at.mada.org.qa/technology/izoom-screen-magnifier-reader/','https://at.mada.org.qa/technology/izoom-screen-magnifier-reader/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/iZoom-Screen-Magnifier-Reader.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:41:59.210Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_zoomtext-magnifier-reader_2420072378247','ZoomText Magnifier / Reader','ZoomText Magnifier / Reader','','','Operating System: Windows ZoomText Magnifier/Reader is a fully integrated magnification and reading program tailored for low-vision users. Magnifier/Reader enlarges and enhances everything on your computer screen, echoes your typing and essential program activity, and automatically reads documents, web pages, email. Additional Information: Manufacturer: Freedom Scientific ZoomText User Guide: https://www.freedomscientific.com/products/software/zoomtext/','','','','Operating System: Windows ZoomText Magnifier/Reader is a fully integrated magnification and reading program tailored for low-vision users. Magnifier/Reader enlarges and enhances everything on your computer screen, echoes your typing and essential program activity, and automatically reads documents, web pages, email. Additional Information: Manufacturer: Freedom Scientific ZoomText User Guide: https://www.freedomscientific.com/products/software/zoomtext/','vision','Freedom Scientific','','','https://at.mada.org.qa/technology/zoomtext-magnifier-reader/','https://at.mada.org.qa/technology/zoomtext-magnifier-reader/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/zoomtext.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:41:55.343Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_jaws_2420072383476','JAWS','JAWS','','','Operating System: Windows JAWS, Job Access With Speech, is the world’s most popular screen reader, developed for computer users whose vision loss prevents them from seeing screen content or navigating with a mouse. JAWS provides speech and Braille output for the most popular computer applications on your PC. You will be able to navigate the Internet, write a document, read an email and create presentations from your office, remote desktop, or from home. Additional Information: Manufacturer: Free','','','','Operating System: Windows JAWS, Job Access With Speech, is the world’s most popular screen reader, developed for computer users whose vision loss prevents them from seeing screen content or navigating with a mouse. JAWS provides speech and Braille output for the most popular computer applications on your PC. You will be able to navigate the Internet, write a document, read an email and create presentations from your office, remote desktop, or from home. Additional Information: Manufacturer: Freedom Scientific (product page)','vision','Freedom Scientific','','','https://at.mada.org.qa/technology/jaws/','https://at.mada.org.qa/technology/jaws/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Jaws.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:40:46.854Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_ruby_2420072387282','Ruby Series','Ruby Series','','','Operating System: Other Ruby is a magnifier that allows users with low vision to read, write, and magnify objects at any distance. The device is a high quality, full-color reading device for visually impaired users of all ages. The RUBY HD brings you crystal-clear images and advanced features in a compact, lightweight body with a 4.3-inch screen. Features include 20 high-contrast color modes, Reading Lines and Masks, Freeze Frame, and the ability to store and transfer images. The new RUBY 7 HD h','','','','Operating System: Other Ruby is a magnifier that allows users with low vision to read, write, and magnify objects at any distance. The device is a high quality, full-color reading device for visually impaired users of all ages. The RUBY HD brings you crystal-clear images and advanced features in a compact, lightweight body with a 4.3-inch screen. Features include 20 high-contrast color modes, Reading Lines and Masks, Freeze Frame, and the ability to store and transfer images. The new RUBY 7 HD has a larger screen, high-definition image, and enhanced functionality to meet the needs of today’s low vision consumers. The unique PivotCam™ camera offers a wide range of viewing modes for reading, writing, distance viewing, and even a mirror-image self-view. The RUBY 7 HD combines convenience and flexibility as the leader in the next generation of handheld video magnifiers. The RUBY XL HD has a larger screen and a high-definition camera for the sharpest possible image. RUBY XL HD has all the advanced features in RUBY HD, plus a built-in reading stand that holds the screen at a comfortable angle as you slide it across a page of text. Additional Information: Manufacturer: Freedom Scientific Ruby Family User Guides: https://support.freedomscientific.com/Products/LowVision/RubyProductDocumentation','vision','Freedom Scientific','','','https://at.mada.org.qa/technology/ruby/','https://at.mada.org.qa/technology/ruby/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/ruby7HD.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:41:25.990Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_varioultra-20_2420072391627','VarioUltra 20/40','VarioUltra 20/40','','','Operating System: Other VarioUltra is the smartest Braille device. Simply put, the ergonomic design of VarioUltra is beyond anything else. From the beautiful brushed aluminum housing, to the incredibly quiet and responsive Braille keyboard, to the crisp Braille cells that feel almost paper-like, VarioUltra is an experience to be enjoyed every day. VarioUltra was the first Braille display to support simultaneous connections with multiple devices. The beautiful brushed aluminum design makes VarioU','','','','Operating System: Other VarioUltra is the smartest Braille device. Simply put, the ergonomic design of VarioUltra is beyond anything else. From the beautiful brushed aluminum housing, to the incredibly quiet and responsive Braille keyboard, to the crisp Braille cells that feel almost paper-like, VarioUltra is an experience to be enjoyed every day. VarioUltra was the first Braille display to support simultaneous connections with multiple devices. The beautiful brushed aluminum design makes VarioUltra the lightest braille device in its class. The ergonomic braille keyboard is extremely quiet, and comfortable to type on. The Braille Notetaker apps include favorites such as a word processor, and PDF and Excel viewers. The superior quality of the Braille cells feels great. Additional Information: Manufacture: Baum Visio Braille (https://www.visiobraille.de/index.php?article_id=21&clang=2) User Guide: https://www.visiobraille.de/index.php?article_id=19&clang=2','vision','','','','https://at.mada.org.qa/technology/varioultra-20/','https://at.mada.org.qa/technology/varioultra-20/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/VarioUltra-20.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:18:13.541Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_index-evert-braille-embosser_2420072396567','Index Basic-D V5 Embosser','Index Basic-D V5 Embosser','','','Operating System: Other The latest edition of Index Braille’s Basic-D Braille printer brings new features such as Wi-fi connection, embossing from USB memory and support for printing from mobile devices. It can print up to 140 characters per second and emboss both sides of the sheet. (Note: As a Braille printer, the Basic-D works best with specialized Braille paper.) Additional Information: Manufacture: Index Braille (https://www.indexbraille.com/en-us/braille-embossers/basic-d-v5) User Guides: ','','','','Operating System: Other The latest edition of Index Braille’s Basic-D Braille printer brings new features such as Wi-fi connection, embossing from USB memory and support for printing from mobile devices. It can print up to 140 characters per second and emboss both sides of the sheet. (Note: As a Braille printer, the Basic-D works best with specialized Braille paper.) Additional Information: Manufacture: Index Braille (https://www.indexbraille.com/en-us/braille-embossers/basic-d-v5) User Guides: https://www.indexbraille.com/getmedia/b542b3c3-042f-466c-9ce3-69d13d612d94/Catalogue-V5-Embossers.pdf?ext=.pdf','vision','','','','https://at.mada.org.qa/technology/index-evert-braille-embosser/','https://at.mada.org.qa/technology/index-evert-braille-embosser/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Index-Basic-D-V5-Embosser.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:17:25.147Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_bonocle_2420072400728','BONOCLE','BONOCLE','','','Operating System: Other The Bonocle is a domestically-produced Braille screen reader and interface for iOS devices, designed with portability and versatility in mind. It boasts a symmetrical and ergonomic design based on computer mice for comfort and to minimize the learning curve for new users. The Bonocle can be used as a standalone device thanks to its built-in storage, and the refreshable Braille cell gives it added potential as a learning tool. Additional Information: Manufacturer: Bonocle ','','','','Operating System: Other The Bonocle is a domestically-produced Braille screen reader and interface for iOS devices, designed with portability and versatility in mind. It boasts a symmetrical and ergonomic design based on computer mice for comfort and to minimize the learning curve for new users. The Bonocle can be used as a standalone device thanks to its built-in storage, and the refreshable Braille cell gives it added potential as a learning tool. Additional Information: Manufacturer: Bonocle (https://bonocle.co) Video:','vision','Bonocle','','','https://at.mada.org.qa/technology/bonocle/','https://at.mada.org.qa/technology/bonocle/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Bonocle.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:21:33.208Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_wewalk-smart-cane_242007240525','WeWALK Smart Cane','WeWALK Smart Cane','','','Operating System: iOS, Android The WeWALK is a smart cane for the visually impaired, enhanced with an ultrasound sensor that detects suspended obstacles a conventional white cane can’t and the ability to provide directions through the companion mobile app. Additional Information: Manufacturer: WeWALK (https://wewalk.io/en/) Video:','','','','Operating System: iOS, Android The WeWALK is a smart cane for the visually impaired, enhanced with an ultrasound sensor that detects suspended obstacles a conventional white cane can’t and the ability to provide directions through the companion mobile app. Additional Information: Manufacturer: WeWALK (https://wewalk.io/en/) Video:','vision','WeWALK','','','https://at.mada.org.qa/technology/wewalk-smart-cane/','https://at.mada.org.qa/technology/wewalk-smart-cane/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Wewalk-smart-cane.jpeg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:41:53.388Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_tobii-dynavox-indi_2420072409145','Tobii Dynavox Indi','Tobii Dynavox Indi','','','Operating System: Windows Tobii Dynavox Indi was designed specifically for Augmentative and Alternative Communication (AAC) and comes with all of your needs fully integrated, like the intuitive and easy to use Snap software with capabilities that even go beyond speech communication – like Environmental Control Units (ECUs), Infrared (IR), access to social media, email, or texting. Direct touch and switch scanning access methods are compatible with Indi. Additional Information: Manufacturer: Tobi','','','','Operating System: Windows Tobii Dynavox Indi was designed specifically for Augmentative and Alternative Communication (AAC) and comes with all of your needs fully integrated, like the intuitive and easy to use Snap software with capabilities that even go beyond speech communication – like Environmental Control Units (ECUs), Infrared (IR), access to social media, email, or texting. Direct touch and switch scanning access methods are compatible with Indi. Additional Information: Manufacturer: Tobii Dynavox More Information at https://www.tobiidynavox.com/support-training/indi-7/','voice-and-speech','Tobii Dynavox','','','https://at.mada.org.qa/technology/tobii-dynavox-indi/','https://at.mada.org.qa/technology/tobii-dynavox-indi/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Tobii-Dynavox-Indi.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:42:56.011Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_proxtalker_2420072414803','ProxTalker','ProxTalker','','','Operating System: Other The Logan ProxTalker is is an exciting mid-tech communication device which uses RFID (radio frequency identification) technology to enable independent verbal picture communication for non-verbal people of all ages by retrieving vocabulary stored on sound tags to produce real words. This technology allows you to simply place any photo, symbol, or object on a sound tag card and have a voice! To trigger voice output place your sound tag card on any one of the 5 buttons and p','','','','Operating System: Other The Logan ProxTalker is is an exciting mid-tech communication device which uses RFID (radio frequency identification) technology to enable independent verbal picture communication for non-verbal people of all ages by retrieving vocabulary stored on sound tags to produce real words. This technology allows you to simply place any photo, symbol, or object on a sound tag card and have a voice! To trigger voice output place your sound tag card on any one of the 5 buttons and press and the ProxTalker device will say the appropriate sound, word or sentence. Additional Information: Mamufacturer: Logan Tech More information at https://logantech.com/pages/product-manuals','voice-and-speech','','','','https://at.mada.org.qa/technology/proxtalker/','https://at.mada.org.qa/technology/proxtalker/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Logan-ProxTalker.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:18:44.608Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_proxpad_242007241936','ProxPAD','ProxPAD','','','Operating System: Other The Logan ProxPAD is a single location communication and learning aid for persons with physical, visual, or cognitive impairments; it requires tangible objects or other site cues to initiate communication. The ProxPAD uses RFID (radio frequency identification) and gives a voice output and responds to touch or proximity frequency. The Touch mode requires your hand or sound tag to make contact with the blue surface of the ProxPAD while the Proximity mode allows you to swipe','','','','Operating System: Other The Logan ProxPAD is a single location communication and learning aid for persons with physical, visual, or cognitive impairments; it requires tangible objects or other site cues to initiate communication. The ProxPAD uses RFID (radio frequency identification) and gives a voice output and responds to touch or proximity frequency. The Touch mode requires your hand or sound tag to make contact with the blue surface of the ProxPAD while the Proximity mode allows you to swipe the sound card above the surface making it perfect for the person who has limited mobility or needs the ProxPAD mounted under a table or wheelchair tray. Additional Information: Manufacturer – Logan Tech More information at https://logantech.com/pages/product-manuals','voice-and-speech','','','','https://at.mada.org.qa/technology/proxpad/','https://at.mada.org.qa/technology/proxpad/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/ProxPAd.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:18:42.561Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_boardmaker_2420072423159','Boardmaker','Boardmaker','','','Operating System: Windows Boardmaker software supports learning and communication in the classroom, therapy room or home with this trove of customizable material, including access to over 45,000 Picture Communication Symbols® (PCS). Educators can save time with searchable, ready-made material and curricula for students of all ages and ability levels. Engage students more easily with activities that can be customized for their needs. Select from a diverse choice of PCS – designed to represent all','','','','Operating System: Windows Boardmaker software supports learning and communication in the classroom, therapy room or home with this trove of customizable material, including access to over 45,000 Picture Communication Symbols® (PCS). Educators can save time with searchable, ready-made material and curricula for students of all ages and ability levels. Engage students more easily with activities that can be customized for their needs. Select from a diverse choice of PCS – designed to represent all learners – in the world’s largest symbol library. Additional Information: Manufacturer: Tobii Dynavox (product page)','voice-and-speech','Tobii Dynavox','','','https://at.mada.org.qa/technology/boardmaker/','https://at.mada.org.qa/technology/boardmaker/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Boardmaker.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:42:09.241Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_clicker-8-english-and-arabic_24200724283','Clicker 8 (English and Arabic)','Clicker 8 (English and Arabic)','','','Operating System: Windows, iOS, Chrome Clicker 8 is upgraded version from Clicker 7, which is combining inclusive literacy tools on it. Clicker Grids enable pupils to write with whole words and phrases. Emerging writers build sentences word-by-word, while Word Banks provide scaffolding to support developing writers. Clicker 8’s new ‘Picturize’ button instantly adds pictures to any Clicker Grid, helping children to find the word they want. Choose from over 4500 Clicker curriculum pictures or use ','','','','Operating System: Windows, iOS, Chrome Clicker 8 is upgraded version from Clicker 7, which is combining inclusive literacy tools on it. Clicker Grids enable pupils to write with whole words and phrases. Emerging writers build sentences word-by-word, while Word Banks provide scaffolding to support developing writers. Clicker 8’s new ‘Picturize’ button instantly adds pictures to any Clicker Grid, helping children to find the word they want. Choose from over 4500 Clicker curriculum pictures or use your own. Make curriculum content accessible for all with talking Clicker Books, support emergent readers and EAL pupils with Matching Sets, and use Talk Sets to develop speaking and listening skills. Organising ideas is a vital first step in the writing process, and one that many learners struggle with. Clicker includes a child-friendly mind mapping area to help learners prepare for writing. Clicker includes free access to LearningGrids, an ever-growing bank of ready-made classroom resources created by our curriculum team. Additional Information: Manufacturer: Crick Software Clicker 8 Training and Support: https://www.cricksoft.com/uk/clicker/training-and-support Video','voice-and-speech','Crick Software','','','https://at.mada.org.qa/technology/clicker-8-english-and-arabic/','https://at.mada.org.qa/technology/clicker-8-english-and-arabic/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Clicker-8.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:42:12.181Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_inclusive-talking-photo-album-pro_2420072433629','Talking Photo Album','Talking Photo Album','','','Operating System: Other The Talking Photo Album is an easy-to-use speech output device with a total of 20 pages, each with an individual message capacity of 10 seconds. Great for talking stories, communication books, step-by-step instructions, memory books and personal information. Insert photos or picture/text cards into the transparent envelopes and record a corresponding message with up to 18 seconds of recording time on each page. Additional Information: Manufacturer: Attainment Company More','','','','Operating System: Other The Talking Photo Album is an easy-to-use speech output device with a total of 20 pages, each with an individual message capacity of 10 seconds. Great for talking stories, communication books, step-by-step instructions, memory books and personal information. Insert photos or picture/text cards into the transparent envelopes and record a corresponding message with up to 18 seconds of recording time on each page. Additional Information: Manufacturer: Attainment Company More information at Attainment’s Talking Photo Album User’s Guide (attainmentcompany.com)','voice-and-speech','Attainment Company','','','https://at.mada.org.qa/technology/inclusive-talking-photo-album-pro/','https://at.mada.org.qa/technology/inclusive-talking-photo-album-pro/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Inclusive-Talking-Photo-Album-Pro.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:42:43.605Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_gotalk-communication-devices_2420072438572','Gotalk Communication Devices','Gotalk Communication Devices','','','Operating System: Other GoTalk is an AAC device that supports those with limited to no speech throughout their daily activities. It comes many variations as discussed below: GoTalk One: Offers a large picture display and play button with easy set-up Slim and light-weight for transport Gotalk Pocket: Small enough to fit in your hand, pocket, and purse Records and stores 30 messages in five levels, on six buttons Attaches to a lanyard for a wearable communication device Pictures and vocal recordin','','','','Operating System: Other GoTalk is an AAC device that supports those with limited to no speech throughout their daily activities. It comes many variations as discussed below: GoTalk One: Offers a large picture display and play button with easy set-up Slim and light-weight for transport Gotalk Pocket: Small enough to fit in your hand, pocket, and purse Records and stores 30 messages in five levels, on six buttons Attaches to a lanyard for a wearable communication device Pictures and vocal recordings make this a highly customizable device and ideal for any language Pairs well with the GoTalk Overlay Software Gotalk 4: Records and stores up to 20 messages in five levels, up to 4.25 minutes in total Four programmable buttons allow the user to personalize each level with pictures and vocal recordings Includes two additional core buttons for frequently used words or phrases across levels Offers sequential recording for quick set-up and re-recording Pairs well with the GoTalk Overlay Software and carry stand Gotalk 9 +: Records and stores up to 45 messages in five levels, up to 8.25 minutes in total Nine programmable buttons allow the user to personalize each level with pictures and vocal recordings Includes three additional core buttons for frequently used words or phrases across levels Offers sequential recording for quick set-up and re-recording Pairs well with the GoTalk Overlay Software and carry stand GoTalk 20 +: Records and stores up to 100 messages in five levels, up to 15 minutes in total 20 programmable buttons allow the user to personalize each level with pictures and vocal recordings. Includes five additional core buttons for frequently used words or phrases across levels Offers sequential recording for quick set-up and re-recording Pairs well with the GoTalk Overlay Software and carry stand GoTalk Express 32: Records and stores 160 messages in five levels, eight seconds per message, up to eight messages in a sequence 32 programmable buttons allow the user to personalize each level with pictures and vocal recordings Includes the standard GoTalk function and express function Optional 1.5 second auditory cue for each button Pairs with GoTalk Overlay Software and GoTalk Carry Stand Includes convenient shoulder strap for transport GoTalk Dynamic: Ideal for any age and experience level Includes: GoTalk NOW Plus iPad App, an iPad Air, and GoNow Case for iPad Air Package GoTalk NOW Plus iPad App offers a flexible and powerful solution for personalized AAC needs Additional Information: Manufacturer: Attainment Company https://www.attainmentcompany.com/technology/gotalks Video:','voice-and-speech','Attainment Company','','','https://at.mada.org.qa/technology/gotalk-communication-devices/','https://at.mada.org.qa/technology/gotalk-communication-devices/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/gotalk-32.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:42:24.127Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_quick-talker-7_2420072442790','Quick talker Series','Quick talker Series','','','Operating System: Other A portable dedicated speech generating device that features 7-message locations and 6-minutes of record time. Simply switching between the five available recording levels provides up to 23-messages. Includes built-in carrying handle. Easy-to-use, go-anywhere communicator! With QuickTalker 7, your students will be ready to start communicating in minutes. The seven message locations, 6-minutes of total recording time, and five available levels provide the flexibility you ne','','','','Operating System: Other A portable dedicated speech generating device that features 7-message locations and 6-minutes of record time. Simply switching between the five available recording levels provides up to 23-messages. Includes built-in carrying handle. Easy-to-use, go-anywhere communicator! With QuickTalker 7, your students will be ready to start communicating in minutes. The seven message locations, 6-minutes of total recording time, and five available levels provide the flexibility you need to customize the learning outcomes for each student. It comes in different sizes with same features: QuickTalker 7, 12, 23 Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/) More information at https://ablenetinc.zendesk.com/hc/en-us/sections/360011783952-QuickTalker-FT Video:','voice-and-speech','AbleNet','','','https://at.mada.org.qa/technology/quick-talker-7/','https://at.mada.org.qa/technology/quick-talker-7/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Quick-talker-7.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:42:39.943Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_big-sbs_2420072447358','BIG Step-by-Step','BIG Step-by-Step','','','Operating System: Other Record a series of messages to this dedicated speech generating device and then activate the large 5-in/12.7-cm switch top to play each message back one at a time. Includes 2-minutes of record time and supports the use of an external switch for alternative methods of access. BIG STEP-BY-STEP FEATURES: Switch tops included: Red, Yellow, Green, Blue Better-than-ever digital sound 40% more recording time 25% more battery life Additional Information: Manufacturer: AbleNet (pr','','','','Operating System: Other Record a series of messages to this dedicated speech generating device and then activate the large 5-in/12.7-cm switch top to play each message back one at a time. Includes 2-minutes of record time and supports the use of an external switch for alternative methods of access. BIG STEP-BY-STEP FEATURES: Switch tops included: Red, Yellow, Green, Blue Better-than-ever digital sound 40% more recording time 25% more battery life Additional Information: Manufacturer: AbleNet (product page)','voice-and-speech','AbleNet','','','https://at.mada.org.qa/technology/big-sbs/','https://at.mada.org.qa/technology/big-sbs/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Big-SBS.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:42:05.117Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_little-step-by-step_2420072451956','Little Step BY Step','Little Step BY Step','','','Operating System: Other Record a series of messages to this dedicated speech generating device and then activate the 2.5-in/6.4-cm switch top to play each message back one at a time. Includes 2-minutes of record time and supports the use of an external switch for alternative methods of access. Record any series of messages into the LITTLE Step-by-Step communicator. Press its activation surface once to hear the first message. Press it again to hear the next message in the sequence, and so on. Two','','','','Operating System: Other Record a series of messages to this dedicated speech generating device and then activate the 2.5-in/6.4-cm switch top to play each message back one at a time. Includes 2-minutes of record time and supports the use of an external switch for alternative methods of access. Record any series of messages into the LITTLE Step-by-Step communicator. Press its activation surface once to hear the first message. Press it again to hear the next message in the sequence, and so on. Two full minutes of recording time allow you to record as many messages as you need. LITTLE Step-by-Step features an angled base and 2.5-in/6.4-cm activation surface. Powered by a replaceable 9 volt battery, LITTLE Step-by-Step never needs charging and can last for weeks or even months on a single battery. LITTLE STEP-BY-STEP FEATURES: Switch tops included: Red, Yellow, Green, Blue Better-than-ever digital sound 40% more recording time 25% more battery life Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/)','voice-and-speech','AbleNet','','','https://at.mada.org.qa/technology/little-step-by-step/','https://at.mada.org.qa/technology/little-step-by-step/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Little-Step-BY-Step.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:42:30.309Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_big-mack_2420072456564','BIGmack','BIGmack','','','Operating System: Other BIGmack is a single message dedicated speech generating device enabling you to record one message up to 2-minutes long directly to the device. For message playback, activate the large 5-in/12.7-cm switch top or use an alternative switch for access. Record any single message up to two minutes in length directly into the BIGmack communicator and press its activation surface for playback. Connect a toy or appliance for additional motivation. With its large, 5-in/12.7-cm acti','','','','Operating System: Other BIGmack is a single message dedicated speech generating device enabling you to record one message up to 2-minutes long directly to the device. For message playback, activate the large 5-in/12.7-cm switch top or use an alternative switch for access. Record any single message up to two minutes in length directly into the BIGmack communicator and press its activation surface for playback. Connect a toy or appliance for additional motivation. With its large, 5-in/12.7-cm activation surface, BIGmack is an excellent choice for persons with visual impairments and persons with physical disabilities who require a larger target area. Powered by a replaceable 9-volt battery, BIGmack never needs charging and can last for weeks or even months on a single battery. BIGMACK FEATURES: Switch tops included: Red, Yellow, Green, Blue Crystal-clear digital sound Volume control and ON/OFF switch Additional Information: Manufacturer: AbleNet (product page)','voice-and-speech','AbleNet','','','https://at.mada.org.qa/technology/big-mack/','https://at.mada.org.qa/technology/big-mack/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Big-Mack.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:42:07.011Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_little-mack_2420072460488','Little Mack','Little Mack','','','Operating System: Other Simply record any message directly into the LITTLEmack communicator for one touch, single message playback up to two minutes in length. Connect a toy or battery-operated appliance for instant positive reinforcement. With its angled base and 2.5-in/6.4-cm activation surface, LITTLEmack is perfect for mounting and is recommended for persons who can access a smaller target area. Powered by a replaceable 9-volt battery, LITTLEmack never needs charging and can last for weeks o','','','','Operating System: Other Simply record any message directly into the LITTLEmack communicator for one touch, single message playback up to two minutes in length. Connect a toy or battery-operated appliance for instant positive reinforcement. With its angled base and 2.5-in/6.4-cm activation surface, LITTLEmack is perfect for mounting and is recommended for persons who can access a smaller target area. Powered by a replaceable 9-volt battery, LITTLEmack never needs charging and can last for weeks or even months on a single battery. LITTLEMACK FEATURES: Switch tops included: Red, Yellow, Green, Blue Crystal-clear digital sound Volume control and ON/OFF switch Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/)','voice-and-speech','AbleNet','','','https://at.mada.org.qa/technology/little-mack/','https://at.mada.org.qa/technology/little-mack/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Little-Mack.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:42:28.149Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_talking-brix-4_2420072465786','TalkingBrix','TalkingBrix','','','Operating System: Other TalkingBrix are thin, lightweight communicators with built-in magnets that are perfect for carrying in a pocket or placing around the room! Use one Brix for personal reminders, or attach as many as you like to create simple, scalable communication grids. For Tabletop users, TalkingBrix use an ingenious tab and slot connector to link to other Brix. TalkingBrix are sold in packs of three with each Brix having a recording time of 10-seconds and a rechargeable battery. Create','','','','Operating System: Other TalkingBrix are thin, lightweight communicators with built-in magnets that are perfect for carrying in a pocket or placing around the room! Use one Brix for personal reminders, or attach as many as you like to create simple, scalable communication grids. For Tabletop users, TalkingBrix use an ingenious tab and slot connector to link to other Brix. TalkingBrix are sold in packs of three with each Brix having a recording time of 10-seconds and a rechargeable battery. Create multi-message communicators in any arrangement you like. Straight-line layouts reinforce sequential communication or linear learning activities. L-shape and other layouts allow users to create communication grids that meet their unique physical needs. TalkingBrix Features: Each pack of 3 TalkingBrix includes 1 each in Red, Blue, and Green Connectable devices for customizable layouts Easy single-message recording on each Brix Power on/off switch Free Snap Switch Cap included Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/) More information at https://ablenetinc.zendesk.com/hc/en-us/sections/360011858012-TalkingBrix-2 Video:','voice-and-speech','AbleNet','','','https://at.mada.org.qa/technology/talking-brix-4/','https://at.mada.org.qa/technology/talking-brix-4/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/talking-brix-4.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:42:45.469Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_tobii-c15-eye-tracking-system_2420072469717','Tobii C15','Tobii C15','','','Operating System: Windows, Other Tobii C15 is an assistive and augmentative communication device (AAC) designed for people with physical impairments. The device has eye control module, which helps people with physical disabilities to communicate in daily life via text, or symbols that generate speech, which allows them to connect with others through email, text, and chat, or surf the internet, play games, etc. Furthermore, it allows users to control infrared (IR) enabled devices such as TVs, DVD','','','','Operating System: Windows, Other Tobii C15 is an assistive and augmentative communication device (AAC) designed for people with physical impairments. The device has eye control module, which helps people with physical disabilities to communicate in daily life via text, or symbols that generate speech, which allows them to connect with others through email, text, and chat, or surf the internet, play games, etc. Furthermore, it allows users to control infrared (IR) enabled devices such as TVs, DVD players, door, and light switches. In addition, it comes with a large screen as well as it supports all input methods that gives the user the freedom of selecting the best method that suits his abilities or needs such as touch screen, keyboard and mouse, switches, head mouse or eye control. Additional Information: Manufacturer: Tobii Dynavox (https://www.tobiidynavox.com)','voice-and-speech','Tobii Dynavox','','','https://at.mada.org.qa/technology/tobii-c15-eye-tracking-system/','https://at.mada.org.qa/technology/tobii-c15-eye-tracking-system/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Tobii-C15-eye-tracking-system.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:42:51.989Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_desmos-accessible-calculator_2420072474129','Desmos Accessible Calculator','Desmos Accessible Calculator','','','Operating System: Windows, iOS, Android, Chrome Desmos is online calculators, which include a four-function, scientific, and graphing calculator, are available free to the public. The online calculators can be accessed with a computer, tablet, or other personal device. Also Desmos apps can be downloaded to iOS or Android devices. Desmos provides accessibility features, such as accessible by screen readers, audio tracing to hear a single function or the entire equations, or keyboard shortcuts for','','','','Operating System: Windows, iOS, Android, Chrome Desmos is online calculators, which include a four-function, scientific, and graphing calculator, are available free to the public. The online calculators can be accessed with a computer, tablet, or other personal device. Also Desmos apps can be downloaded to iOS or Android devices. Desmos provides accessibility features, such as accessible by screen readers, audio tracing to hear a single function or the entire equations, or keyboard shortcuts for ease access. Additional Information: Manufacturer: Desmos (official website) Desmos Support at https://help.desmos.com/hc/en-us Desmos introduction video','cognition','Desmos','','','https://at.mada.org.qa/technology/desmos-accessible-calculator/','https://at.mada.org.qa/technology/desmos-accessible-calculator/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Desmos.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:31.590Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_bjoy-chin_2420072478582','BJoy Chin','BJoy Chin','','','Operating System: Other Control the computer with your chin The BJOY Chin is the best alternative to use the mouse with your chin. Its small size, position of the buttons, accuracy and all the mounting options and possibilities make this mouse a very versatile device. It is part of the BJOY range of products: it can be tailored to the user’s needs and capabilities and the operation can be customized using the BJOY Software. Use your mouse with accuracy and ergonomics with the movement of your he','','','','Operating System: Other Control the computer with your chin The BJOY Chin is the best alternative to use the mouse with your chin. Its small size, position of the buttons, accuracy and all the mounting options and possibilities make this mouse a very versatile device. It is part of the BJOY range of products: it can be tailored to the user’s needs and capabilities and the operation can be customized using the BJOY Software. Use your mouse with accuracy and ergonomics with the movement of your head. Access your favourite apps with comfort and simplicity. Customise your mouse if you want that it suits you better. We can manufacture it according to your needs. “Plug and Play” device, compatible with Windows, MacOS and Linux. Use the BJOY Software to modify the function of each button, the cursor speed, the orientation and many other parameters. All settings are stored in the device so you can use your customised mouse to access any device. Additional Information: Manufacturer: Qinera (product page) Video:','cognition','Qinera','','','https://at.mada.org.qa/technology/bjoy-chin/','https://at.mada.org.qa/technology/bjoy-chin/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Bjoy-chin.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:04.638Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_bee-bot-programmable-floor-robot_2420072483613','Bee-Bot Programmable Floor Robot','Bee-Bot Programmable Floor Robot','','','Operating System: Other The robot Bee-Bot is designed to be used by the younger children from 5 years old. Its usage is very simple and pleasant. This educational robot teaches children the forms and colors but also to find their way in space. In the form of a bee, this robot has several buttons on its back. Simply press one of them to turn it on. Then, it’s very simple for a child to program it by pressing the directions one after the other (right, left, straight…) Additional Information: Manuf','','','','Operating System: Other The robot Bee-Bot is designed to be used by the younger children from 5 years old. Its usage is very simple and pleasant. This educational robot teaches children the forms and colors but also to find their way in space. In the form of a bee, this robot has several buttons on its back. Simply press one of them to turn it on. Then, it’s very simple for a child to program it by pressing the directions one after the other (right, left, straight…) Additional Information: Manufacturer: Terrapin (product page) Terrapin Bee Bot Resources at https://resources.terrapinlogo.com/robots/bee-bot/ Virtual Bee Bot Mats for trial at https://beebot.terrapinlogo.com/','cognition','Terrapin','','','https://at.mada.org.qa/technology/bee-bot-programmable-floor-robot/','https://at.mada.org.qa/technology/bee-bot-programmable-floor-robot/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/beebot.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:06.428Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_newmero-bricks_2420072487878','Newmero Bricks','Newmero Bricks','','','Operating System: Other Newmero Bricks is an Innovative STEM toy for children aged 3-9 years that helps children find the answers themselves. Contains 57 numbered bricks (1, 10, 100, & 1,000) that makes learning fun of the numbers and the decimal system. The concept of the newmero bricks is to turn the abstract decimal number system into a physical playing and learning experience. Understanding numbers by touching, building, decomposing them. Additional Information: Manufacturer: Newmero (https:','','','','Operating System: Other Newmero Bricks is an Innovative STEM toy for children aged 3-9 years that helps children find the answers themselves. Contains 57 numbered bricks (1, 10, 100, & 1,000) that makes learning fun of the numbers and the decimal system. The concept of the newmero bricks is to turn the abstract decimal number system into a physical playing and learning experience. Understanding numbers by touching, building, decomposing them. Additional Information: Manufacturer: Newmero (https://newmero.dk) Video:','cognition','Newmero','','','https://at.mada.org.qa/technology/newmero-bricks/','https://at.mada.org.qa/technology/newmero-bricks/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/newmero_bricks.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:15.051Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_cosmo-switch_242007249163','Cosmo Switch','Cosmo Switch','','','Operating System: Windows, iOS, Android, Chrome The Cosmo Switch is a unique Bluetooth switch interface for tablets, mobile phones, and computers. It is highly responsive, making it very easy to activate regardless of your motor abilities. The switch lights up in a variety of colours, making it very engaging and providing visual feedback with every press. The Cosmo Switch provides access to all switch accessible apps or software on iOS, OS X, Chromebooks, Windows and Android devices. Use the Cos','','','','Operating System: Windows, iOS, Android, Chrome The Cosmo Switch is a unique Bluetooth switch interface for tablets, mobile phones, and computers. It is highly responsive, making it very easy to activate regardless of your motor abilities. The switch lights up in a variety of colours, making it very engaging and providing visual feedback with every press. The Cosmo Switch provides access to all switch accessible apps or software on iOS, OS X, Chromebooks, Windows and Android devices. Use the CosmoSwitch with your Augmented and Alternative Communication (AAC) software, for switch accessibility, for games, controlling music playback, or even connect to IFTTT to control your calls, lights and more. Additional Information: Manufacturer: Filisia (official website, product page) Cosmo introduction video:','cognition','Filisia','','','https://at.mada.org.qa/technology/cosmo-switch/','https://at.mada.org.qa/technology/cosmo-switch/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/download.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:27.520Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_skoog-2-0_2420072496257','Skoog 2.0','Skoog 2.0','','','Operating System: iOS Skoog works with iPad, so you can play, jam and create music like a rockstar. Just choose a song you love and get playing! The free Skoog app works with Apple Music, Spotify or your music streaming service. It automatically tunes your Skoog, so you learn as you play. It’s creative and fun – that’s what ‘musicplay’ is all about. Additional Information: Manufacturer: Skoogmusic Ltd. (Defunct) Skoog Introduction video:','','','','Operating System: iOS Skoog works with iPad, so you can play, jam and create music like a rockstar. Just choose a song you love and get playing! The free Skoog app works with Apple Music, Spotify or your music streaming service. It automatically tunes your Skoog, so you learn as you play. It’s creative and fun – that’s what ‘musicplay’ is all about. Additional Information: Manufacturer: Skoogmusic Ltd. (Defunct) Skoog Introduction video:','cognition','Skoogmusic Ltd. Defunct','','','https://at.mada.org.qa/technology/skoog-2-0/','https://at.mada.org.qa/technology/skoog-2-0/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/skoog.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:28.735Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_grid-3-arabic-english_2420072500918','Grid 3 (Arabic-English)','Grid 3 (Arabic-English)','','','Operating System: Windows Grid 3 is a complete communication solution that enables people to have a voice, control their environment and live more independent lives. It’s designed for anyone with complex communication or access needs and includes a wide range of resources that you can control with touch, switch, eye gaze and pointing devices. You’ll find grid sets for talking with symbols or text, and content for all ages and abilities. A range of vocabularies are available with Grid, from Word ','','','','Operating System: Windows Grid 3 is a complete communication solution that enables people to have a voice, control their environment and live more independent lives. It’s designed for anyone with complex communication or access needs and includes a wide range of resources that you can control with touch, switch, eye gaze and pointing devices. You’ll find grid sets for talking with symbols or text, and content for all ages and abilities. A range of vocabularies are available with Grid, from Word Power to PODD and Vocabulary for Life. All popular symbol libraries are included with Grid 3: Widgit, PCS, Symbol Stix and Snap Photos. Additional Information: Manufacturer: Think SmartBox More information at https://thinksmartbox.com/product/grid-3/','cognition','Think SmartBox','','','https://at.mada.org.qa/technology/grid-3-arabic-english/','https://at.mada.org.qa/technology/grid-3-arabic-english/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Grid-3.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:43.090Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_wordpower_2420072504634','WordPower','WordPower','','','Operating System: Windows WordPower uses high-frequency core words to facilitate quick and easy sentence generation. It also includes nouns and adjectives that are organized in logical categories. Grammatical word classes have been included. As a sentence is being built, you often find that the next word you want to say can be spoken with one or two button presses. A spelling/word prediction page is used to spell words that are not included in the vocabulary set. Being a word-based vocabulary, W','','','','Operating System: Windows WordPower uses high-frequency core words to facilitate quick and easy sentence generation. It also includes nouns and adjectives that are organized in logical categories. Grammatical word classes have been included. As a sentence is being built, you often find that the next word you want to say can be spoken with one or two button presses. A spelling/word prediction page is used to spell words that are not included in the vocabulary set. Being a word-based vocabulary, WordPower can be used by a wide age group. Nouns, adjectives and verbs can be added and customized to meet the particular needs of the individual. WordPower is provided in a 20, 25 Touch & Scan, 42 basic, 42, 48, 60 Basic, 60, 80, 108 with Keyboard, 108 button page layout, and 140 Scan & Touch. It is also available in Spanish and French options. Additional Information: Manufacturer: Saltillo More information at https://saltillo.com/products/option/wordpower','cognition','Saltillo','','','https://at.mada.org.qa/technology/wordpower/','https://at.mada.org.qa/technology/wordpower/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/WordPower.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:57.224Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_snap-read_242007251051','Snap & Read (English/Arabic)','Snap & Read (English/Arabic)','','','Operating System: Windows, iOS, Chrome Snap&Read is the Next-Generation reading tool that can cover the most diverse reading needs. Features: Read Aloud – Listen to text as it’s read aloud across websites, PDFs, and Google Drive. It also reads in other languages Additional Information: Manufacturer: Don Johnston Snap&Read Learning Resources: https://learningtools.donjohnston.com/support/product-resources/#snap-read-learning-academy','','','','Operating System: Windows, iOS, Chrome Snap&Read is the Next-Generation reading tool that can cover the most diverse reading needs. Features: Read Aloud – Listen to text as it’s read aloud across websites, PDFs, and Google Drive. It also reads in other languages Additional Information: Manufacturer: Don Johnston Snap&Read Learning Resources: https://learningtools.donjohnston.com/support/product-resources/#snap-read-learning-academy','cognition','Don Johnston','','','https://at.mada.org.qa/technology/snap-read/','https://at.mada.org.qa/technology/snap-read/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Snap-Read.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:32.490Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_symwriter-2_2420072514920','SymWriter 2 (English)','SymWriter 2 (English)','','','Operating System: Windows SymWriter 2 is a symbol-supported word processor that any writer, regardless of literacy levels, can use to create documents. Writers of any age or ability can use the widget Symbols to see the meaning of words as they type, supporting access to new or challenging vocabulary. Additional Information: Manufacturer: Widgit Software (https://www.widgit.com/) SymWriter2 Video Introduction: SymWriter2 User Support: https://www.widgit.com/support/symwriter/index.htm','','','','Operating System: Windows SymWriter 2 is a symbol-supported word processor that any writer, regardless of literacy levels, can use to create documents. Writers of any age or ability can use the widget Symbols to see the meaning of words as they type, supporting access to new or challenging vocabulary. Additional Information: Manufacturer: Widgit Software (https://www.widgit.com/) SymWriter2 Video Introduction: SymWriter2 User Support: https://www.widgit.com/support/symwriter/index.htm','cognition','Widgit Software','','','https://at.mada.org.qa/technology/symwriter-2/','https://at.mada.org.qa/technology/symwriter-2/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/SymWriter-2.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:39.068Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_nessy-learning-program_2420072519411','Nessy Learning Program','Nessy Learning Program','','','Operating System: Windows, iOS, Android, Chrome Nessy has been making fun, educational software for children since 1999 and has developed a reputation for exceptional quality. Nessy offers the complete dyslexia aware solution with a suite of multisensory products aimed at making learning to read, write and spell fun. Additional Information: Manufacturer: Nessy Learning (official website) Nessy Learning Program User Support: https://nessy.zendesk.com/hc/en-gb Nessy Learning Program Introduction V','','','','Operating System: Windows, iOS, Android, Chrome Nessy has been making fun, educational software for children since 1999 and has developed a reputation for exceptional quality. Nessy offers the complete dyslexia aware solution with a suite of multisensory products aimed at making learning to read, write and spell fun. Additional Information: Manufacturer: Nessy Learning (official website) Nessy Learning Program User Support: https://nessy.zendesk.com/hc/en-gb Nessy Learning Program Introduction Video:','cognition','Nessy','','','https://at.mada.org.qa/technology/nessy-learning-program/','https://at.mada.org.qa/technology/nessy-learning-program/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Nessy-Learning-Program.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:44:17.996Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_xmind_2420072523762','XMind','XMind','','','Operating System: Windows, iOS, Android, Chrome XMind is a mind mapping and brainstorming software, developed by XMind Ltd. In addition to the management elements, the software can be used to capture ideas, clarify thinking, manage complex information, and promote team collaboration. Additional Information: Manufacturer: XMind XMind User Guide: https://support.xmind.net/hc/en-us/sections/360004567512-XMind-8-User-Guide','','','','Operating System: Windows, iOS, Android, Chrome XMind is a mind mapping and brainstorming software, developed by XMind Ltd. In addition to the management elements, the software can be used to capture ideas, clarify thinking, manage complex information, and promote team collaboration. Additional Information: Manufacturer: XMind XMind User Guide: https://support.xmind.net/hc/en-us/sections/360004567512-XMind-8-User-Guide','cognition','XMind','','','https://at.mada.org.qa/technology/xmind/','https://at.mada.org.qa/technology/xmind/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/XMind.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:59.162Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_texthelp-readwrite_2420072528925','TextHelp Read and Write','TextHelp Read and Write','','','Operating System: Windows, iOS, Android, Chrome Read&Write lets everyone read, write and express themselves more confidently. Our easy-to-use toolbar makes documents, files and web pages more accessible. Read&Write is a big confidence booster for anyone who needs a little support with their reading and writing, at school or in the workplace. And its friendly literacy features help English Language Learners, as well as people with dyslexia or other learning difficulties. From hearing emails or do','','','','Operating System: Windows, iOS, Android, Chrome Read&Write lets everyone read, write and express themselves more confidently. Our easy-to-use toolbar makes documents, files and web pages more accessible. Read&Write is a big confidence booster for anyone who needs a little support with their reading and writing, at school or in the workplace. And its friendly literacy features help English Language Learners, as well as people with dyslexia or other learning difficulties. From hearing emails or documents read out loud to text prediction, picture dictionaries and summary highlighters, Read&Write makes lots of everyday literacy tasks simpler, quicker and more accurate. Additional Information: Manufacturer: TextHelp (https://www.texthelp.com/) Read&Write Introduction Video: Read&Write Support Manuals: https://support.texthelp.com/help/readwrite-7fdf2ac','cognition','TextHelp','','','https://at.mada.org.qa/technology/texthelp-readwrite/','https://at.mada.org.qa/technology/texthelp-readwrite/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/TextHelp-ReadWrite.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:49.123Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_mindview-software_2420072532659','MindView Software','MindView Software','','','Operating System: Windows, iOS, Chrome MindView is an educational mind mapping software that helps you present your ideas visually. It provides a set of ready-to-use templates, wizards and professional clipart to create your mind map. The models could also be exported to several formats including MS Word, PowerPoint, and Excel. Additional Information: Manufacturer: Matchware MindView 7 Manual: https://www.matchware.com/product-manuals','','','','Operating System: Windows, iOS, Chrome MindView is an educational mind mapping software that helps you present your ideas visually. It provides a set of ready-to-use templates, wizards and professional clipart to create your mind map. The models could also be exported to several formats including MS Word, PowerPoint, and Excel. Additional Information: Manufacturer: Matchware MindView 7 Manual: https://www.matchware.com/product-manuals','cognition','Matchware','','','https://at.mada.org.qa/technology/mindview-software/','https://at.mada.org.qa/technology/mindview-software/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/MindView-Software.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:05.155Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_kurzweil-3000_2420072537429','Kurzweil 3000','Kurzweil 3000','','','Operating System: Windows, iOS, Chrome Kurzweil 3000 is a software designed for people with visual impairment. The program makes printed or electronic text readily available for people with vision loss. Kurzweil 3000 software can help individuals with ‘early vision loss, computer vision syndrome, and visual impairments such as macular degeneration and glaucoma as well users at home, at school or at work. Kurzweil 3000 provides highlighting a sentence, line or phrase in one color and each word in','','','','Operating System: Windows, iOS, Chrome Kurzweil 3000 is a software designed for people with visual impairment. The program makes printed or electronic text readily available for people with vision loss. Kurzweil 3000 software can help individuals with ‘early vision loss, computer vision syndrome, and visual impairments such as macular degeneration and glaucoma as well users at home, at school or at work. Kurzweil 3000 provides highlighting a sentence, line or phrase in one color and each word in another color as it is read aloud. In addition, it provides quick access to dictionaries, synonyms, and syllables. Furthermore, it has flexiable writing tools which students use while typing such as check-spelling or speak while typing. Moreover, it provides audible and visual access to web pages with Mozilla Firefox. Besides, it has delivery options such as stadalone for singel users, Network for users sharing same network, and USB flash drive. The product is also available in Professional Color or Black/ White as well as Learn Station (Read Only) versions. Additional Information: Manufacturer: Cambium Learning Group Kurzweil 3000 How-to-Guides: https://www.kurzweiledu.com/kurzweil-academy/kurzweil-academy.html','cognition','Cambium Learning Group','','','https://at.mada.org.qa/technology/kurzweil-3000/','https://at.mada.org.qa/technology/kurzweil-3000/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Kurzweil-3000.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:51.050Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_c-pen-dictionarypen_2420072542122','C-Pen DictionaryPen','C-Pen DictionaryPen','','','Operating System: Other C-PEN DictionaryPen™ a robust, portable, pocket-sized translator pen that easily translates and pronounces single words. DictionaryPen is a major technological breakthrough for anyone working or studying in a “second language”. The embedded camera and OCR technology enables “zero click” lookup or translation of words. Simply pass the nib across a word and it instantly displays the definition and reads the word. The pen dictionary include nine (9) OXFORD Academic and Engli','','','','Operating System: Other C-PEN DictionaryPen™ a robust, portable, pocket-sized translator pen that easily translates and pronounces single words. DictionaryPen is a major technological breakthrough for anyone working or studying in a “second language”. The embedded camera and OCR technology enables “zero click” lookup or translation of words. Simply pass the nib across a word and it instantly displays the definition and reads the word. The pen dictionary include nine (9) OXFORD Academic and English Language Teaching (ELT) dictionaries supporting six different languages. It’s a totally portable, pocket-sized device that pronounces the looked up word with a human like natural speaking voice. Additional Information: Manufacturer: C-Pen (https://cpen.com/) C-Pen DictionaryPen Introduction: C-Pen DitionaryPen User Guide: https://cpen.com/kb-article/dictionarypen-user-guide/','cognition','C-Pen','','','https://at.mada.org.qa/technology/c-pen-dictionarypen/','https://at.mada.org.qa/technology/c-pen-dictionarypen/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/C-Pen-DictionaryPen.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:10.250Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_livescribe-echo-smart-pen_2420072546178','Livescribe ECHO Smart Pen','Livescribe ECHO Smart Pen','','','Operating System: Windows, iOS, Android, Chrome Livescribe smartpens digitally capture everything you write on Livescribe notebooks and store them in its memory. When the smartpens are connected with a supported companion device (mobile/ tablet/ desktops), they securely transfer the data to the Livescribe Apps in the device. In addition to digitizing handwritten notes, Livescribe smartpens also record audio and synchronize the recorded audio to what you write. Depending on the smartpen, audio re','','','','Operating System: Windows, iOS, Android, Chrome Livescribe smartpens digitally capture everything you write on Livescribe notebooks and store them in its memory. When the smartpens are connected with a supported companion device (mobile/ tablet/ desktops), they securely transfer the data to the Livescribe Apps in the device. In addition to digitizing handwritten notes, Livescribe smartpens also record audio and synchronize the recorded audio to what you write. Depending on the smartpen, audio recording and playback is either done on the pen itself or with the help of the Livescribe+ App on a companion mobile device. Additional Information: Manufacturer: Livescribe (https://us.livescribe.com/) Livescribe Smart EchoPen Introduction :','cognition','Livescribe','','','https://at.mada.org.qa/technology/livescribe-echo-smart-pen/','https://at.mada.org.qa/technology/livescribe-echo-smart-pen/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Eco-Smartpen.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:58.817Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_co-writer_242007255026','Co-Writer','Co-Writer','','','Operating System: Windows, iOS, Chrome Co:Writer is a toolkit that helps educators address a wide range of writing abilities in the classroom—from dyslexia and dysgraphia to language barriers (ELL). Co:Writer provides various features, such as grammar-smart and vocabulary-smart word prediction, translation support, and speech recognition to help organizing ideas and get them to flow in writing. Additional Information: Manufacturer: Don Johnston Co-Writer Supporting Documents: https://learningtoo','','','','Operating System: Windows, iOS, Chrome Co:Writer is a toolkit that helps educators address a wide range of writing abilities in the classroom—from dyslexia and dysgraphia to language barriers (ELL). Co:Writer provides various features, such as grammar-smart and vocabulary-smart word prediction, translation support, and speech recognition to help organizing ideas and get them to flow in writing. Additional Information: Manufacturer: Don Johnston Co-Writer Supporting Documents: https://learningtools.donjohnston.com/support/product-resources/#cowriter-quickcards','cognition','Don Johnston','','','https://at.mada.org.qa/technology/co-writer/','https://at.mada.org.qa/technology/co-writer/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Co-Writer.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:25.563Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_claroread_2420072555264','ClaroRead','ClaroRead','','','Operating System: Windows, iOS, Chrome ClaroRead is a simple, easy-to-use and flexible software program that helps you to read, write, study, sit exams, and increase your confidence. You can read any on-screen text out loud and improve your writing in Microsoft Word. ClaroRead Plus and Pro also let you read aloud scanned paper books and documents. Additional Information: Manufacturer: Claro Software (https://www.clarosoftware.com/) ClaroRead User Guide: https://www.clarosoftware.com/help/help_fi','','','','Operating System: Windows, iOS, Chrome ClaroRead is a simple, easy-to-use and flexible software program that helps you to read, write, study, sit exams, and increase your confidence. You can read any on-screen text out loud and improve your writing in Microsoft Word. ClaroRead Plus and Pro also let you read aloud scanned paper books and documents. Additional Information: Manufacturer: Claro Software (https://www.clarosoftware.com/) ClaroRead User Guide: https://www.clarosoftware.com/help/help_files/manuals/ClaroRead-9.0-en.pdf ClaroRead Overview Video:','cognition','Claro Software','','','https://at.mada.org.qa/technology/claroread/','https://at.mada.org.qa/technology/claroread/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/ClaroRead.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:19.911Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_claroideas_2420072560927','ClaroIdeas','ClaroIdeas','','','Operating System: Windows, iOS, Android, Chrome ClaroIdeas is a mind mapping and idea capture program that helps with research, planning, outlining, studying and presenting. It is easy-to-use and powerful and will help users and groups to capture their ideas, pictures, research notes, web page links, audio and video files with more freedom, flexibility and creativity. Additional Information: Manufacturer: Claro Software (https://www.clarosoftware.com) ClaroIdeas User Guide: https://www.clarosoft','','','','Operating System: Windows, iOS, Android, Chrome ClaroIdeas is a mind mapping and idea capture program that helps with research, planning, outlining, studying and presenting. It is easy-to-use and powerful and will help users and groups to capture their ideas, pictures, research notes, web page links, audio and video files with more freedom, flexibility and creativity. Additional Information: Manufacturer: Claro Software (https://www.clarosoftware.com) ClaroIdeas User Guide: https://www.clarosoftware.com/help/help_files/online_help/ClaroIdeas_V2_en/','cognition','Claro Software','','','https://at.mada.org.qa/technology/claroideas/','https://at.mada.org.qa/technology/claroideas/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/ClaroIdeas.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:18.057Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_c-pen-readerpen_2420072564923','C-Pen ReaderPen','C-Pen ReaderPen','','','Operating System: Other C-Pen ReaderPen is a robust, portable, pocket-sized reading pen that reads text out loud with a human-like digital voice. ReaderPen is designed to promote independent learning and is a major technological breakthrough for any student suffering from reading difficulties such as dyslexia. It reads text out aloud with American English, British English, French and Spanish human-like digital voices. It also features embedded first tier junior and academic dictionaries for imme','','','','Operating System: Other C-Pen ReaderPen is a robust, portable, pocket-sized reading pen that reads text out loud with a human-like digital voice. ReaderPen is designed to promote independent learning and is a major technological breakthrough for any student suffering from reading difficulties such as dyslexia. It reads text out aloud with American English, British English, French and Spanish human-like digital voices. It also features embedded first tier junior and academic dictionaries for immediate access to word definitions, a function allowing storage of text captured from textbooks, and a voice memo function. Additional Information: Manufacturer: C-Pen C-Pen ReaderPen First Use: https://youtu.be/PPrAm4i8e0k C-Pen ReaderPen Quick Start Guide: https://cpen.com/kb-article/readerpen-quick-start-guide-multilingual/ Video:','cognition','C-Pen','','','https://at.mada.org.qa/technology/c-pen-readerpen/','https://at.mada.org.qa/technology/c-pen-readerpen/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/C-Pen-ReaderPen.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:12.490Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_nessy-fingers-touch-typing_2420072568235','Nessy Fingers Touch Typing','Nessy Fingers Touch Typing','','','Operating System: Windows, iOS, Chrome Nessy gets students typing real words fast and introduces spelling practice immediately. Keys are introduced alphabetically which makes sense to kids – this is different to most other typing programs which mix up random letters. Additional Information: Manufacturer: Nessy (product page) Nessy Fingers Touch Typings Introduction Video:','','','','Operating System: Windows, iOS, Chrome Nessy gets students typing real words fast and introduces spelling practice immediately. Keys are introduced alphabetically which makes sense to kids – this is different to most other typing programs which mix up random letters. Additional Information: Manufacturer: Nessy (product page) Nessy Fingers Touch Typings Introduction Video:','cognition','Nessy','','','https://at.mada.org.qa/technology/nessy-fingers-touch-typing/','https://at.mada.org.qa/technology/nessy-fingers-touch-typing/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Nessy-Fingers.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:10.870Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_minecraft-education-edition_2420072573544','Minecraft Education','Minecraft Education','','','Operating System: Windows Minecraft Education is a special version of the hit game tailored for the classroom, with special features like the in-game programming environment and lesson library that allow educators of all stripes to provide comprehensive and fun courses on a wide variety of subjects in a safe and immersive environment. Additional Information: Manufacturer: Mojang Studios (http://education.minecraft.net/en-us) Video:','','','','Operating System: Windows Minecraft Education is a special version of the hit game tailored for the classroom, with special features like the in-game programming environment and lesson library that allow educators of all stripes to provide comprehensive and fun courses on a wide variety of subjects in a safe and immersive environment. Additional Information: Manufacturer: Mojang Studios (http://education.minecraft.net/en-us) Video:','cognition','Mojang Studios','','','https://at.mada.org.qa/technology/minecraft-education-edition/','https://at.mada.org.qa/technology/minecraft-education-edition/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Minecraft.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:07.302Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_look-to-learn-2_2420072578164','Look to Learn','Look to Learn','','','Operating System: Windows A motivating and fun way to get started with eye gaze technology including over 40 activities. With over 40 specially created activities, Look to Learn is a motivating and fun way to get started with eye gaze technology. Every activity has been developed in consultation with teachers and therapists to improve access and choice making skills. Expand the Look to Learn experience with 26 new activities for anyone starting out with eye gaze. Again we have worked with teache','','','','Operating System: Windows A motivating and fun way to get started with eye gaze technology including over 40 activities. With over 40 specially created activities, Look to Learn is a motivating and fun way to get started with eye gaze technology. Every activity has been developed in consultation with teachers and therapists to improve access and choice making skills. Expand the Look to Learn experience with 26 new activities for anyone starting out with eye gaze. Again we have worked with teachers and therapists to make sure every activity is fun yet teaches valuable skills. Get creative and load in your favourite images and videos to make the activities your own. The built in analysis tool to show where somebody has looked on the screen during an activity in the form of a heat map. These heat maps can be saved, printed and used to measure progress and record successes. You can also assess eye tracking, targeting and choice making skills. Additional Information: Manufacturer: SmartBox (https://thinksmartbox.com) Look to Learn Video Introduction: Look to Learn Manual: https://thinksmartbox.com/wp/wp-content/uploads/2018/11/Look-to-Learn-Manual-Oct-2018-Web.pdf','cognition','SmartBox','','','https://at.mada.org.qa/technology/look-to-learn-2/','https://at.mada.org.qa/technology/look-to-learn-2/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Look-to-Learn.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:00.990Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_eyegaze-learning-curve_2420072582480','EyeGaze Learning Curve','EyeGaze Learning Curve','','','Operating System: Windows Learning Curve provides 54 fun and engaging interactive activities specially created to teach early eye gaze access and develop choice making skills. This collection takes users on the learning curve from assessment and cause and effect understanding through to using eye gaze for communication, learning and leisure. All users on their first steps with eye gaze can use these activities to improve their accuracy and understanding of eye gaze in preparation for using other','','','','Operating System: Windows Learning Curve provides 54 fun and engaging interactive activities specially created to teach early eye gaze access and develop choice making skills. This collection takes users on the learning curve from assessment and cause and effect understanding through to using eye gaze for communication, learning and leisure. All users on their first steps with eye gaze can use these activities to improve their accuracy and understanding of eye gaze in preparation for using other communication and learning software. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk/) Inclusive EyeGaze Learning Curve Introduction Video:','cognition','Inclusive Technology','','','https://at.mada.org.qa/technology/eyegaze-learning-curve/','https://at.mada.org.qa/technology/eyegaze-learning-curve/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Learning-curve.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:37.274Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_switch-skills-series-2_2420072586784','Switch Skills Series','Switch Skills Series','','','Operating System: Windows Switch Skills 1: This collection of easy switch timing games have themes which motivate children who understand cause and effect to develop more disciplined switch use. The activities also encourage speaking and listening and help develop concentration skills. The graphics are bright and clear and this combined with sound and music makes the games suitable for children. Switch Skills 2: It is early learning cause and effect software with 20 different activities The user','','','','Operating System: Windows Switch Skills 1: This collection of easy switch timing games have themes which motivate children who understand cause and effect to develop more disciplined switch use. The activities also encourage speaking and listening and help develop concentration skills. The graphics are bright and clear and this combined with sound and music makes the games suitable for children. Switch Skills 2: It is early learning cause and effect software with 20 different activities The user presses the switch or touch screen to activate a bright animation with music. Higher-level activities require increased visual discrimination but are still activated by the press of a switch. ‘Gopher in a Drainpipe’ and ‘Mystery Egg’ can be trialed at www.helpkidzlearn.com. Switch Skills 3: It is a software has sixteen graded activities that aim to develop scanning skills. Some of the activities are error-free whilst others require good switch timing skills. Other variations include Switch skills 1 Set 1, Switch Skills 2 Set 2, Switch Skills 1 Set 2, Switch Skills 2 Set 1, Switch Skills Scanning, Switch Skills Champions. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk/) Switch Skills Series Demonstration Video:','cognition','Inclusive Technology','','','https://at.mada.org.qa/technology/switch-skills-series-2/','https://at.mada.org.qa/technology/switch-skills-series-2/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Switch-Skills-Series.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:34.890Z',NULL,NULL,NULL);
