INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_lets-go-to-town_2420072599437','Lets Go to Town','Lets Go to Town','','','Operating System: Windows Let’s Go To Town features 9 interactive scenes with linking animations to provide cohesion. Let’s Go To Town is designed to promote decision making and encourage discussion of the real-life activity at a basic level. The story and presentation has been aimed at students of all ages, principally with severe learning difficulties and/or little reading ability. Suitable for young children as well. Additional Information: Manufacturer: Inclusive Technology (http://www.inclu','','','','Operating System: Windows Let’s Go To Town features 9 interactive scenes with linking animations to provide cohesion. Let’s Go To Town is designed to promote decision making and encourage discussion of the real-life activity at a basic level. The story and presentation has been aimed at students of all ages, principally with severe learning difficulties and/or little reading ability. Suitable for young children as well. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk/)','cognition','Inclusive Technology','','','https://at.mada.org.qa/technology/lets-go-to-town/','https://at.mada.org.qa/technology/lets-go-to-town/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Lets-Go-to-Town.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:54.804Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_lets-go-to-the-seaside_2420072604780','Lets Go to the Seaside','Lets Go to the Seaside','','','Operating System: Windows Let’s Go To The Seaside is an onscreen story book with decision making activities and animations to link the story together. It encourages the discussion of preferences and promotes life skills. Each page has a limited number of things to click on, making it easy for those learning switch scanning skills. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk/)','','','','Operating System: Windows Let’s Go To The Seaside is an onscreen story book with decision making activities and animations to link the story together. It encourages the discussion of preferences and promotes life skills. Each page has a limited number of things to click on, making it easy for those learning switch scanning skills. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk/)','cognition','Inclusive Technology','','','https://at.mada.org.qa/technology/lets-go-to-the-seaside/','https://at.mada.org.qa/technology/lets-go-to-the-seaside/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Lets-Go-to-the-Seaside.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:56.836Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_switchit-jigsaw-maker-2_2420072609799','SwitchIt! Jigsaw Maker 2','SwitchIt! Jigsaw Maker 2','','','Operating System: Windows Jigsaw Maker allows to create gizsaw puzzles activities for children with learning difficulties. The jigsaws can be completed in 4 ways, which provides activities with a finely graded progression in skill level: Cause and effect – just press a switch to build the picture. This level can also be used in a reveal game: The picture appears bit by bit, so learners can try and guess what the picture is before it is completed. Click on any piece – it will jump into place. An ','','','','Operating System: Windows Jigsaw Maker allows to create gizsaw puzzles activities for children with learning difficulties. The jigsaws can be completed in 4 ways, which provides activities with a finely graded progression in skill level: Cause and effect – just press a switch to build the picture. This level can also be used in a reveal game: The picture appears bit by bit, so learners can try and guess what the picture is before it is completed. Click on any piece – it will jump into place. An easy introduction to making jigsaws. Find the piece that fits the place chosen by the computer. A more demanding activity. Drag the pieces into their correct places. This level simulates making a real jigsaw. Support is provided for those players who find dragging with the mouse difficult, and this level can also be played using single clicks of the mouse. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk/) SwitchIt Jigsaw Maker 2 Video Introduction','cognition','Inclusive Technology','','','https://at.mada.org.qa/technology/switchit-jigsaw-maker-2/','https://at.mada.org.qa/technology/switchit-jigsaw-maker-2/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/SwitchIt-Jigsaw-Maker-2.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:37.167Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_tobii-pceye-mini_2420072613125','Tobii PCEye Mini','Tobii PCEye Mini','','','Operating System: Windows The PCEye Mini includes a PCEye Mini eye tracker and the new Windows Control software. Windows Control enables full computer access on a Windows PC via eye gaze or eye gaze combined with switch input, replacing the standard keyboard and mouse. Additional Information: Manufacturer: Tobii Dynabox Tobii PCEye Mini – Windows Control Training and Tutorials: https://www.tobiidynavox.com/support-training/windows-control-2/','','','','Operating System: Windows The PCEye Mini includes a PCEye Mini eye tracker and the new Windows Control software. Windows Control enables full computer access on a Windows PC via eye gaze or eye gaze combined with switch input, replacing the standard keyboard and mouse. Additional Information: Manufacturer: Tobii Dynabox Tobii PCEye Mini – Windows Control Training and Tutorials: https://www.tobiidynavox.com/support-training/windows-control-2/','cognition','Tobii Dynavox','','','https://at.mada.org.qa/technology/tobii-pceye-mini/','https://at.mada.org.qa/technology/tobii-pceye-mini/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/tobiidynavox-pceye-mini.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:55.363Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_firstkeys-widgits_2420072617769','FirstKeys Widgits','FirstKeys Widgits','','','Operating System: Windows First Keys provides a fun introduction to the keyboard by using speech, phonics and Widgit Symbols in colourful and engaging letter exercises to teach literacy skills. You can choose from the wide selection of over 80 activities included with the program or create your own activities using the straightforward and intuitive editor. You can make spelling exercises to support literacy activities, curriculum topics or personalised learning. Additional Information: Manufactu','','','','Operating System: Windows First Keys provides a fun introduction to the keyboard by using speech, phonics and Widgit Symbols in colourful and engaging letter exercises to teach literacy skills. You can choose from the wide selection of over 80 activities included with the program or create your own activities using the straightforward and intuitive editor. You can make spelling exercises to support literacy activities, curriculum topics or personalised learning. Additional Information: Manufacturer: Widgit Software FirstKeys Widgit Manual: https://www.widgit.com/support/fk3/manual.htm','cognition','Widgit Software','','','https://at.mada.org.qa/technology/firstkeys-widgits/','https://at.mada.org.qa/technology/firstkeys-widgits/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/FirstKeys-Widgits.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:39.201Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_chooseit-readymades_2420072622830','ChooseIt Readymades','ChooseIt Readymades','','','Operating System: Windows ChooseIt Readymades cover a wide variety of topics including Numeracy, Literacy and Science. Each activity supports the objectives found in curriculum standards making it easy to find the right skills to practice to meet your learning goals! New activities are added on a regular basis. Additional Information: Manufacturer: HelpKidzLearn (product page) Overview video:','','','','Operating System: Windows ChooseIt Readymades cover a wide variety of topics including Numeracy, Literacy and Science. Each activity supports the objectives found in curriculum standards making it easy to find the right skills to practice to meet your learning goals! New activities are added on a regular basis. Additional Information: Manufacturer: HelpKidzLearn (product page) Overview video:','cognition','HelpKidzLearn','','','https://at.mada.org.qa/technology/chooseit-readymades/','https://at.mada.org.qa/technology/chooseit-readymades/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Choose-IT-Ready-Made.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:16.166Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_boardmaker_2420072628684','Boardmaker','Boardmaker','','','Operating System: Windows Boardmaker software supports learning and communication in the classroom, therapy room or home with this trove of customizable material, including access to over 45,000 Picture Communication Symbols® (PCS). Educators can save time with searchable, ready-made material and curricula for students of all ages and ability levels. Engage students more easily with activities that can be customized for their needs. Select from a diverse choice of PCS – designed to represent all','','','','Operating System: Windows Boardmaker software supports learning and communication in the classroom, therapy room or home with this trove of customizable material, including access to over 45,000 Picture Communication Symbols® (PCS). Educators can save time with searchable, ready-made material and curricula for students of all ages and ability levels. Engage students more easily with activities that can be customized for their needs. Select from a diverse choice of PCS – designed to represent all learners – in the world’s largest symbol library. Additional Information: Manufacturer: Tobii Dynavox (product page)','cognition','Tobii Dynavox','','','https://at.mada.org.qa/technology/boardmaker/','https://at.mada.org.qa/technology/boardmaker/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Boardmaker.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:08.394Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_modmath_2420072632616','ModMath','ModMath','','','Operating System: iOS ModMath is an adaptive program to assist students who struggle with Mathematical notation. The app lets you write and solve math problems right onto the touch screen of an iPad using the custom keypad, and you can print, email, or save to cloud services like Dropbox. Additional Information: Manufacturer: ModMath (http://www.modmath.com)','','','','Operating System: iOS ModMath is an adaptive program to assist students who struggle with Mathematical notation. The app lets you write and solve math problems right onto the touch screen of an iPad using the custom keypad, and you can print, email, or save to cloud services like Dropbox. Additional Information: Manufacturer: ModMath (http://www.modmath.com)','cognition','ModMath','','','https://at.mada.org.qa/technology/modmath/','https://at.mada.org.qa/technology/modmath/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/ModMath.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:09.114Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_texthelp-equatio_2420072638228','TextHelp Equatio','TextHelp Equatio','','','Operating System: Windows, iOS, Android, Chrome EquatIO allows you to create equations, formulas, and more, digitally. Helping to make math and STEM classes more accessible and engaging for every student. Additional Information: Manufacturer: TextHelp TextHelp Equatio Training Resources: https://www.texthelp.com/resources/training/equatio/ Equatio Features for specific learning needs: https://texthelp-website-proof.cdn.prismic.io/texthelp-website-proof/7ba93461-54c1-404f-bb58-d6f61c380e6b_Suppor','','','','Operating System: Windows, iOS, Android, Chrome EquatIO allows you to create equations, formulas, and more, digitally. Helping to make math and STEM classes more accessible and engaging for every student. Additional Information: Manufacturer: TextHelp TextHelp Equatio Training Resources: https://www.texthelp.com/resources/training/equatio/ Equatio Features for specific learning needs: https://texthelp-website-proof.cdn.prismic.io/texthelp-website-proof/7ba93461-54c1-404f-bb58-d6f61c380e6b_Supporting+Specific+Learning+needs+with+EquatIO++%281%29.pdf Video:','cognition','TextHelp','','','https://at.mada.org.qa/technology/texthelp-equatio/','https://at.mada.org.qa/technology/texthelp-equatio/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/TextHelp-Equatio.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:47.205Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_dynamo-maths_2420072643389','Dynamo Maths','Dynamo Maths','','','Operating System: Windows, iOS, Android, Chrome Dynamo Maths aims to support students at risk of developmental dyscalculia and students performing significantly below their peers in maths. Dynamo Maths has two core components: – Dynamo Assessment – Standardised dyscalculia assessment for ages 6 to 11 and baseline at ages 6 to 9. It provides a profile of Number Sense strength and areas of need, supported by an Individual Support Plan signposted to Dynamo Intervention. – Dynamo Intervention – for ','','','','Operating System: Windows, iOS, Android, Chrome Dynamo Maths aims to support students at risk of developmental dyscalculia and students performing significantly below their peers in maths. Dynamo Maths has two core components: – Dynamo Assessment – Standardised dyscalculia assessment for ages 6 to 11 and baseline at ages 6 to 9. It provides a profile of Number Sense strength and areas of need, supported by an Individual Support Plan signposted to Dynamo Intervention. – Dynamo Intervention – for ages 6 to 11 and incorporates a purposeful triple-pathway resources and a range of SEN support tools. Proven and ready for Catch-up and blended learning strategies. Additional Information: Manufacturer: JellyJames Publishing (https://dynamomaths.co.uk) Dynamo Maths Video Tutorial:','cognition','JellyJames Publishing','','','https://at.mada.org.qa/technology/dynamo-maths/','https://at.mada.org.qa/technology/dynamo-maths/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Dynamo-Maths.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:35.357Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_talking-calculator_2420072648685','Talking Calculator','Talking Calculator','','','Operating System: Other A talking calculator has a built-in speech synthesizer that reads aloud each number, symbol, or operation key a user presses; it also vocalizes the answer to the problem. Additional Information: Manufacturer: Attainment Company (https://www.attainmentcompany.com)','','','','Operating System: Other A talking calculator has a built-in speech synthesizer that reads aloud each number, symbol, or operation key a user presses; it also vocalizes the answer to the problem. Additional Information: Manufacturer: Attainment Company (https://www.attainmentcompany.com)','cognition','Attainment Company','','','https://at.mada.org.qa/technology/talking-calculator/','https://at.mada.org.qa/technology/talking-calculator/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Talking-Calculator.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:41.060Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_google-home_2420072652249','Google Home','Google Home','','','Operating System: Android, Chrome Google Home is a brand of smart speakers developed by Google. Google Home speakers enable users to speak voice commands to interact with services through Google’s intelligent personal assistant called Google Assistant. A large number of services, both in-house and third-party, are integrated, allowing users to listen to music, control playback of videos or photos, or receive news updates entirely by voice. Google Home devices also have integrated support for hom','','','','Operating System: Android, Chrome Google Home is a brand of smart speakers developed by Google. Google Home speakers enable users to speak voice commands to interact with services through Google’s intelligent personal assistant called Google Assistant. A large number of services, both in-house and third-party, are integrated, allowing users to listen to music, control playback of videos or photos, or receive news updates entirely by voice. Google Home devices also have integrated support for home automation, letting users control smart home appliances with their voice. Additional Information: Manufacturer: Google https://support.google.com/chromecast/answer/7071794?hl=en&co=GENIE.Platform%3DAndroid','cognition','Google','','','https://at.mada.org.qa/technology/google-home/','https://at.mada.org.qa/technology/google-home/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Google-Home.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:40.962Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_clicker-8-english-and-arabic_2420072658419','Clicker 8 (English and Arabic)','Clicker 8 (English and Arabic)','','','Operating System: Windows, iOS, Chrome Clicker 8 is upgraded version from Clicker 7, which is combining inclusive literacy tools on it. Clicker Grids enable pupils to write with whole words and phrases. Emerging writers build sentences word-by-word, while Word Banks provide scaffolding to support developing writers. Clicker 8’s new ‘Picturize’ button instantly adds pictures to any Clicker Grid, helping children to find the word they want. Choose from over 4500 Clicker curriculum pictures or use ','','','','Operating System: Windows, iOS, Chrome Clicker 8 is upgraded version from Clicker 7, which is combining inclusive literacy tools on it. Clicker Grids enable pupils to write with whole words and phrases. Emerging writers build sentences word-by-word, while Word Banks provide scaffolding to support developing writers. Clicker 8’s new ‘Picturize’ button instantly adds pictures to any Clicker Grid, helping children to find the word they want. Choose from over 4500 Clicker curriculum pictures or use your own. Make curriculum content accessible for all with talking Clicker Books, support emergent readers and EAL pupils with Matching Sets, and use Talk Sets to develop speaking and listening skills. Organising ideas is a vital first step in the writing process, and one that many learners struggle with. Clicker includes a child-friendly mind mapping area to help learners prepare for writing. Clicker includes free access to LearningGrids, an ever-growing bank of ready-made classroom resources created by our curriculum team. Additional Information: Manufacturer: Crick Software Clicker 8 Training and Support: https://www.cricksoft.com/uk/clicker/training-and-support Video','cognition','Crick Software','','','https://at.mada.org.qa/technology/clicker-8-english-and-arabic/','https://at.mada.org.qa/technology/clicker-8-english-and-arabic/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Clicker-8.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:23.734Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_chooseit-maker_2420072662228','ChooseIt Maker','ChooseIt Maker','','','Operating System: Windows, iOS Create, edit and play personalised learning materials that can be used in your classroom and with individual students securely online and then download them to your iPad or Android tablet. With its carefully designed ‘easy flow’ editor, take a photo with your web cam, record sounds, draw or paint and make an activity with your child or class in minutes. They can all join in and then proudly present it to the rest of the school, family and friends. ChooseIt! Maker i','','','','Operating System: Windows, iOS Create, edit and play personalised learning materials that can be used in your classroom and with individual students securely online and then download them to your iPad or Android tablet. With its carefully designed ‘easy flow’ editor, take a photo with your web cam, record sounds, draw or paint and make an activity with your child or class in minutes. They can all join in and then proudly present it to the rest of the school, family and friends. ChooseIt! Maker is an important tool for those learners who respond best to familiar materials, such as pictures of themselves, their families, their classmates and places they know well. Additional Information: Manufacturer: HelpKidzLearn (product page)','cognition','HelpKidzLearn','','','https://at.mada.org.qa/technology/chooseit-maker/','https://at.mada.org.qa/technology/chooseit-maker/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/ChooseIt-Maker-Series.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:14.333Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_clicker_2420072668809','Clicker','Clicker','','','Operating System: Windows, iOS Clicker is a software designed to help struggling readers, writers and English language learners to access support tools they need at school, work or home. The program can help individuals with Dyslexia, Learning Difficulties, Speech or Language Impairments, Physical Disabilities, Low Vision, Autistic Learners, and Downs Syndrome. The program has a word processor on top and a grid with different cells that contains letters, words or phrases to help children to writ','','','','Operating System: Windows, iOS Clicker is a software designed to help struggling readers, writers and English language learners to access support tools they need at school, work or home. The program can help individuals with Dyslexia, Learning Difficulties, Speech or Language Impairments, Physical Disabilities, Low Vision, Autistic Learners, and Downs Syndrome. The program has a word processor on top and a grid with different cells that contains letters, words or phrases to help children to write sentences without typing them. Additionally, it allows the user to hear before writing and even highlights the text as it’s spoken. Furthermore, it allows users to write with pictures and animate their writings. Also, the program provides free learning resources as well as it allows the user to create his own sets of grids, links them, and have full-screen grids. As well, it supports voice recording, MP3 sounds and MPEG videos. Additional Information: Manufacturer: Crick Software (product page, documentation and support) Introduction Video:','cognition','Crick Software','','','https://at.mada.org.qa/technology/clicker/','https://at.mada.org.qa/technology/clicker/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Clicker-7.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:13:21.870Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_sensory-guru_242007267450','Sensory Guru','Sensory Guru','','','Operating System: Other Our Sensory Rooms are focused on inclusion and incorporate the latest in sensory technology, helping to reimagine how a sensory room looks, feels and functions. Our spaces offer content-rich interactive experiences providing social, educational and therapeutic benefits for all ages and abilities. Spaces designed by Sensory Guru offer multi-modal access and variable levels of stimulation. We also ensure that they are easy for staff to set up, use and customise.The design t','','','','Operating System: Other Our Sensory Rooms are focused on inclusion and incorporate the latest in sensory technology, helping to reimagine how a sensory room looks, feels and functions. Our spaces offer content-rich interactive experiences providing social, educational and therapeutic benefits for all ages and abilities. Spaces designed by Sensory Guru offer multi-modal access and variable levels of stimulation. We also ensure that they are easy for staff to set up, use and customise.The design team like to collaborate with clients to identify the key needs and desired outcomes for their users. Each space is scalable to suit the the needs of different individuals and is based on rewards, successes and exploration to grow a users confidence and exercise a range of skills. With our Sensory Learning Environments, customisation is vast. We will work with you to provide not only hardware and installation services, but also the content and user experience too. We are able to configure a wide range of access devices including IR, and wireless switches, gesture and camera tracking, eye control, modified game controllers and a range of bespoke input devices. We provide a wide range of options for the development of sensory rooms and hydrotherapy pools. From simple colour wash lighting to interactive projection walls, we can deliver a design that will inspire and stimulate your students. We have created an online design platform to collaborate with our clients. This puts you in control from the outset and enables you to modify the designs in real-time to ensure you are happy with the direction. Additional Information: Manufacturer: Sensory Guru (https://sensoryguru.com/sensory-eye-fx-downloads/)','cognition','Sensory Guru','','','https://at.mada.org.qa/technology/sensory-guru/','https://at.mada.org.qa/technology/sensory-guru/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Sensory-Guru-.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:26.877Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_inclusive-talking-photo-album-pro_2420072679829','Talking Photo Album','Talking Photo Album','','','Operating System: Other The Talking Photo Album is an easy-to-use speech output device with a total of 20 pages, each with an individual message capacity of 10 seconds. Great for talking stories, communication books, step-by-step instructions, memory books and personal information. Insert photos or picture/text cards into the transparent envelopes and record a corresponding message with up to 18 seconds of recording time on each page. Additional Information: Manufacturer: Attainment Company More','','','','Operating System: Other The Talking Photo Album is an easy-to-use speech output device with a total of 20 pages, each with an individual message capacity of 10 seconds. Great for talking stories, communication books, step-by-step instructions, memory books and personal information. Insert photos or picture/text cards into the transparent envelopes and record a corresponding message with up to 18 seconds of recording time on each page. Additional Information: Manufacturer: Attainment Company More information at Attainment’s Talking Photo Album User’s Guide (attainmentcompany.com)','cognition','Attainment Company','','','https://at.mada.org.qa/technology/inclusive-talking-photo-album-pro/','https://at.mada.org.qa/technology/inclusive-talking-photo-album-pro/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Inclusive-Talking-Photo-Album-Pro.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:42.959Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_quick-talker-7_24200726841','Quick talker Series','Quick talker Series','','','Operating System: Other A portable dedicated speech generating device that features 7-message locations and 6-minutes of record time. Simply switching between the five available recording levels provides up to 23-messages. Includes built-in carrying handle. Easy-to-use, go-anywhere communicator! With QuickTalker 7, your students will be ready to start communicating in minutes. The seven message locations, 6-minutes of total recording time, and five available levels provide the flexibility you ne','','','','Operating System: Other A portable dedicated speech generating device that features 7-message locations and 6-minutes of record time. Simply switching between the five available recording levels provides up to 23-messages. Includes built-in carrying handle. Easy-to-use, go-anywhere communicator! With QuickTalker 7, your students will be ready to start communicating in minutes. The seven message locations, 6-minutes of total recording time, and five available levels provide the flexibility you need to customize the learning outcomes for each student. It comes in different sizes with same features: QuickTalker 7, 12, 23 Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/) More information at https://ablenetinc.zendesk.com/hc/en-us/sections/360011783952-QuickTalker-FT Video:','cognition','AbleNet','','','https://at.mada.org.qa/technology/quick-talker-7/','https://at.mada.org.qa/technology/quick-talker-7/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Quick-talker-7.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:14:23.012Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_kinova-jaco-assistive-robotic-arm_2420072688918','Kinova Jaco Assistive Robotic Arm','Kinova Jaco Assistive Robotic Arm','','','Operating System: Other The Kinova Jaco assistive robotic arm features 6-axis movement corresponding to shoulder, elbow, and wrist, allowing 16 movements in all to mimic the smoothness and versatility of a fully functioning human arm. Mount it on your motorized wheelchair and take full control using the chair’s joystick, head control, sip-and-puff, head array system, or almost any other interface, in combination. Additional Information: Manufacturer: Kinova inc. (https://www.kinovarobotics.com/)','','','','Operating System: Other The Kinova Jaco assistive robotic arm features 6-axis movement corresponding to shoulder, elbow, and wrist, allowing 16 movements in all to mimic the smoothness and versatility of a fully functioning human arm. Mount it on your motorized wheelchair and take full control using the chair’s joystick, head control, sip-and-puff, head array system, or almost any other interface, in combination. Additional Information: Manufacturer: Kinova inc. (https://www.kinovarobotics.com/) Video:','mobility','Kinova inc.','','','https://at.mada.org.qa/technology/kinova-jaco-assistive-robotic-arm/','https://at.mada.org.qa/technology/kinova-jaco-assistive-robotic-arm/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/kinova-assistive-robotic-arm.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T11:36:33.248Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_obi-robotic-feeding-device_2420072693224','Obi robotic feeding device','Obi robotic feeding device','','','Operating System: Other Obi is a revolutionary dining device for individuals who lack upper extremity function. Obi increases independence, social interaction, and effective food capture like never before. With the momentary touch of a switch, Obi allows users to select between four compartments of food and command when the food is captured and delivered to the mouth. Additional Information: Manufacturer: Kinova (product page) Obi user guide: https://www.kinovarobotics.com/en/assistive-technolog','','','','Operating System: Other Obi is a revolutionary dining device for individuals who lack upper extremity function. Obi increases independence, social interaction, and effective food capture like never before. With the momentary touch of a switch, Obi allows users to select between four compartments of food and command when the food is captured and delivered to the mouth. Additional Information: Manufacturer: Kinova (product page) Obi user guide: https://www.kinovarobotics.com/en/assistive-technologies/column-a3/eating-devices Video:','mobility','Kinova','','','https://at.mada.org.qa/technology/obi-robotic-feeding-device/','https://at.mada.org.qa/technology/obi-robotic-feeding-device/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Obi-feeding-robot.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:19:58.760Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_desmos-accessible-calculator_2420072697319','Desmos Accessible Calculator','Desmos Accessible Calculator','','','Operating System: Windows, iOS, Android, Chrome Desmos is online calculators, which include a four-function, scientific, and graphing calculator, are available free to the public. The online calculators can be accessed with a computer, tablet, or other personal device. Also Desmos apps can be downloaded to iOS or Android devices. Desmos provides accessibility features, such as accessible by screen readers, audio tracing to hear a single function or the entire equations, or keyboard shortcuts for','','','','Operating System: Windows, iOS, Android, Chrome Desmos is online calculators, which include a four-function, scientific, and graphing calculator, are available free to the public. The online calculators can be accessed with a computer, tablet, or other personal device. Also Desmos apps can be downloaded to iOS or Android devices. Desmos provides accessibility features, such as accessible by screen readers, audio tracing to hear a single function or the entire equations, or keyboard shortcuts for ease access. Additional Information: Manufacturer: Desmos (official website) Desmos Support at https://help.desmos.com/hc/en-us Desmos introduction video','mobility','Desmos','','','https://at.mada.org.qa/technology/desmos-accessible-calculator/','https://at.mada.org.qa/technology/desmos-accessible-calculator/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Desmos.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:43.790Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_bjoy-chin_2420072701518','BJoy Chin','BJoy Chin','','','Operating System: Other Control the computer with your chin The BJOY Chin is the best alternative to use the mouse with your chin. Its small size, position of the buttons, accuracy and all the mounting options and possibilities make this mouse a very versatile device. It is part of the BJOY range of products: it can be tailored to the user’s needs and capabilities and the operation can be customized using the BJOY Software. Use your mouse with accuracy and ergonomics with the movement of your he','','','','Operating System: Other Control the computer with your chin The BJOY Chin is the best alternative to use the mouse with your chin. Its small size, position of the buttons, accuracy and all the mounting options and possibilities make this mouse a very versatile device. It is part of the BJOY range of products: it can be tailored to the user’s needs and capabilities and the operation can be customized using the BJOY Software. Use your mouse with accuracy and ergonomics with the movement of your head. Access your favourite apps with comfort and simplicity. Customise your mouse if you want that it suits you better. We can manufacture it according to your needs. “Plug and Play” device, compatible with Windows, MacOS and Linux. Use the BJOY Software to modify the function of each button, the cursor speed, the orientation and many other parameters. All settings are stored in the device so you can use your customised mouse to access any device. Additional Information: Manufacturer: Qinera (product page) Video:','mobility','Qinera','','','https://at.mada.org.qa/technology/bjoy-chin/','https://at.mada.org.qa/technology/bjoy-chin/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Bjoy-chin.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:12.207Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_accent-1400_2420072706858','Accent 1400','Accent 1400','','','Operating System: Other The Accent® 1400 features a sleek design with a 14″ high-definition, daylight-readable display and extraordinary all-day battery life. The device is built to last with a magnesium frame, chemically-hardened glass and a moisture-resistant seal. The Accent 1400 also offers multiple access modes supporting a wide array of switches, joysticks, and other tools, and accommodates the PRC Look® Eye Tracking and NuPoint® Head Tracking systems. Features include: vailable with Unity','','','','Operating System: Other The Accent® 1400 features a sleek design with a 14″ high-definition, daylight-readable display and extraordinary all-day battery life. The device is built to last with a magnesium frame, chemically-hardened glass and a moisture-resistant seal. The Accent 1400 also offers multiple access modes supporting a wide array of switches, joysticks, and other tools, and accommodates the PRC Look® Eye Tracking and NuPoint® Head Tracking systems. Features include: vailable with Unity®, LAMP Words for Life®, CoreScanner™, Essence®, UNIDAD®, WordPower™, and WordCore language systems in grid sizes 4-144 Includes NuVoice® and Empower™ software options A wide range of optional voice synthesizers Compatible with 3rd party SAPI voice synthesizers including deliverables from The VoiceKeeper, VocalID and Acapela MyOwnVoice Look module integration, featuring an all-new module using the latest in Eye Tracking technology Splash-resistant from all angles Fanless for silent operation Six IR emitters positioned for optimal coverage Bluetooth® for wireless accessories and phone functionality Front and Rear cameras Wi-Fi Capable* Removable carry handle Additional Information: Manufacturer: Prentke Romich Company (PRC – Saltillo) Download manual and software updates at https://www.prentrom.com/support Accent Youtube Tutorial Channel at https://www.youtube.com/c/PRCBrand/playlists?view=50&sort=dd&shelf_id=6 PRC Accent 1400 introduction video:','mobility','Saltillo','','','https://at.mada.org.qa/technology/accent-1400/','https://at.mada.org.qa/technology/accent-1400/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/accent-1400.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:44:17.997Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_cosmo-switch_2420072711442','Cosmo Switch','Cosmo Switch','','','Operating System: Windows, iOS, Android, Chrome The Cosmo Switch is a unique Bluetooth switch interface for tablets, mobile phones, and computers. It is highly responsive, making it very easy to activate regardless of your motor abilities. The switch lights up in a variety of colours, making it very engaging and providing visual feedback with every press. The Cosmo Switch provides access to all switch accessible apps or software on iOS, OS X, Chromebooks, Windows and Android devices. Use the Cos','','','','Operating System: Windows, iOS, Android, Chrome The Cosmo Switch is a unique Bluetooth switch interface for tablets, mobile phones, and computers. It is highly responsive, making it very easy to activate regardless of your motor abilities. The switch lights up in a variety of colours, making it very engaging and providing visual feedback with every press. The Cosmo Switch provides access to all switch accessible apps or software on iOS, OS X, Chromebooks, Windows and Android devices. Use the CosmoSwitch with your Augmented and Alternative Communication (AAC) software, for switch accessibility, for games, controlling music playback, or even connect to IFTTT to control your calls, lights and more. Additional Information: Manufacturer: Filisia (official website, product page) Cosmo introduction video:','mobility','Filisia','','','https://at.mada.org.qa/technology/cosmo-switch/','https://at.mada.org.qa/technology/cosmo-switch/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/download.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:37.656Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_skoog-2-0_2420072716547','Skoog 2.0','Skoog 2.0','','','Operating System: iOS Skoog works with iPad, so you can play, jam and create music like a rockstar. Just choose a song you love and get playing! The free Skoog app works with Apple Music, Spotify or your music streaming service. It automatically tunes your Skoog, so you learn as you play. It’s creative and fun – that’s what ‘musicplay’ is all about. Additional Information: Manufacturer: Skoogmusic Ltd. (Defunct) Skoog Introduction video:','','','','Operating System: iOS Skoog works with iPad, so you can play, jam and create music like a rockstar. Just choose a song you love and get playing! The free Skoog app works with Apple Music, Spotify or your music streaming service. It automatically tunes your Skoog, so you learn as you play. It’s creative and fun – that’s what ‘musicplay’ is all about. Additional Information: Manufacturer: Skoogmusic Ltd. (Defunct) Skoog Introduction video:','mobility','Skoogmusic Ltd. Defunct','','','https://at.mada.org.qa/technology/skoog-2-0/','https://at.mada.org.qa/technology/skoog-2-0/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/skoog.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:20:38.700Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_grid-3-arabic-english_2420072726318','Grid 3 (Arabic-English)','Grid 3 (Arabic-English)','','','Operating System: Windows Grid 3 is a complete communication solution that enables people to have a voice, control their environment and live more independent lives. It’s designed for anyone with complex communication or access needs and includes a wide range of resources that you can control with touch, switch, eye gaze and pointing devices. You’ll find grid sets for talking with symbols or text, and content for all ages and abilities. A range of vocabularies are available with Grid, from Word ','','','','Operating System: Windows Grid 3 is a complete communication solution that enables people to have a voice, control their environment and live more independent lives. It’s designed for anyone with complex communication or access needs and includes a wide range of resources that you can control with touch, switch, eye gaze and pointing devices. You’ll find grid sets for talking with symbols or text, and content for all ages and abilities. A range of vocabularies are available with Grid, from Word Power to PODD and Vocabulary for Life. All popular symbol libraries are included with Grid 3: Widgit, PCS, Symbol Stix and Snap Photos. Additional Information: Manufacturer: Think SmartBox More information at https://thinksmartbox.com/product/grid-3/','mobility','Think SmartBox','','','https://at.mada.org.qa/technology/grid-3-arabic-english/','https://at.mada.org.qa/technology/grid-3-arabic-english/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Grid-3.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:19:05.000Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_wordpower_2420072754777','WordPower','WordPower','','','Operating System: Windows WordPower uses high-frequency core words to facilitate quick and easy sentence generation. It also includes nouns and adjectives that are organized in logical categories. Grammatical word classes have been included. As a sentence is being built, you often find that the next word you want to say can be spoken with one or two button presses. A spelling/word prediction page is used to spell words that are not included in the vocabulary set. Being a word-based vocabulary, W','','','','Operating System: Windows WordPower uses high-frequency core words to facilitate quick and easy sentence generation. It also includes nouns and adjectives that are organized in logical categories. Grammatical word classes have been included. As a sentence is being built, you often find that the next word you want to say can be spoken with one or two button presses. A spelling/word prediction page is used to spell words that are not included in the vocabulary set. Being a word-based vocabulary, WordPower can be used by a wide age group. Nouns, adjectives and verbs can be added and customized to meet the particular needs of the individual. WordPower is provided in a 20, 25 Touch & Scan, 42 basic, 42, 48, 60 Basic, 60, 80, 108 with Keyboard, 108 button page layout, and 140 Scan & Touch. It is also available in Spanish and French options. Additional Information: Manufacturer: Saltillo More information at https://saltillo.com/products/option/wordpower','mobility','Saltillo','','','https://at.mada.org.qa/technology/wordpower/','https://at.mada.org.qa/technology/wordpower/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/WordPower.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:21:19.675Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_proxtalker_2420072759603','ProxTalker','ProxTalker','','','Operating System: Other The Logan ProxTalker is is an exciting mid-tech communication device which uses RFID (radio frequency identification) technology to enable independent verbal picture communication for non-verbal people of all ages by retrieving vocabulary stored on sound tags to produce real words. This technology allows you to simply place any photo, symbol, or object on a sound tag card and have a voice! To trigger voice output place your sound tag card on any one of the 5 buttons and p','','','','Operating System: Other The Logan ProxTalker is is an exciting mid-tech communication device which uses RFID (radio frequency identification) technology to enable independent verbal picture communication for non-verbal people of all ages by retrieving vocabulary stored on sound tags to produce real words. This technology allows you to simply place any photo, symbol, or object on a sound tag card and have a voice! To trigger voice output place your sound tag card on any one of the 5 buttons and press and the ProxTalker device will say the appropriate sound, word or sentence. Additional Information: Mamufacturer: Logan Tech More information at https://logantech.com/pages/product-manuals','mobility','','','','https://at.mada.org.qa/technology/proxtalker/','https://at.mada.org.qa/technology/proxtalker/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Logan-ProxTalker.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:16:00.243Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_proxpad_2420072764915','ProxPAD','ProxPAD','','','Operating System: Other The Logan ProxPAD is a single location communication and learning aid for persons with physical, visual, or cognitive impairments; it requires tangible objects or other site cues to initiate communication. The ProxPAD uses RFID (radio frequency identification) and gives a voice output and responds to touch or proximity frequency. The Touch mode requires your hand or sound tag to make contact with the blue surface of the ProxPAD while the Proximity mode allows you to swipe','','','','Operating System: Other The Logan ProxPAD is a single location communication and learning aid for persons with physical, visual, or cognitive impairments; it requires tangible objects or other site cues to initiate communication. The ProxPAD uses RFID (radio frequency identification) and gives a voice output and responds to touch or proximity frequency. The Touch mode requires your hand or sound tag to make contact with the blue surface of the ProxPAD while the Proximity mode allows you to swipe the sound card above the surface making it perfect for the person who has limited mobility or needs the ProxPAD mounted under a table or wheelchair tray. Additional Information: Manufacturer – Logan Tech More information at https://logantech.com/pages/product-manuals','mobility','','','','https://at.mada.org.qa/technology/proxpad/','https://at.mada.org.qa/technology/proxpad/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/ProxPAd.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:15:58.296Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_gewa-control-prog_2420072768384','GEWA Control Prog','GEWA Control Prog','','','Operating System: Other Control Prog is a programmable IR–transmitter adapted for persons with physical disabilities. The transmitter can store codes from other remote controls such as TV, Video and DVD. Using Control Prog makes everyday life simpler; you can control everything in your home, from the telephone to lift. No matter what the users’ motor ability and needs are, there are multiple setting possibilities to simplify the use of Control Prog. For a person unable to use “direct touch”, the','','','','Operating System: Other Control Prog is a programmable IR–transmitter adapted for persons with physical disabilities. The transmitter can store codes from other remote controls such as TV, Video and DVD. Using Control Prog makes everyday life simpler; you can control everything in your home, from the telephone to lift. No matter what the users’ motor ability and needs are, there are multiple setting possibilities to simplify the use of Control Prog. For a person unable to use “direct touch”, there are twelve different scanning alternatives. It is possible to connect one or two single–function switches. It is possible to store 241 programmable function positions distributed over 15 levels. There is a coded channel for security functions that requires strict authorisation – such as apartment or house doors. There are options to create sequences (macros). By pushing a button, you can get directly to a text–TV page Additional Information: Manufacturer: Abilia https://www.abilia.com/intl/our-products/environmental-control/controllers/control-prog','mobility','Abilia','','','https://at.mada.org.qa/technology/gewa-control-prog/','https://at.mada.org.qa/technology/gewa-control-prog/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/GEWA-Control-Prog.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:55.212Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_qwayo_2420072773608','Qwayo','Qwayo','','','Operating System: Other The main benefit of the Qwayo is how customisable it is, a user can choose if they want a simple set up with a few functions available, or a more advanced set up as each Qwayo is tailored to the user’s requirements. The Qwayo can be used to control (additionally purchased) Assistive Technology products, for example switching on and off a lamp, fan or radio, using an intercom, raising an alarm, opening and closing doors or raising or lowering a chair or bed. The Qwayo can ','','','','Operating System: Other The main benefit of the Qwayo is how customisable it is, a user can choose if they want a simple set up with a few functions available, or a more advanced set up as each Qwayo is tailored to the user’s requirements. The Qwayo can be used to control (additionally purchased) Assistive Technology products, for example switching on and off a lamp, fan or radio, using an intercom, raising an alarm, opening and closing doors or raising or lowering a chair or bed. The Qwayo can also act as a communication device, allowing people with physical or cognitive disabilities to send and receive calls, e-mails and SMS text messages. The Qwayo can be programmed to have pre-set contact groups or messages to save time. Users can also browse the web using Possum’s accessible web browser and access apps including Kindle which we have configured so that a page can be turned using the switch of choice. The unique technology behind Qwayo takes the user experience to the next level whilst Qwayo’s ability to provide emergency alarm functions – even if Bluetooth, Wi-Fi and Android fail, delivers peace of mind. Additional Information: Manufacturer: Possum http://www.possum.co.uk/products/qwayo/','mobility','Possum','','','https://at.mada.org.qa/technology/qwayo/','https://at.mada.org.qa/technology/qwayo/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Qwayo.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:20:30.965Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_newfreeway_2420072778640','NewFreeway','NewFreeway','','','Operating System: Other NewFreeway is an infrared (IR) and radio frequency (RF) environmental controller that provides simple remote control of a wide range of domestic appliances and entertainment devices. The intuitive interface can be accessed in 3 easy ways, including: 1) Integral touch switch 2) Wired switch 3) IR Remote switch Providing a wider range of users access to environmental control and greater independence. An integral Possum Telecare RF transmitter enables discreet activation of ','','','','Operating System: Other NewFreeway is an infrared (IR) and radio frequency (RF) environmental controller that provides simple remote control of a wide range of domestic appliances and entertainment devices. The intuitive interface can be accessed in 3 easy ways, including: 1) Integral touch switch 2) Wired switch 3) IR Remote switch Providing a wider range of users access to environmental control and greater independence. An integral Possum Telecare RF transmitter enables discreet activation of numerous wireless emergency communication devices including: the Info Pager, Novo Care phone or an existing nurse call system Additional Information: Manufacturer: Possum http://www.possum.co.uk/products/newfreeway/','mobility','Possum','','','https://at.mada.org.qa/technology/newfreeway/','https://at.mada.org.qa/technology/newfreeway/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/NewFreeway.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:19:56.786Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_phonelink_242007278250','PhoneLink','PhoneLink','','','Operating System: Android You can now link an Android phone to an existing environmental controller using the Phonelink hub in combination with the versatile and easy to use Android application. You do not need to upgrade to a new system or use a landline phone with the Phonelink. This new innovative product from Possum enables not just Possum’s range access to a mobile but many other systems that send (IR) infra-red including Abilia’s Control Medi units and communication aids that have an infra','','','','Operating System: Android You can now link an Android phone to an existing environmental controller using the Phonelink hub in combination with the versatile and easy to use Android application. You do not need to upgrade to a new system or use a landline phone with the Phonelink. This new innovative product from Possum enables not just Possum’s range access to a mobile but many other systems that send (IR) infra-red including Abilia’s Control Medi units and communication aids that have an infra-red output. As well as providing a means to make and receive calls, you can also send a dedicated pre-defined message with or without location ID. We can also trigger a voice command to open up a larger number of possibilities easily. Additional Information: Manufacturer: Possum http://www.possum.co.uk/products/phonelink/','mobility','Possum','','','https://at.mada.org.qa/technology/phonelink/','https://at.mada.org.qa/technology/phonelink/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/PhoneLink.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:20:08.691Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_primo-environment-control_2420072787803','Primo+ Environment Control','Primo+ Environment Control','','','Operating System: Other Primo+ enhanced Environmental Control Unit (ECU) empowers people with physical impairments by providing control of the immediate environment through remote operation of electrical appliances and automated devices in the home or workplace. The Possum Primo+ provides an affordable, touch sensitive, dynamic screen Environment Control device combined with switch scanning options. All packaged in an ergonomically styled, highly portable, lightweight yet robust case. Control a ','','','','Operating System: Other Primo+ enhanced Environmental Control Unit (ECU) empowers people with physical impairments by providing control of the immediate environment through remote operation of electrical appliances and automated devices in the home or workplace. The Possum Primo+ provides an affordable, touch sensitive, dynamic screen Environment Control device combined with switch scanning options. All packaged in an ergonomically styled, highly portable, lightweight yet robust case. Control a Telephone, Television, DVD, Stereo, Radio, Heater, Fan, Lights, Windows, Doors, Intercom, Call System and even an Electrically Controlled Bed. The Primo+ can hold up to 140 captured infrared codes as well as embedded Possum and Gewa codes in multiple menus providing the ultimate flexibility in controlling the domestic environment for older or disabled users. A library of selectable clear icons and programmable labels further enhance user choice and the customised nature of this versatile controller. Additional Information: Manufacturer: Possum http://www.possum.co.uk/products/primo/','mobility','Possum','','','https://at.mada.org.qa/technology/primo-environment-control/','https://at.mada.org.qa/technology/primo-environment-control/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Primo-Environment-Control.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:20:18.862Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_clicktophone_2420072791316','ClickToPhone','ClickToPhone','','','Operating System: Android The ClickToPhone App provides a highly customisable and accessible user interface for Mobiles and Tablets that run on the Android operating system. Click To Phone provides direct or scanning access to: •Answer and make calls. •Read, compose and send text messages. •Scan using an external switch or touch the screen. •Take photos and browse the picture gallery. •Play music files. •Text-to-speech communication. •Auditory scanning. • Programmable scanning options. To gain t','','','','Operating System: Android The ClickToPhone App provides a highly customisable and accessible user interface for Mobiles and Tablets that run on the Android operating system. Click To Phone provides direct or scanning access to: •Answer and make calls. •Read, compose and send text messages. •Scan using an external switch or touch the screen. •Take photos and browse the picture gallery. •Play music files. •Text-to-speech communication. •Auditory scanning. • Programmable scanning options. To gain the most from ClickToPhone we highly recommend pairing with the HouseMate PRO Environment Control switch access module. HouseMate provides many enhanced features that have been developed specifically for disability access. Additional Information: Manufacturer: Housemate (product page, user manual, app on Google Play)','mobility','Housemate','','','https://at.mada.org.qa/technology/clicktophone/','https://at.mada.org.qa/technology/clicktophone/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Clicktophone.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:29.732Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_hook-switch-interface_2420072796190','Hook+ Switch Interface','Hook+ Switch Interface','','','Operating System: Other Hook+ is an Apple MFi (Made For iPod etc.) approved switch interface that provides a reliable wired connection to the iPad, iPhone, or iPod touch via the Lightning connector. Hook+ utilises the Apple auto switch configurator and the first time Hook+ is used with an iDevice it will automatically configure the iDevice to use single switch auto scanning or dual switch step scanning based on how many switches are connected to Hook+. Once initially configured, switches can be ','','','','Operating System: Other Hook+ is an Apple MFi (Made For iPod etc.) approved switch interface that provides a reliable wired connection to the iPad, iPhone, or iPod touch via the Lightning connector. Hook+ utilises the Apple auto switch configurator and the first time Hook+ is used with an iDevice it will automatically configure the iDevice to use single switch auto scanning or dual switch step scanning based on how many switches are connected to Hook+. Once initially configured, switches can be manually re-configured to meet the needs of the user. The Apple auto switch configurator is only available on Apple MFi approved switch interfaces. Once Hook+ is connected and Switch Control is configured, you can do almost anything on an iDevice with a switch. Read an eBook, write an email, browse the internet, play games, control your home. Additional Information: Manufacturer: AbleNet https://www.ablenetinc.com/switch-interface/hook-3rd-gen/','mobility','AbleNet','','','https://at.mada.org.qa/technology/hook-switch-interface/','https://at.mada.org.qa/technology/hook-switch-interface/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Hook-Switch-Interface.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:19:10.700Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_housemate_2420072801390','Housemate','Housemate','','','Operating System: Other HouseMate is the smart way to control the world of a person with disability. HouseMate enables people with disabilities to access their smart phone and control their environment. They will be able to independently control their smart phone and use it to operate appliances in their house or work environment. With a single switch and HouseMate Module paired with an Android or iOS device a person with disability will be able to can open the front door and turn on the room li','','','','Operating System: Other HouseMate is the smart way to control the world of a person with disability. HouseMate enables people with disabilities to access their smart phone and control their environment. They will be able to independently control their smart phone and use it to operate appliances in their house or work environment. With a single switch and HouseMate Module paired with an Android or iOS device a person with disability will be able to can open the front door and turn on the room lights, change channels on TV and turn up the heating, make a phone call and send some texts, browse the internet, control thousands of third party apps such as Email, Social Networking, Netflix, and eReaders, shop online, play some music or watch YouTube or listen to Spotify. HouseMate hardware in combination with an iOS or Android device enables the person with disability to do this and much more. The HouseMate hardware module connects via bluetooth to an iphone, iPad, Android phone or Android tablet. The HouseMate provides a user friendly switch accessible interface which enables full control of a mobile phone without the need to touch the keys or touch screen. The phone becomes fully remote controlled via a single switch, multiple switches or even a wheelchair joystick. Housemate can also be controlled by voice using “OK Google” or SIRI commands. Additional Information: Manufacturer: Housemate http://housemate.ie/housemate/','mobility','Housemate','','','https://at.mada.org.qa/technology/housemate/','https://at.mada.org.qa/technology/housemate/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Housemate.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:19:14.650Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_power-link-4-2_2420072805343','Power Link 4','Power Link 4','','','Operating System: Other Six unique modes of control allow you to define exactly how, and for how long, appliances will be turned on. PowerLink will accept any single switch, including our Big or Jelly Beamer wireless switches. We think the PowerLink is one of our best looking products ever, but that’s not even close to the best part. How about an on-board display that lets you set the exact number of minutes or seconds of control? How about a new “Count” mode that allows for easy, precise data c','','','','Operating System: Other Six unique modes of control allow you to define exactly how, and for how long, appliances will be turned on. PowerLink will accept any single switch, including our Big or Jelly Beamer wireless switches. We think the PowerLink is one of our best looking products ever, but that’s not even close to the best part. How about an on-board display that lets you set the exact number of minutes or seconds of control? How about a new “Count” mode that allows for easy, precise data collection? Want more? Choose the new “Two-switch” mode for collaborative activation for safety or cooperative play. PowerLink is available in two international versions: North America and Continental Europe. PowerLink 4 Features: Easy setup with built-in display and simple new design Powerful access with six modes of control Accurate programming and data collection Flexible outlets allow custom positioning of up to two appliances Linkable wireless technology allows Big or Jelly Beamers to be linked to each outlet Two switch input jacks Great looks at a small size Modes of Control: Direct: Behaves like a traditional switch. Count: Behaves like Direct, shows number of activations Two-Switch: Behaves like Direct, both switches must be activated Timed Seconds: Runs appliance from 1 to 99 seconds Timed Minutes: Runs appliance from 1 to 99 minutes Latch: First activation turns appliance ON; second activation turns it OFF Additional Information: Manufacturer: AbleNet https://www.ablenetinc.com/powerlink-4-central-europe/','mobility','AbleNet','','','https://at.mada.org.qa/technology/power-link-4-2/','https://at.mada.org.qa/technology/power-link-4-2/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Power-Link-4.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:20:16.777Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_snap-read_2420072810555','Snap & Read (English/Arabic)','Snap & Read (English/Arabic)','','','Operating System: Windows, iOS, Chrome Snap&Read is the Next-Generation reading tool that can cover the most diverse reading needs. Features: Read Aloud – Listen to text as it’s read aloud across websites, PDFs, and Google Drive. It also reads in other languages Additional Information: Manufacturer: Don Johnston Snap&Read Learning Resources: https://learningtools.donjohnston.com/support/product-resources/#snap-read-learning-academy','','','','Operating System: Windows, iOS, Chrome Snap&Read is the Next-Generation reading tool that can cover the most diverse reading needs. Features: Read Aloud – Listen to text as it’s read aloud across websites, PDFs, and Google Drive. It also reads in other languages Additional Information: Manufacturer: Don Johnston Snap&Read Learning Resources: https://learningtools.donjohnston.com/support/product-resources/#snap-read-learning-academy','mobility','Don Johnston','','','https://at.mada.org.qa/technology/snap-read/','https://at.mada.org.qa/technology/snap-read/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Snap-Read.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:20:46.481Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_symwriter-2_2420072815894','SymWriter 2 (English)','SymWriter 2 (English)','','','Operating System: Windows SymWriter 2 is a symbol-supported word processor that any writer, regardless of literacy levels, can use to create documents. Writers of any age or ability can use the widget Symbols to see the meaning of words as they type, supporting access to new or challenging vocabulary. Additional Information: Manufacturer: Widgit Software (https://www.widgit.com/) SymWriter2 Video Introduction: SymWriter2 User Support: https://www.widgit.com/support/symwriter/index.htm','','','','Operating System: Windows SymWriter 2 is a symbol-supported word processor that any writer, regardless of literacy levels, can use to create documents. Writers of any age or ability can use the widget Symbols to see the meaning of words as they type, supporting access to new or challenging vocabulary. Additional Information: Manufacturer: Widgit Software (https://www.widgit.com/) SymWriter2 Video Introduction: SymWriter2 User Support: https://www.widgit.com/support/symwriter/index.htm','mobility','Widgit Software','','','https://at.mada.org.qa/technology/symwriter-2/','https://at.mada.org.qa/technology/symwriter-2/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/SymWriter-2.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:20:56.308Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_nessy-learning-program_2420072820108','Nessy Learning Program','Nessy Learning Program','','','Operating System: Windows, iOS, Android, Chrome Nessy has been making fun, educational software for children since 1999 and has developed a reputation for exceptional quality. Nessy offers the complete dyslexia aware solution with a suite of multisensory products aimed at making learning to read, write and spell fun. Additional Information: Manufacturer: Nessy Learning (official website) Nessy Learning Program User Support: https://nessy.zendesk.com/hc/en-gb Nessy Learning Program Introduction V','','','','Operating System: Windows, iOS, Android, Chrome Nessy has been making fun, educational software for children since 1999 and has developed a reputation for exceptional quality. Nessy offers the complete dyslexia aware solution with a suite of multisensory products aimed at making learning to read, write and spell fun. Additional Information: Manufacturer: Nessy Learning (official website) Nessy Learning Program User Support: https://nessy.zendesk.com/hc/en-gb Nessy Learning Program Introduction Video:','mobility','Nessy','','','https://at.mada.org.qa/technology/nessy-learning-program/','https://at.mada.org.qa/technology/nessy-learning-program/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Nessy-Learning-Program.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:44:17.996Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_look-to-learn-2_2420072825225','Look to Learn','Look to Learn','','','Operating System: Windows A motivating and fun way to get started with eye gaze technology including over 40 activities. With over 40 specially created activities, Look to Learn is a motivating and fun way to get started with eye gaze technology. Every activity has been developed in consultation with teachers and therapists to improve access and choice making skills. Expand the Look to Learn experience with 26 new activities for anyone starting out with eye gaze. Again we have worked with teache','','','','Operating System: Windows A motivating and fun way to get started with eye gaze technology including over 40 activities. With over 40 specially created activities, Look to Learn is a motivating and fun way to get started with eye gaze technology. Every activity has been developed in consultation with teachers and therapists to improve access and choice making skills. Expand the Look to Learn experience with 26 new activities for anyone starting out with eye gaze. Again we have worked with teachers and therapists to make sure every activity is fun yet teaches valuable skills. Get creative and load in your favourite images and videos to make the activities your own. The built in analysis tool to show where somebody has looked on the screen during an activity in the form of a heat map. These heat maps can be saved, printed and used to measure progress and record successes. You can also assess eye tracking, targeting and choice making skills. Additional Information: Manufacturer: SmartBox (https://thinksmartbox.com) Look to Learn Video Introduction: Look to Learn Manual: https://thinksmartbox.com/wp/wp-content/uploads/2018/11/Look-to-Learn-Manual-Oct-2018-Web.pdf','mobility','SmartBox','','','https://at.mada.org.qa/technology/look-to-learn-2/','https://at.mada.org.qa/technology/look-to-learn-2/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Look-to-Learn.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:19:39.985Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_mouse-skills_2420072830877','Mouse Skills','Mouse Skills','','','Operating System: Windows Learners are taken stage by stage through the many applications of the mouse. Move the mouse over an object, drag and drop, drag along a path and the use of drop-down menus are all represented. Various clicking activities can be found such as clicking anywhere, click timing and double clicking. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk/)','','','','Operating System: Windows Learners are taken stage by stage through the many applications of the mouse. Move the mouse over an object, drag and drop, drag along a path and the use of drop-down menus are all represented. Various clicking activities can be found such as clicking anywhere, click timing and double clicking. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk/)','mobility','Inclusive Technology','','','https://at.mada.org.qa/technology/mouse-skills/','https://at.mada.org.qa/technology/mouse-skills/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/mouse-skills.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:19:51.264Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_eyegaze-learning-curve_2420072834818','EyeGaze Learning Curve','EyeGaze Learning Curve','','','Operating System: Windows Learning Curve provides 54 fun and engaging interactive activities specially created to teach early eye gaze access and develop choice making skills. This collection takes users on the learning curve from assessment and cause and effect understanding through to using eye gaze for communication, learning and leisure. All users on their first steps with eye gaze can use these activities to improve their accuracy and understanding of eye gaze in preparation for using other','','','','Operating System: Windows Learning Curve provides 54 fun and engaging interactive activities specially created to teach early eye gaze access and develop choice making skills. This collection takes users on the learning curve from assessment and cause and effect understanding through to using eye gaze for communication, learning and leisure. All users on their first steps with eye gaze can use these activities to improve their accuracy and understanding of eye gaze in preparation for using other communication and learning software. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk/) Inclusive EyeGaze Learning Curve Introduction Video:','mobility','Inclusive Technology','','','https://at.mada.org.qa/technology/eyegaze-learning-curve/','https://at.mada.org.qa/technology/eyegaze-learning-curve/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Learning-curve.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:53.012Z',NULL,NULL,NULL);
