INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_irisbond-duo-eye-tracker_2420072843410','Irisbond Duo Eye Tracker','Irisbond Duo Eye Tracker','','','Operating System: Windows Irisbond Duo is a mobile, lightweight eye tracker that connects to your Windows PC, laptop or tablet to give you eye gaze access. Additional Information: Manufacturer: Irisbond Irisbond Due Quick Start Guide : https://www.irisbond.com/wp-content/uploads/2021/03/Irisbond_Duo_Quick_Start_Guide_v4.0.pdf','','','','Operating System: Windows Irisbond Duo is a mobile, lightweight eye tracker that connects to your Windows PC, laptop or tablet to give you eye gaze access. Additional Information: Manufacturer: Irisbond Irisbond Due Quick Start Guide : https://www.irisbond.com/wp-content/uploads/2021/03/Irisbond_Duo_Quick_Start_Guide_v4.0.pdf','mobility','Irisbond','','','https://at.mada.org.qa/technology/irisbond-duo-eye-tracker/','https://at.mada.org.qa/technology/irisbond-duo-eye-tracker/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/irisbond.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:19:20.328Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_switch-skills-series-2_2420072849454','Switch Skills Series','Switch Skills Series','','','Operating System: Windows Switch Skills 1: This collection of easy switch timing games have themes which motivate children who understand cause and effect to develop more disciplined switch use. The activities also encourage speaking and listening and help develop concentration skills. The graphics are bright and clear and this combined with sound and music makes the games suitable for children. Switch Skills 2: It is early learning cause and effect software with 20 different activities The user','','','','Operating System: Windows Switch Skills 1: This collection of easy switch timing games have themes which motivate children who understand cause and effect to develop more disciplined switch use. The activities also encourage speaking and listening and help develop concentration skills. The graphics are bright and clear and this combined with sound and music makes the games suitable for children. Switch Skills 2: It is early learning cause and effect software with 20 different activities The user presses the switch or touch screen to activate a bright animation with music. Higher-level activities require increased visual discrimination but are still activated by the press of a switch. ‘Gopher in a Drainpipe’ and ‘Mystery Egg’ can be trialed at www.helpkidzlearn.com. Switch Skills 3: It is a software has sixteen graded activities that aim to develop scanning skills. Some of the activities are error-free whilst others require good switch timing skills. Other variations include Switch skills 1 Set 1, Switch Skills 2 Set 2, Switch Skills 1 Set 2, Switch Skills 2 Set 1, Switch Skills Scanning, Switch Skills Champions. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk/) Switch Skills Series Demonstration Video:','mobility','Inclusive Technology','','','https://at.mada.org.qa/technology/switch-skills-series-2/','https://at.mada.org.qa/technology/switch-skills-series-2/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Switch-Skills-Series.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:20:52.246Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_switchit-jigsaw-maker-2_2420072853309','SwitchIt! Jigsaw Maker 2','SwitchIt! Jigsaw Maker 2','','','Operating System: Windows Jigsaw Maker allows to create gizsaw puzzles activities for children with learning difficulties. The jigsaws can be completed in 4 ways, which provides activities with a finely graded progression in skill level: Cause and effect – just press a switch to build the picture. This level can also be used in a reveal game: The picture appears bit by bit, so learners can try and guess what the picture is before it is completed. Click on any piece – it will jump into place. An ','','','','Operating System: Windows Jigsaw Maker allows to create gizsaw puzzles activities for children with learning difficulties. The jigsaws can be completed in 4 ways, which provides activities with a finely graded progression in skill level: Cause and effect – just press a switch to build the picture. This level can also be used in a reveal game: The picture appears bit by bit, so learners can try and guess what the picture is before it is completed. Click on any piece – it will jump into place. An easy introduction to making jigsaws. Find the piece that fits the place chosen by the computer. A more demanding activity. Drag the pieces into their correct places. This level simulates making a real jigsaw. Support is provided for those players who find dragging with the mouse difficult, and this level can also be played using single clicks of the mouse. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk/) SwitchIt Jigsaw Maker 2 Video Introduction','mobility','Inclusive Technology','','','https://at.mada.org.qa/technology/switchit-jigsaw-maker-2/','https://at.mada.org.qa/technology/switchit-jigsaw-maker-2/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/SwitchIt-Jigsaw-Maker-2.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:20:54.361Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_tobii-pceye-mini_2420072858953','Tobii PCEye Mini','Tobii PCEye Mini','','','Operating System: Windows The PCEye Mini includes a PCEye Mini eye tracker and the new Windows Control software. Windows Control enables full computer access on a Windows PC via eye gaze or eye gaze combined with switch input, replacing the standard keyboard and mouse. Additional Information: Manufacturer: Tobii Dynabox Tobii PCEye Mini – Windows Control Training and Tutorials: https://www.tobiidynavox.com/support-training/windows-control-2/','','','','Operating System: Windows The PCEye Mini includes a PCEye Mini eye tracker and the new Windows Control software. Windows Control enables full computer access on a Windows PC via eye gaze or eye gaze combined with switch input, replacing the standard keyboard and mouse. Additional Information: Manufacturer: Tobii Dynabox Tobii PCEye Mini – Windows Control Training and Tutorials: https://www.tobiidynavox.com/support-training/windows-control-2/','mobility','Tobii Dynavox','','','https://at.mada.org.qa/technology/tobii-pceye-mini/','https://at.mada.org.qa/technology/tobii-pceye-mini/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/tobiidynavox-pceye-mini.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:21:10.314Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_hitch-2-0_2420072862459','Hitch 2.0','Hitch 2.0','','','Operating System: Other Hitch 2 is a plug-and-play USB computer switch interface with inputs for up to five switches or one joystick with a 9-pin D plug. When used with switch accessible software, users are able to control their computer, actively learn, and have fun. Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/)','','','','Operating System: Other Hitch 2 is a plug-and-play USB computer switch interface with inputs for up to five switches or one joystick with a 9-pin D plug. When used with switch accessible software, users are able to control their computer, actively learn, and have fun. Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/)','mobility','AbleNet','','','https://at.mada.org.qa/technology/hitch-2-0/','https://at.mada.org.qa/technology/hitch-2-0/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Hitch.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:19:08.638Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_tecla-e_2420072867204','Tecla-e','Tecla-e','','','Operating System: Other Tecla-e is an assistive device that gives people with upper-body mobility impairments the ability to fully access smart devices and technology. Users can control multiple devices to send and receive emails and text messages, browse the web, watch videos, launch and use apps, read books, turn on their TV, control their thermostat, turn the lights on or off, make (or hang up) phone calls, enter commands using Siri, and more – all with ONE tecla-e. Additional Information: Ma','','','','Operating System: Other Tecla-e is an assistive device that gives people with upper-body mobility impairments the ability to fully access smart devices and technology. Users can control multiple devices to send and receive emails and text messages, browse the web, watch videos, launch and use apps, read books, turn on their TV, control their thermostat, turn the lights on or off, make (or hang up) phone calls, enter commands using Siri, and more – all with ONE tecla-e. Additional Information: Manufacturer: Tecla (https://gettecla.com/ Tecla Introduction video:','mobility','Tecla','','','https://at.mada.org.qa/technology/tecla-e/','https://at.mada.org.qa/technology/tecla-e/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Tecla.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:21:00.799Z',NULL,NULL,NULL);
