INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_texthelp-equatio_2420073021132','TextHelp Equatio','TextHelp Equatio','','','Operating System: Windows, iOS, Android, Chrome EquatIO allows you to create equations, formulas, and more, digitally. Helping to make math and STEM classes more accessible and engaging for every student. Additional Information: Manufacturer: TextHelp TextHelp Equatio Training Resources: https://www.texthelp.com/resources/training/equatio/ Equatio Features for specific learning needs: https://texthelp-website-proof.cdn.prismic.io/texthelp-website-proof/7ba93461-54c1-404f-bb58-d6f61c380e6b_Suppor','','','','Operating System: Windows, iOS, Android, Chrome EquatIO allows you to create equations, formulas, and more, digitally. Helping to make math and STEM classes more accessible and engaging for every student. Additional Information: Manufacturer: TextHelp TextHelp Equatio Training Resources: https://www.texthelp.com/resources/training/equatio/ Equatio Features for specific learning needs: https://texthelp-website-proof.cdn.prismic.io/texthelp-website-proof/7ba93461-54c1-404f-bb58-d6f61c380e6b_Supporting+Specific+Learning+needs+with+EquatIO++%281%29.pdf Video:','mobility','TextHelp','','','https://at.mada.org.qa/technology/texthelp-equatio/','https://at.mada.org.qa/technology/texthelp-equatio/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/TextHelp-Equatio.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:21:02.693Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_dynamo-maths_2420073026510','Dynamo Maths','Dynamo Maths','','','Operating System: Windows, iOS, Android, Chrome Dynamo Maths aims to support students at risk of developmental dyscalculia and students performing significantly below their peers in maths. Dynamo Maths has two core components: – Dynamo Assessment – Standardised dyscalculia assessment for ages 6 to 11 and baseline at ages 6 to 9. It provides a profile of Number Sense strength and areas of need, supported by an Individual Support Plan signposted to Dynamo Intervention. – Dynamo Intervention – for ','','','','Operating System: Windows, iOS, Android, Chrome Dynamo Maths aims to support students at risk of developmental dyscalculia and students performing significantly below their peers in maths. Dynamo Maths has two core components: – Dynamo Assessment – Standardised dyscalculia assessment for ages 6 to 11 and baseline at ages 6 to 9. It provides a profile of Number Sense strength and areas of need, supported by an Individual Support Plan signposted to Dynamo Intervention. – Dynamo Intervention – for ages 6 to 11 and incorporates a purposeful triple-pathway resources and a range of SEN support tools. Proven and ready for Catch-up and blended learning strategies. Additional Information: Manufacturer: JellyJames Publishing (https://dynamomaths.co.uk) Dynamo Maths Video Tutorial:','mobility','JellyJames Publishing','','','https://at.mada.org.qa/technology/dynamo-maths/','https://at.mada.org.qa/technology/dynamo-maths/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Dynamo-Maths.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:49.299Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_google-home_2420073030106','Google Home','Google Home','','','Operating System: Android, Chrome Google Home is a brand of smart speakers developed by Google. Google Home speakers enable users to speak voice commands to interact with services through Google’s intelligent personal assistant called Google Assistant. A large number of services, both in-house and third-party, are integrated, allowing users to listen to music, control playback of videos or photos, or receive news updates entirely by voice. Google Home devices also have integrated support for hom','','','','Operating System: Android, Chrome Google Home is a brand of smart speakers developed by Google. Google Home speakers enable users to speak voice commands to interact with services through Google’s intelligent personal assistant called Google Assistant. A large number of services, both in-house and third-party, are integrated, allowing users to listen to music, control playback of videos or photos, or receive news updates entirely by voice. Google Home devices also have integrated support for home automation, letting users control smart home appliances with their voice. Additional Information: Manufacturer: Google https://support.google.com/chromecast/answer/7071794?hl=en&co=GENIE.Platform%3DAndroid','mobility','Google','','','https://at.mada.org.qa/technology/google-home/','https://at.mada.org.qa/technology/google-home/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Google-Home.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:19:03.051Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_accuratus-monster-2_242007303582','Accuratus Monster 2','Accuratus Monster 2','','','Operating System: Windows, iOS, Chrome The Accuratus Monster keyboard is ideal for users who may have a visual impairment or cerebral palsy. The large keys assists easily with typing whereas standard keyboard may be a hindrance, the Accuratus Monster Keyboard integrates number keys, punctuation keys and a full size keyboard. Both Arabic and English keyboards are available. Additional Information: Manufacturer: Accuratus (product page)','','','','Operating System: Windows, iOS, Chrome The Accuratus Monster keyboard is ideal for users who may have a visual impairment or cerebral palsy. The large keys assists easily with typing whereas standard keyboard may be a hindrance, the Accuratus Monster Keyboard integrates number keys, punctuation keys and a full size keyboard. Both Arabic and English keyboards are available. Additional Information: Manufacturer: Accuratus (product page)','mobility','Accuratus','','','https://at.mada.org.qa/technology/accuratus-monster-2/','https://at.mada.org.qa/technology/accuratus-monster-2/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Accuratus-key.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:00.641Z',NULL,NULL,NULL);
