INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_clicker-8-english-and-arabic_2420073044713','Clicker 8 (English and Arabic)','Clicker 8 (English and Arabic)','','','Operating System: Windows, iOS, Chrome Clicker 8 is upgraded version from Clicker 7, which is combining inclusive literacy tools on it. Clicker Grids enable pupils to write with whole words and phrases. Emerging writers build sentences word-by-word, while Word Banks provide scaffolding to support developing writers. Clicker 8’s new ‘Picturize’ button instantly adds pictures to any Clicker Grid, helping children to find the word they want. Choose from over 4500 Clicker curriculum pictures or use ','','','','Operating System: Windows, iOS, Chrome Clicker 8 is upgraded version from Clicker 7, which is combining inclusive literacy tools on it. Clicker Grids enable pupils to write with whole words and phrases. Emerging writers build sentences word-by-word, while Word Banks provide scaffolding to support developing writers. Clicker 8’s new ‘Picturize’ button instantly adds pictures to any Clicker Grid, helping children to find the word they want. Choose from over 4500 Clicker curriculum pictures or use your own. Make curriculum content accessible for all with talking Clicker Books, support emergent readers and EAL pupils with Matching Sets, and use Talk Sets to develop speaking and listening skills. Organising ideas is a vital first step in the writing process, and one that many learners struggle with. Clicker includes a child-friendly mind mapping area to help learners prepare for writing. Clicker includes free access to LearningGrids, an ever-growing bank of ready-made classroom resources created by our curriculum team. Additional Information: Manufacturer: Crick Software Clicker 8 Training and Support: https://www.cricksoft.com/uk/clicker/training-and-support Video','mobility','Crick Software','','','https://at.mada.org.qa/technology/clicker-8-english-and-arabic/','https://at.mada.org.qa/technology/clicker-8-english-and-arabic/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Clicker-8.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:33.979Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_bigkeys-lx-keyboard_2420073049262','BigKeys LX Keyboard','BigKeys LX Keyboard','','','Operating System: Windows, iOS BigKeys LX is a keyboard designed for people with visual impairments. The device can be configured as standard QWERTY or ABC order. It also contains all essential characters including all standard punctuation characters: 97 character keyset. Additionally, it is compatible with all major applications as well as it works with iPad. Furthermore, it comes with a native USB connector and an Apple iPad adapter. The product is also available in different colors depending ','','','','Operating System: Windows, iOS BigKeys LX is a keyboard designed for people with visual impairments. The device can be configured as standard QWERTY or ABC order. It also contains all essential characters including all standard punctuation characters: 97 character keyset. Additionally, it is compatible with all major applications as well as it works with iPad. Furthermore, it comes with a native USB connector and an Apple iPad adapter. The product is also available in different colors depending on the different visual disabilities. Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/)','mobility','AbleNet','','','https://at.mada.org.qa/technology/bigkeys-lx-keyboard/','https://at.mada.org.qa/technology/bigkeys-lx-keyboard/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/BigKeys-LX-Keyboard.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:16.037Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_clevy-keyboard_2420073054323','Clevy Keyboard','Clevy Keyboard','','','Operating System: Windows, iOS, Chrome Clevy Keyboard is a keyboard designed for school children and people with physical disability. The device has a sturdy plastic cover fits perfectly on top of the Clevy keyboard, which prevents users from accidentally pressing two keys at the same time. In addition, it has colorful keys, which makes it attractive to work with by children. Furthermore, it comes with a USB connector, a PS2 adapter and the Clevy function keys tool CD. In addition, the keyboard ','','','','Operating System: Windows, iOS, Chrome Clevy Keyboard is a keyboard designed for school children and people with physical disability. The device has a sturdy plastic cover fits perfectly on top of the Clevy keyboard, which prevents users from accidentally pressing two keys at the same time. In addition, it has colorful keys, which makes it attractive to work with by children. Furthermore, it comes with a USB connector, a PS2 adapter and the Clevy function keys tool CD. In addition, the keyboard is 100 times stronger than the standard keyboard. The product is also available in Clevy Keyboard Cover/Glove, which is designed for Clevy Keyboard to protect it from dirt and moisture. Additional Information: Manufacturer: Clevy (product page)','mobility','Clevy','','','https://at.mada.org.qa/technology/clevy-keyboard/','https://at.mada.org.qa/technology/clevy-keyboard/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Clevy-Keyboard.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:27.579Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_myboard-lc-keyboard_2420073058608','MyBoard-lc Keyboard','MyBoard-lc Keyboard','','','Operating System: Windows, iOS, Chrome MyBoard-lc is a keyboard designed for school children as young as three years old. The device comes with lower case letters which makes it easier on them to use the PC. Also, it has color-coding for vowels, consonants, numbers and punctuation marks and gentle finger pressure. Additionally, it has an USB with PS/2 adaptor type of connectors. As well, it comes with 6 years warranty for in-home use. Additional Information: Manufacturer: Chester Creek (https://','','','','Operating System: Windows, iOS, Chrome MyBoard-lc is a keyboard designed for school children as young as three years old. The device comes with lower case letters which makes it easier on them to use the PC. Also, it has color-coding for vowels, consonants, numbers and punctuation marks and gentle finger pressure. Additionally, it has an USB with PS/2 adaptor type of connectors. As well, it comes with 6 years warranty for in-home use. Additional Information: Manufacturer: Chester Creek (https://www.ablenetinc.com/)','mobility','Chester Creek','','','https://at.mada.org.qa/technology/myboard-lc-keyboard/','https://at.mada.org.qa/technology/myboard-lc-keyboard/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/MyBoard_keyboards.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:19:53.053Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_clicker_2420073063569','Clicker','Clicker','','','Operating System: Windows, iOS Clicker is a software designed to help struggling readers, writers and English language learners to access support tools they need at school, work or home. The program can help individuals with Dyslexia, Learning Difficulties, Speech or Language Impairments, Physical Disabilities, Low Vision, Autistic Learners, and Downs Syndrome. The program has a word processor on top and a grid with different cells that contains letters, words or phrases to help children to writ','','','','Operating System: Windows, iOS Clicker is a software designed to help struggling readers, writers and English language learners to access support tools they need at school, work or home. The program can help individuals with Dyslexia, Learning Difficulties, Speech or Language Impairments, Physical Disabilities, Low Vision, Autistic Learners, and Downs Syndrome. The program has a word processor on top and a grid with different cells that contains letters, words or phrases to help children to write sentences without typing them. Additionally, it allows the user to hear before writing and even highlights the text as it’s spoken. Furthermore, it allows users to write with pictures and animate their writings. Also, the program provides free learning resources as well as it allows the user to create his own sets of grids, links them, and have full-screen grids. As well, it supports voice recording, MP3 sounds and MPEG videos. Additional Information: Manufacturer: Crick Software (product page, documentation and support) Introduction Video:','mobility','Crick Software','','','https://at.mada.org.qa/technology/clicker/','https://at.mada.org.qa/technology/clicker/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Clicker-7.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:31.833Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_blue-2-bluetooth-switch_2420073067973','Blue 2 Bluetooth Switch','Blue 2 Bluetooth Switch','','','Operating System: Windows, iOS, Android, Chrome Provides single or dual switch access via Bluetooth connection to iOS, Apple OS X, Windows, Google Chrome, and Android devices. Includes an integrated rechargeable battery, two external switch jacks, and tactile feedback. The NEW Blue2 Bluetooth switch provides single or dual switch access to iDevices running iOS 7, Apple desktop or laptop computers running OS X Mavericks, and all switch accessible apps or software on iOS, OS X, Windows, and Androi','','','','Operating System: Windows, iOS, Android, Chrome Provides single or dual switch access via Bluetooth connection to iOS, Apple OS X, Windows, Google Chrome, and Android devices. Includes an integrated rechargeable battery, two external switch jacks, and tactile feedback. The NEW Blue2 Bluetooth switch provides single or dual switch access to iDevices running iOS 7, Apple desktop or laptop computers running OS X Mavericks, and all switch accessible apps or software on iOS, OS X, Windows, and Android! Blue2 connects to your favorite device via a Bluetooth connection that is easy and quick to set up. New features include an improved switch activation surface that takes 40-percent less pressure to activate, multiple modes of operation for compatibility to all apps, a long-lasting rechargeable battery, and a sleek, modern design. The Blue2 switch is compatible with most tablet, desktop, and laptop computers that have a Bluetooth connection. iOS 7, OS X Mavericks, or switch accessible software or apps are required. BLUE2 BLUETOOTH WIRELESS FEATURES: Rechargeable battery Requires 40% less pressure to activate than the original Blue2 Two external switch jacks Program one to four custom keystrokes for use with any app or software Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/) Blue2 Switch Introduction Video:','mobility','AbleNet','','','https://at.mada.org.qa/technology/blue-2-bluetooth-switch/','https://at.mada.org.qa/technology/blue-2-bluetooth-switch/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Blue2.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:18.046Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_jelly-beamer-twist-wireless-switch_2420073071787','Jelly Beamer Twist Wireless Switch','Jelly Beamer Twist Wireless Switch','','','Operating System: Windows, iOS Jelly Beamer Twist Wireless Switch is an assistive switch designed for people with visual, cognitive or physical requirements. The switch allows users to use their personal computer from as far away as 30 feet. As well, it allows the user to use multiple Jelly beamer without interference. The product is also available with 4 different interchangeable twist tops. Additional Information: Manufacture: AbleNet (https://www.ablenetinc.com/) Jelly Beamer Tutorials: https','','','','Operating System: Windows, iOS Jelly Beamer Twist Wireless Switch is an assistive switch designed for people with visual, cognitive or physical requirements. The switch allows users to use their personal computer from as far away as 30 feet. As well, it allows the user to use multiple Jelly beamer without interference. The product is also available with 4 different interchangeable twist tops. Additional Information: Manufacture: AbleNet (https://www.ablenetinc.com/) Jelly Beamer Tutorials: https://ablenetinc.zendesk.com/hc/en-us/sections/360011798232-Jelly-Beamer-Transmitter Jelly Beamer Switch Introduction Video:','mobility','','','','https://at.mada.org.qa/technology/jelly-beamer-twist-wireless-switch/','https://at.mada.org.qa/technology/jelly-beamer-twist-wireless-switch/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Jelly-Beamer-Twist-Wireless-Switch.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:15:09.507Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_micro-light-switch_2420073076619','Micro Light Switch','Micro Light Switch','','','Operating System: Windows, iOS Micro Light Switch is an assistive switch designed for people with visual, cognitive or physical requirements. The switch allows users to use their personal computer by pressing down on top. The product is also available with 5 colored stickers. Additional Information: Manufacture: AbleNet (https://www.ablenetinc.com/) Micro Light Switch Tutorials: https://ablenetinc.zendesk.com/hc/en-us/sections/360011889291-Mirco-Light-Switch','','','','Operating System: Windows, iOS Micro Light Switch is an assistive switch designed for people with visual, cognitive or physical requirements. The switch allows users to use their personal computer by pressing down on top. The product is also available with 5 colored stickers. Additional Information: Manufacture: AbleNet (https://www.ablenetinc.com/) Micro Light Switch Tutorials: https://ablenetinc.zendesk.com/hc/en-us/sections/360011889291-Mirco-Light-Switch','mobility','','','','https://at.mada.org.qa/technology/micro-light-switch/','https://at.mada.org.qa/technology/micro-light-switch/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Micor-light.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:15:25.739Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_crick-usb-interface_2420073081181','Crick USB Interface','Crick USB Interface','','','Operating System: Other This reliable USB switch interface will work with almost all switch accessible software. This box will instantly work with Clicker, Cloze Pro and All My Words 2 with no set up required. Works on both Mac and PC Operates most switch accessible software Incredibly easy to set up For other switch accessible software, USB Keys is included, a small software application which converts switch presses from the USB switch box into key presses or mouse clicks. It is very easy to us','','','','Operating System: Other This reliable USB switch interface will work with almost all switch accessible software. This box will instantly work with Clicker, Cloze Pro and All My Words 2 with no set up required. Works on both Mac and PC Operates most switch accessible software Incredibly easy to set up For other switch accessible software, USB Keys is included, a small software application which converts switch presses from the USB switch box into key presses or mouse clicks. It is very easy to use and can be set up to start automatically when the computer is switched on. Now there is a database making it even simpler. USBKeys2 can update itself from www.SwitchIndex.com to keep its internal database up to date. Programs that are listed in the database are detected automatically by USBKeys2. If your software is listed, USBKeys2 will know exactly how to behave. Additional Information: Manufacturer: Crick Software (https://www.cricksoft.com)','mobility','Crick Software','','','https://at.mada.org.qa/technology/crick-usb-interface/','https://at.mada.org.qa/technology/crick-usb-interface/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Crick-USB-Interface.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:41.778Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_jelly-bean-twist_2420073086980','Jelly Bean twist','Jelly Bean twist','','','Operating System: Other Long considered the standard in the industry, our famous Jelly Bean switch features a 2.5-in/6.4-cm activation surface and is recommended for users who are able to access a smaller target area. Switch tops can be removed and replaced with the color of your choice: Red, Blue, Yellow, or Green. Also includes a clear snap cap for symbol use. It’s all up to your own style, tastes, or specific vision needs. JELLY BEAN SWITCH TECHNICAL SPECIFICATIONS: Switch Type: Mechanical Co','','','','Operating System: Other Long considered the standard in the industry, our famous Jelly Bean switch features a 2.5-in/6.4-cm activation surface and is recommended for users who are able to access a smaller target area. Switch tops can be removed and replaced with the color of your choice: Red, Blue, Yellow, or Green. Also includes a clear snap cap for symbol use. It’s all up to your own style, tastes, or specific vision needs. JELLY BEAN SWITCH TECHNICAL SPECIFICATIONS: Switch Type: Mechanical Connection Type: Wired Activation Type: Pressure Activation Surface: 2.5-in/6.4-cm diameter Activating Force: 2.5-oz/71-g Travel Before Activation: 0.025-in/0.0635-cm Feedback: Auditory click, Tactile Plug Size: 1/8-in/3.5-mm mono Mounting Plate: Universal Mounting Plate Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/) Jelly Bean Switch Introduction Video:','mobility','AbleNet','','','https://at.mada.org.qa/technology/jelly-bean-twist/','https://at.mada.org.qa/technology/jelly-bean-twist/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Jelly-Bean-twist.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:19:24.347Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_pebble-smart-watch_2420073090570','Pebble Smart Watch','Pebble Smart Watch','','','Operating System: Other Allow your smart device’s to be turned into High tech alerting devices with Sound Alert. By converting any type of sound from your environment, Sound Alert can notify you by the power of visuals and vibrations to ensure your safety, security, and comfort. Using Sound Alert You Will Be Able to Choose How You Would Like To Be Notified from Vibration, Flashing Light to Smart Watch Notifications. Connect your Pebble Smart watch to the Sound Alert App through Bluetooth to rece','','','','Operating System: Other Allow your smart device’s to be turned into High tech alerting devices with Sound Alert. By converting any type of sound from your environment, Sound Alert can notify you by the power of visuals and vibrations to ensure your safety, security, and comfort. Using Sound Alert You Will Be Able to Choose How You Would Like To Be Notified from Vibration, Flashing Light to Smart Watch Notifications. Connect your Pebble Smart watch to the Sound Alert App through Bluetooth to receive vibrations and on screen notifications of events. The Sound Alert App is compatible with many other technologies from expanding the detection range to receiving different forms of notifications. Additional Information: Manufacturer: rePebble (official site)','mobility','rePebble','','','https://at.mada.org.qa/technology/pebble-smart-watch/','https://at.mada.org.qa/technology/pebble-smart-watch/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/pebble.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:20:06.750Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_bigtrack-2_2420073095851','BIGtrack 2','BIGtrack 2','','','Operating System: Other The BIGtrack Trackball Switch Adapted has a 3 inch trackball which makes it the largest trackball available. The large ball requires less fine motor control than a standard trackball and it is ruggedly built. It has a left and a right mouse click button located behind the trackball to avoid unwanted mouse clicks. The BIGtrack trackball also allows for 2nd Mouse Connection both the BIGtrack and a second mouse can be connected allowing simultaneous participation. The bright','','','','Operating System: Other The BIGtrack Trackball Switch Adapted has a 3 inch trackball which makes it the largest trackball available. The large ball requires less fine motor control than a standard trackball and it is ruggedly built. It has a left and a right mouse click button located behind the trackball to avoid unwanted mouse clicks. The BIGtrack trackball also allows for 2nd Mouse Connection both the BIGtrack and a second mouse can be connected allowing simultaneous participation. The bright large 3″ trackball helps to make mouse movements easy and accurate. While the oversized buttons make mouse clicks simple for those with poor motor control. For even more access this switch adapted version comes with two standard 1/8″ plugs for two switches. Its left and right mouse clicks have been adapted so that you can use a switch for activation. This large trackball is also perfect for kids of all ages, especially children in preschool. The large trackball is easy on little hands and is simple to use. (Switches sold separately) The BIGtrack Switch Adapted is easy to install and works on any Windows or Macintosh computer that has a USB or PS/2 port. Just plug and play. Additional Information: Manufacturer: AbleNet (product page)','mobility','AbleNet','','','https://at.mada.org.qa/technology/bigtrack-2/','https://at.mada.org.qa/technology/bigtrack-2/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Ablenet-BigTrack.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:08.273Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_track-bar_242007309957','Trackbar Emotion','Trackbar Emotion','','','Operating System: Other The Trackbar Emotion was mindfully created for both preventative as well as rehabilitative use for people concerned about upper limb disorders (ULD’s). It was built on the principle of centering the pointing device between the user and keyboard (defined between keys G and H). This positioning keeps the user’s hands and arms in a more natural position during keyboard and mouse work. Employing this principle, this product reduces or eliminates sideways or reaching arm movem','','','','Operating System: Other The Trackbar Emotion was mindfully created for both preventative as well as rehabilitative use for people concerned about upper limb disorders (ULD’s). It was built on the principle of centering the pointing device between the user and keyboard (defined between keys G and H). This positioning keeps the user’s hands and arms in a more natural position during keyboard and mouse work. Employing this principle, this product reduces or eliminates sideways or reaching arm movements that can increase the risk of developing ULD’s. Additional Information: Manufacturer: Keyboard Company (https://www.keyboardco.com)','mobility','Keyboard Company','','','https://at.mada.org.qa/technology/track-bar/','https://at.mada.org.qa/technology/track-bar/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/trackbar_emotion.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:21:12.167Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_chester-mouse_2420073104509','Chester Mouse','Chester Mouse','','','Operating System: Other ChesterMouse is a single-button mouse with no scroll wheel made from rugged plastic. ChesterMouse is small enough to fit into small hands. A small computer mouse with no scroll wheel, about half the size of a standard mouse with one large green button that serves as the left-click. Helps young users or anyone just learning mouse skills understand what the left button does on a mouse without the fear of opening menus, etc. Additional Information: Manufacturer: AbleNet (htt','','','','Operating System: Other ChesterMouse is a single-button mouse with no scroll wheel made from rugged plastic. ChesterMouse is small enough to fit into small hands. A small computer mouse with no scroll wheel, about half the size of a standard mouse with one large green button that serves as the left-click. Helps young users or anyone just learning mouse skills understand what the left button does on a mouse without the fear of opening menus, etc. Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/)','mobility','AbleNet','','','https://at.mada.org.qa/technology/chester-mouse/','https://at.mada.org.qa/technology/chester-mouse/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Chester.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:25.825Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_bjoy-ring_2420073108657','BJOY Ring','BJOY Ring','','','Operating System: Other Turn your wheelchair’s joystick into your mouse BJOY Ring is a USB device that allows using the joystick of your wheelchair as a mouse to control the computer. With no additional adjustment, you can control and access all your favourite applications. The mouse clicks can be done with the external switches that you prefer. Use your mouse in an accurate and comfortable way from your wheelchair’s joystick. Get to your favourite applications in an easy and simple way. Use you','','','','Operating System: Other Turn your wheelchair’s joystick into your mouse BJOY Ring is a USB device that allows using the joystick of your wheelchair as a mouse to control the computer. With no additional adjustment, you can control and access all your favourite applications. The mouse clicks can be done with the external switches that you prefer. Use your mouse in an accurate and comfortable way from your wheelchair’s joystick. Get to your favourite applications in an easy and simple way. Use your favourite switches to make the clicks Use the external switches that suits you the most to make the clicks. Use the BJOY software in order to modify the mouse operation features like the pointer speed, orientation, buttons functions and many others. All settings are stored in the device. There’s no need to configure the mouse if used with different devices. Additional Information: Manufacturer: Qinera (product page) Video:','mobility','Qinera','','','https://at.mada.org.qa/technology/bjoy-ring/','https://at.mada.org.qa/technology/bjoy-ring/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Bjoy-Series.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:18:10.219Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_ablenet-hook-plus_2420073112348','Ablenet Hook Plus','Ablenet Hook Plus','','','Operating System: Other Hook+ is an Apple MFi approved switch interface that provides a reliable wired connection to the iPad and iPhone via the Lightning connector. To get started, simply connect one to four switches to Hook+, turn Switch Control on, and connect Hook+ to your iPad or iPhone. Hook+ utilizes the Apple auto switch configurator and the first time Hook+ is used with an iPad or iPhone it will automatically configure the iPad or iPhone to use single switch auto scanning or dual switch','','','','Operating System: Other Hook+ is an Apple MFi approved switch interface that provides a reliable wired connection to the iPad and iPhone via the Lightning connector. To get started, simply connect one to four switches to Hook+, turn Switch Control on, and connect Hook+ to your iPad or iPhone. Hook+ utilizes the Apple auto switch configurator and the first time Hook+ is used with an iPad or iPhone it will automatically configure the iPad or iPhone to use single switch auto scanning or dual switch step scanning based on how many switches are connected to Hook+. Once initially configured, switches can be manually re-configured to meet the needs of the user. The Apple auto switch configurator is only available on Apple MFi approved switch interfaces. Once Hook+ is connected and Switch Control is configured, you can do almost anything on an iPad or iPhone with a switch. Read an eBook, write an email, browse the internet, play games, control your home, and much more! Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/) Hook+ Switch Interface how to setup guide: Video:','mobility','AbleNet','','','https://at.mada.org.qa/technology/ablenet-hook-plus/','https://at.mada.org.qa/technology/ablenet-hook-plus/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Hook-interface.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:17:56.475Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_mouse-skills_2420073117527','Mouse Skills','Mouse Skills','','','Operating System: Windows Learners are taken stage by stage through the many applications of the mouse. Move the mouse over an object, drag and drop, drag along a path and the use of drop-down menus are all represented. Various clicking activities can be found such as clicking anywhere, click timing and double clicking. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk/)','','','','Operating System: Windows Learners are taken stage by stage through the many applications of the mouse. Move the mouse over an object, drag and drop, drag along a path and the use of drop-down menus are all represented. Various clicking activities can be found such as clicking anywhere, click timing and double clicking. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk/)','daily_living','Inclusive Technology','','','https://at.mada.org.qa/technology/mouse-skills/','https://at.mada.org.qa/technology/mouse-skills/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/mouse-skills.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:16:08.136Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_tobii-pceye-mini_2420073121678','Tobii PCEye Mini','Tobii PCEye Mini','','','Operating System: Windows The PCEye Mini includes a PCEye Mini eye tracker and the new Windows Control software. Windows Control enables full computer access on a Windows PC via eye gaze or eye gaze combined with switch input, replacing the standard keyboard and mouse. Additional Information: Manufacturer: Tobii Dynabox Tobii PCEye Mini – Windows Control Training and Tutorials: https://www.tobiidynavox.com/support-training/windows-control-2/','','','','Operating System: Windows The PCEye Mini includes a PCEye Mini eye tracker and the new Windows Control software. Windows Control enables full computer access on a Windows PC via eye gaze or eye gaze combined with switch input, replacing the standard keyboard and mouse. Additional Information: Manufacturer: Tobii Dynabox Tobii PCEye Mini – Windows Control Training and Tutorials: https://www.tobiidynavox.com/support-training/windows-control-2/','daily_living','Tobii Dynavox','','','https://at.mada.org.qa/technology/tobii-pceye-mini/','https://at.mada.org.qa/technology/tobii-pceye-mini/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/tobiidynavox-pceye-mini.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:16:44.441Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_hitch-2-0_2420073126946','Hitch 2.0','Hitch 2.0','','','Operating System: Other Hitch 2 is a plug-and-play USB computer switch interface with inputs for up to five switches or one joystick with a 9-pin D plug. When used with switch accessible software, users are able to control their computer, actively learn, and have fun. Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/)','','','','Operating System: Other Hitch 2 is a plug-and-play USB computer switch interface with inputs for up to five switches or one joystick with a 9-pin D plug. When used with switch accessible software, users are able to control their computer, actively learn, and have fun. Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/)','daily_living','AbleNet','','','https://at.mada.org.qa/technology/hitch-2-0/','https://at.mada.org.qa/technology/hitch-2-0/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Hitch.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:15:42.607Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_tecla-e_2420073130697','Tecla-e','Tecla-e','','','Operating System: Other Tecla-e is an assistive device that gives people with upper-body mobility impairments the ability to fully access smart devices and technology. Users can control multiple devices to send and receive emails and text messages, browse the web, watch videos, launch and use apps, read books, turn on their TV, control their thermostat, turn the lights on or off, make (or hang up) phone calls, enter commands using Siri, and more – all with ONE tecla-e. Additional Information: Ma','','','','Operating System: Other Tecla-e is an assistive device that gives people with upper-body mobility impairments the ability to fully access smart devices and technology. Users can control multiple devices to send and receive emails and text messages, browse the web, watch videos, launch and use apps, read books, turn on their TV, control their thermostat, turn the lights on or off, make (or hang up) phone calls, enter commands using Siri, and more – all with ONE tecla-e. Additional Information: Manufacturer: Tecla (https://gettecla.com/ Tecla Introduction video:','daily_living','Tecla','','','https://at.mada.org.qa/technology/tecla-e/','https://at.mada.org.qa/technology/tecla-e/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Tecla.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:16:38.739Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_wobble-switch_2420073135330','Wobble Switch','Wobble Switch','','','Operating System: Other The wobble switch is good for the users who lack the upper extremity control necessary for other types of switches, wobbles can be activated by any gross motor movement that swipes its lever. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk )','','','','Operating System: Other The wobble switch is good for the users who lack the upper extremity control necessary for other types of switches, wobbles can be activated by any gross motor movement that swipes its lever. Additional Information: Manufacturer: Inclusive Technology (http://www.inclusive.co.uk )','daily_living','Inclusive Technology','','','https://at.mada.org.qa/technology/wobble-switch/','https://at.mada.org.qa/technology/wobble-switch/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/wobble.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:16:52.370Z',NULL,NULL,NULL);
