INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_candy-corn-proximity-switch_2420073171588','Candy Corn Proximity Switch','Candy Corn Proximity Switch','','','Operating System: Other Candy Corn proximity sensor switch is highly sensitive and does not require a physical touch from the user to activate. A user simply wave a hand or move a body part within 1inche from the switch and it would activate. Big Candy Corn has 3.5 inches wide of activation area. Little Candy corn is a compact size, which has 1.9 inches of activation area. Additional Information: Manufacturer: AbleNet (product page, support hub) Candy Corn proximity switch introduction video:','','','','Operating System: Other Candy Corn proximity sensor switch is highly sensitive and does not require a physical touch from the user to activate. A user simply wave a hand or move a body part within 1inche from the switch and it would activate. Big Candy Corn has 3.5 inches wide of activation area. Little Candy corn is a compact size, which has 1.9 inches of activation area. Additional Information: Manufacturer: AbleNet (product page, support hub) Candy Corn proximity switch introduction video:','daily_living','AbleNet','','','https://at.mada.org.qa/technology/candy-corn-proximity-switch/','https://at.mada.org.qa/technology/candy-corn-proximity-switch/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Cancy-Corn.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:15:18.976Z',NULL,NULL,NULL);
