INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_yumqua-mouse_2420073180611','Yumqua Mouse','Yumqua Mouse','','','Operating System: Windows, iOS, Android, Chrome Yumqua mouse is off-table, without limitation by operation space and avoiding harm to wrist and muscle. The two dimensions and buttons are simply controlled by fingers. Looking for something a bit different in a mouse? It looks like a lame Sci-Fi gun in a low budget movie, but who knows, it might just help your wrist. Additional Information: Manufacturer: Yumqua (https://www.yumqua.com/collections/trackball-mouse)','','','','Operating System: Windows, iOS, Android, Chrome Yumqua mouse is off-table, without limitation by operation space and avoiding harm to wrist and muscle. The two dimensions and buttons are simply controlled by fingers. Looking for something a bit different in a mouse? It looks like a lame Sci-Fi gun in a low budget movie, but who knows, it might just help your wrist. Additional Information: Manufacturer: Yumqua (https://www.yumqua.com/collections/trackball-mouse)','daily_living','Yumqua','','','https://at.mada.org.qa/technology/yumqua-mouse/','https://at.mada.org.qa/technology/yumqua-mouse/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Yumqua-mouse.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:16:54.236Z',NULL,NULL,NULL);
