INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_pointit-joysticks_2420073189310','PointIt! Joystick','PointIt! Joystick','','','Operating System: Windows, iOS, Chrome Point-It! Joystick is an access solution for people who find it difficult to use standard computer mice. You can use them to move the pointer around the screen, make left and right clicks and control applications. Use a Point-It! to surf the web, catch up on emails, play games, watch YouTube, and much more. Additional Information: Manufacturer: HouseMate (https://housemate.ie/point-it/)','','','','Operating System: Windows, iOS, Chrome Point-It! Joystick is an access solution for people who find it difficult to use standard computer mice. You can use them to move the pointer around the screen, make left and right clicks and control applications. Use a Point-It! to surf the web, catch up on emails, play games, watch YouTube, and much more. Additional Information: Manufacturer: HouseMate (https://housemate.ie/point-it/)','daily_living','Housemate','','','https://at.mada.org.qa/technology/pointit-joysticks/','https://at.mada.org.qa/technology/pointit-joysticks/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/PointIt.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T09:44:17.996Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_optima-joystick_2420073195290','Optima Joystick','Optima Joystick','','','Operating System: Windows, iOS, Chrome Optima Joystick and Trackball are compact, desktop mouse alternatives that do not require fine motor skills and are suitable for a wide spectrum of computer users. They are specifically designed to respond to the lightest touch to give accurate cursor navigation and precise targeting of objects on the computer screen while occupying the minimum amount of desk space. Additional Information: Manufacturer: Pretorian Technologies (https://www.pretorianuk.com/)','','','','Operating System: Windows, iOS, Chrome Optima Joystick and Trackball are compact, desktop mouse alternatives that do not require fine motor skills and are suitable for a wide spectrum of computer users. They are specifically designed to respond to the lightest touch to give accurate cursor navigation and precise targeting of objects on the computer screen while occupying the minimum amount of desk space. Additional Information: Manufacturer: Pretorian Technologies (https://www.pretorianuk.com/)','daily_living','Pretorian Technologies','','','https://at.mada.org.qa/technology/optima-joystick/','https://at.mada.org.qa/technology/optima-joystick/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/optima-joystick.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:16:12.100Z',NULL,NULL,NULL);
