INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_handshoe-mouse-2_2420073208766','Handshoe Mouse','Handshoe Mouse','','','Operating System: Windows, iOS, Chrome The Handshoe mouse provides the optimal support for the human hand the patented shape of the HandShoe Mouse has been defined as follows: Support is provided for fingers and thumb. The finger support is a curved surface which follows the finger arch of the relaxed finger (Extensor and Flexor muscles in equilibrium). In view of the anatomical shape of the human hand the thumb supporting element lies at a pre-defined lower level relative to the finger supporti','','','','Operating System: Windows, iOS, Chrome The Handshoe mouse provides the optimal support for the human hand the patented shape of the HandShoe Mouse has been defined as follows: Support is provided for fingers and thumb. The finger support is a curved surface which follows the finger arch of the relaxed finger (Extensor and Flexor muscles in equilibrium). In view of the anatomical shape of the human hand the thumb supporting element lies at a pre-defined lower level relative to the finger supporting part. Both supports, for thumb and fingers, join to provide the hand palm support. Additional Information: Manufacturer: Hippus NV (product page) Handshoe Mouse Introduction Video:','daily_living','Hippus NV','','','https://at.mada.org.qa/technology/handshoe-mouse-2/','https://at.mada.org.qa/technology/handshoe-mouse-2/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/HandShoeMouse.gif','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:15:40.553Z',NULL,NULL,NULL);
