INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_bigkeys-lx-keyboard_2420073286434','BigKeys LX Keyboard','BigKeys LX Keyboard','','','Operating System: Windows, iOS BigKeys LX is a keyboard designed for people with visual impairments. The device can be configured as standard QWERTY or ABC order. It also contains all essential characters including all standard punctuation characters: 97 character keyset. Additionally, it is compatible with all major applications as well as it works with iPad. Furthermore, it comes with a native USB connector and an Apple iPad adapter. The product is also available in different colors depending ','','','','Operating System: Windows, iOS BigKeys LX is a keyboard designed for people with visual impairments. The device can be configured as standard QWERTY or ABC order. It also contains all essential characters including all standard punctuation characters: 97 character keyset. Additionally, it is compatible with all major applications as well as it works with iPad. Furthermore, it comes with a native USB connector and an Apple iPad adapter. The product is also available in different colors depending on the different visual disabilities. Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/)','daily_living','AbleNet','','','https://at.mada.org.qa/technology/bigkeys-lx-keyboard/','https://at.mada.org.qa/technology/bigkeys-lx-keyboard/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/BigKeys-LX-Keyboard.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:15:14.781Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_clevy-keyboard_2420073291943','Clevy Keyboard','Clevy Keyboard','','','Operating System: Windows, iOS, Chrome Clevy Keyboard is a keyboard designed for school children and people with physical disability. The device has a sturdy plastic cover fits perfectly on top of the Clevy keyboard, which prevents users from accidentally pressing two keys at the same time. In addition, it has colorful keys, which makes it attractive to work with by children. Furthermore, it comes with a USB connector, a PS2 adapter and the Clevy function keys tool CD. In addition, the keyboard ','','','','Operating System: Windows, iOS, Chrome Clevy Keyboard is a keyboard designed for school children and people with physical disability. The device has a sturdy plastic cover fits perfectly on top of the Clevy keyboard, which prevents users from accidentally pressing two keys at the same time. In addition, it has colorful keys, which makes it attractive to work with by children. Furthermore, it comes with a USB connector, a PS2 adapter and the Clevy function keys tool CD. In addition, the keyboard is 100 times stronger than the standard keyboard. The product is also available in Clevy Keyboard Cover/Glove, which is designed for Clevy Keyboard to protect it from dirt and moisture. Additional Information: Manufacturer: Clevy (product page)','daily_living','Clevy','','','https://at.mada.org.qa/technology/clevy-keyboard/','https://at.mada.org.qa/technology/clevy-keyboard/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Clevy-Keyboard.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:15:22.797Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_myboard-lc-keyboard_2420073295674','MyBoard-lc Keyboard','MyBoard-lc Keyboard','','','Operating System: Windows, iOS, Chrome MyBoard-lc is a keyboard designed for school children as young as three years old. The device comes with lower case letters which makes it easier on them to use the PC. Also, it has color-coding for vowels, consonants, numbers and punctuation marks and gentle finger pressure. Additionally, it has an USB with PS/2 adaptor type of connectors. As well, it comes with 6 years warranty for in-home use. Additional Information: Manufacturer: Chester Creek (https://','','','','Operating System: Windows, iOS, Chrome MyBoard-lc is a keyboard designed for school children as young as three years old. The device comes with lower case letters which makes it easier on them to use the PC. Also, it has color-coding for vowels, consonants, numbers and punctuation marks and gentle finger pressure. Additionally, it has an USB with PS/2 adaptor type of connectors. As well, it comes with 6 years warranty for in-home use. Additional Information: Manufacturer: Chester Creek (https://www.ablenetinc.com/)','daily_living','Chester Creek','','','https://at.mada.org.qa/technology/myboard-lc-keyboard/','https://at.mada.org.qa/technology/myboard-lc-keyboard/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/MyBoard_keyboards.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:16:10.151Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_blue-2-bluetooth-switch_2420073300774','Blue 2 Bluetooth Switch','Blue 2 Bluetooth Switch','','','Operating System: Windows, iOS, Android, Chrome Provides single or dual switch access via Bluetooth connection to iOS, Apple OS X, Windows, Google Chrome, and Android devices. Includes an integrated rechargeable battery, two external switch jacks, and tactile feedback. The NEW Blue2 Bluetooth switch provides single or dual switch access to iDevices running iOS 7, Apple desktop or laptop computers running OS X Mavericks, and all switch accessible apps or software on iOS, OS X, Windows, and Androi','','','','Operating System: Windows, iOS, Android, Chrome Provides single or dual switch access via Bluetooth connection to iOS, Apple OS X, Windows, Google Chrome, and Android devices. Includes an integrated rechargeable battery, two external switch jacks, and tactile feedback. The NEW Blue2 Bluetooth switch provides single or dual switch access to iDevices running iOS 7, Apple desktop or laptop computers running OS X Mavericks, and all switch accessible apps or software on iOS, OS X, Windows, and Android! Blue2 connects to your favorite device via a Bluetooth connection that is easy and quick to set up. New features include an improved switch activation surface that takes 40-percent less pressure to activate, multiple modes of operation for compatibility to all apps, a long-lasting rechargeable battery, and a sleek, modern design. The Blue2 switch is compatible with most tablet, desktop, and laptop computers that have a Bluetooth connection. iOS 7, OS X Mavericks, or switch accessible software or apps are required. BLUE2 BLUETOOTH WIRELESS FEATURES: Rechargeable battery Requires 40% less pressure to activate than the original Blue2 Two external switch jacks Program one to four custom keystrokes for use with any app or software Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/) Blue2 Switch Introduction Video:','daily_living','AbleNet','','','https://at.mada.org.qa/technology/blue-2-bluetooth-switch/','https://at.mada.org.qa/technology/blue-2-bluetooth-switch/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Blue2.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:15:17.101Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_jelly-beamer-twist-wireless-switch_2420073304648','Jelly Beamer Twist Wireless Switch','Jelly Beamer Twist Wireless Switch','','','Operating System: Windows, iOS Jelly Beamer Twist Wireless Switch is an assistive switch designed for people with visual, cognitive or physical requirements. The switch allows users to use their personal computer from as far away as 30 feet. As well, it allows the user to use multiple Jelly beamer without interference. The product is also available with 4 different interchangeable twist tops. Additional Information: Manufacture: AbleNet (https://www.ablenetinc.com/) Jelly Beamer Tutorials: https','','','','Operating System: Windows, iOS Jelly Beamer Twist Wireless Switch is an assistive switch designed for people with visual, cognitive or physical requirements. The switch allows users to use their personal computer from as far away as 30 feet. As well, it allows the user to use multiple Jelly beamer without interference. The product is also available with 4 different interchangeable twist tops. Additional Information: Manufacture: AbleNet (https://www.ablenetinc.com/) Jelly Beamer Tutorials: https://ablenetinc.zendesk.com/hc/en-us/sections/360011798232-Jelly-Beamer-Transmitter Jelly Beamer Switch Introduction Video:','daily_living','','','','https://at.mada.org.qa/technology/jelly-beamer-twist-wireless-switch/','https://at.mada.org.qa/technology/jelly-beamer-twist-wireless-switch/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Jelly-Beamer-Twist-Wireless-Switch.png','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:12:25.907Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_micro-light-switch_2420073309685','Micro Light Switch','Micro Light Switch','','','Operating System: Windows, iOS Micro Light Switch is an assistive switch designed for people with visual, cognitive or physical requirements. The switch allows users to use their personal computer by pressing down on top. The product is also available with 5 colored stickers. Additional Information: Manufacture: AbleNet (https://www.ablenetinc.com/) Micro Light Switch Tutorials: https://ablenetinc.zendesk.com/hc/en-us/sections/360011889291-Mirco-Light-Switch','','','','Operating System: Windows, iOS Micro Light Switch is an assistive switch designed for people with visual, cognitive or physical requirements. The switch allows users to use their personal computer by pressing down on top. The product is also available with 5 colored stickers. Additional Information: Manufacture: AbleNet (https://www.ablenetinc.com/) Micro Light Switch Tutorials: https://ablenetinc.zendesk.com/hc/en-us/sections/360011889291-Mirco-Light-Switch','daily_living','','','','https://at.mada.org.qa/technology/micro-light-switch/','https://at.mada.org.qa/technology/micro-light-switch/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Micor-light.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-22T07:12:37.919Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_crick-usb-interface_2420073313770','Crick USB Interface','Crick USB Interface','','','Operating System: Other This reliable USB switch interface will work with almost all switch accessible software. This box will instantly work with Clicker, Cloze Pro and All My Words 2 with no set up required. Works on both Mac and PC Operates most switch accessible software Incredibly easy to set up For other switch accessible software, USB Keys is included, a small software application which converts switch presses from the USB switch box into key presses or mouse clicks. It is very easy to us','','','','Operating System: Other This reliable USB switch interface will work with almost all switch accessible software. This box will instantly work with Clicker, Cloze Pro and All My Words 2 with no set up required. Works on both Mac and PC Operates most switch accessible software Incredibly easy to set up For other switch accessible software, USB Keys is included, a small software application which converts switch presses from the USB switch box into key presses or mouse clicks. It is very easy to use and can be set up to start automatically when the computer is switched on. Now there is a database making it even simpler. USBKeys2 can update itself from www.SwitchIndex.com to keep its internal database up to date. Programs that are listed in the database are detected automatically by USBKeys2. If your software is listed, USBKeys2 will know exactly how to behave. Additional Information: Manufacturer: Crick Software (https://www.cricksoft.com)','daily_living','Crick Software','','','https://at.mada.org.qa/technology/crick-usb-interface/','https://at.mada.org.qa/technology/crick-usb-interface/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Crick-USB-Interface.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:15:26.694Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_jelly-bean-twist_2420073318887','Jelly Bean twist','Jelly Bean twist','','','Operating System: Other Long considered the standard in the industry, our famous Jelly Bean switch features a 2.5-in/6.4-cm activation surface and is recommended for users who are able to access a smaller target area. Switch tops can be removed and replaced with the color of your choice: Red, Blue, Yellow, or Green. Also includes a clear snap cap for symbol use. It’s all up to your own style, tastes, or specific vision needs. JELLY BEAN SWITCH TECHNICAL SPECIFICATIONS: Switch Type: Mechanical Co','','','','Operating System: Other Long considered the standard in the industry, our famous Jelly Bean switch features a 2.5-in/6.4-cm activation surface and is recommended for users who are able to access a smaller target area. Switch tops can be removed and replaced with the color of your choice: Red, Blue, Yellow, or Green. Also includes a clear snap cap for symbol use. It’s all up to your own style, tastes, or specific vision needs. JELLY BEAN SWITCH TECHNICAL SPECIFICATIONS: Switch Type: Mechanical Connection Type: Wired Activation Type: Pressure Activation Surface: 2.5-in/6.4-cm diameter Activating Force: 2.5-oz/71-g Travel Before Activation: 0.025-in/0.0635-cm Feedback: Auditory click, Tactile Plug Size: 1/8-in/3.5-mm mono Mounting Plate: Universal Mounting Plate Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/) Jelly Bean Switch Introduction Video:','daily_living','AbleNet','','','https://at.mada.org.qa/technology/jelly-bean-twist/','https://at.mada.org.qa/technology/jelly-bean-twist/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Jelly-Bean-twist.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:15:50.829Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_ablenet-hook-plus_242007332258','Ablenet Hook Plus','Ablenet Hook Plus','','','Operating System: Other Hook+ is an Apple MFi approved switch interface that provides a reliable wired connection to the iPad and iPhone via the Lightning connector. To get started, simply connect one to four switches to Hook+, turn Switch Control on, and connect Hook+ to your iPad or iPhone. Hook+ utilizes the Apple auto switch configurator and the first time Hook+ is used with an iPad or iPhone it will automatically configure the iPad or iPhone to use single switch auto scanning or dual switch','','','','Operating System: Other Hook+ is an Apple MFi approved switch interface that provides a reliable wired connection to the iPad and iPhone via the Lightning connector. To get started, simply connect one to four switches to Hook+, turn Switch Control on, and connect Hook+ to your iPad or iPhone. Hook+ utilizes the Apple auto switch configurator and the first time Hook+ is used with an iPad or iPhone it will automatically configure the iPad or iPhone to use single switch auto scanning or dual switch step scanning based on how many switches are connected to Hook+. Once initially configured, switches can be manually re-configured to meet the needs of the user. The Apple auto switch configurator is only available on Apple MFi approved switch interfaces. Once Hook+ is connected and Switch Control is configured, you can do almost anything on an iPad or iPhone with a switch. Read an eBook, write an email, browse the internet, play games, control your home, and much more! Additional Information: Manufacturer: AbleNet (https://www.ablenetinc.com/) Hook+ Switch Interface how to setup guide: Video:','daily_living','AbleNet','','','https://at.mada.org.qa/technology/ablenet-hook-plus/','https://at.mada.org.qa/technology/ablenet-hook-plus/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Hook-interface.jpg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:15:05.365Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_wewalk-smart-cane_242007332716','WeWALK Smart Cane','WeWALK Smart Cane','','','Operating System: iOS, Android The WeWALK is a smart cane for the visually impaired, enhanced with an ultrasound sensor that detects suspended obstacles a conventional white cane can’t and the ability to provide directions through the companion mobile app. Additional Information: Manufacturer: WeWALK (https://wewalk.io/en/) Video:','','','','Operating System: iOS, Android The WeWALK is a smart cane for the visually impaired, enhanced with an ultrasound sensor that detects suspended obstacles a conventional white cane can’t and the ability to provide directions through the companion mobile app. Additional Information: Manufacturer: WeWALK (https://wewalk.io/en/) Video:','daily_living','WeWALK','','','https://at.mada.org.qa/technology/wewalk-smart-cane/','https://at.mada.org.qa/technology/wewalk-smart-cane/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Wewalk-smart-cane.jpeg','[]','','','published',0,0,'vi',NULL,'2026-10-19T14:27:52.108Z','2026-10-23T08:16:50.498Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_td-pilot_voiceandspeech_1792656917563','TD Pilot','TD Pilot','','','Operating System: iOS','','','','TD Pilot is an eye-controlled communication device for iPad. Designed to empower people with conditions such as ALS/MND, spinal cord injury or cerebral palsy to communicate and use their favourite apps, this iPad OS-based speech generating device features the world’s leading eye tracker.

Manufacturer: Tobii Dynavox (https://www.tobiidynavox.com/pages/tdpilot)

','voice-and-speech','Tobii Dynavox','','','https://at.mada.org.qa/technology/td-pilot/','https://at.mada.org.qa/technology/td-pilot/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/06/TD-pilot.png','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.563Z','2026-10-23T09:42:41.737Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_tawasol-symbols_voiceandspeech_1792656917565','Tawasol Symbols','Tawasol Symbols','','','Operating System: Windows, iOS','','','','TAWASOL Symbols dictionary is a bilingual Arabic / English symbol dictionary of frequently used words in spoken and written communication (Tawasol in Arabic) to support Alternative and Augmentative Communication (AAC) users, individuals who may have low levels of literacy, learning disabilities or specific learning difficulties and individuals who have social interaction difficulties.

Download Tawasol symbols: https://tawasol.mada.org.qa/

','voice-and-speech','','','','https://at.mada.org.qa/technology/tawasol-symbols/','https://at.mada.org.qa/technology/tawasol-symbols/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Tawasol-symbols.png','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-22T08:15:17.565Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_proloquo2go_cognition_1792656917565','Proloquo2Go','Proloquo2Go','','','Operating System: iOS','','','','Proloquo2Go is a symbol-based app helps users learn how to express themselves. Proloquo2Go puts the user’s development first, with innovative features based on clinical knowledge and user research.

It’s also one of the few AAC apps designed to support all users, from beginning to advanced. Completely customizable and designed for a range of fine-motor and visual skills, the app’s versatility makes it useful for non-verbal people with autism, Down syndrome, cerebral palsy, and a range of other diagnoses or speech impediments like apraxia and dysarthria.

Manufacturer: Assistiveware (https://www.assistiveware.com)

','cognition','Assistiveware','','','https://at.mada.org.qa/technology/proloquo2go/','https://at.mada.org.qa/technology/proloquo2go/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Proloquo2Go.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T08:14:20.890Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_coughdrop-aac_mobility_1792656917565','CoughDrop AAC','CoughDrop AAC','','','Operating System: Windows, iOS, Android, Chrome','','','','CoughDrop is an open, flexible augmentative and alternative communication (AAC) app for people with complex communication needs, that can grow and expand with the user, make it easier to provide meaningful supports, and provide useful insights, all in a clean, cross-platform package.

CoughDrop is built to run on all major devices, including desktop computers and laptops, iPads and iPhones, Android tablets and phones, Kindles, Chromebooks, and Windows devices. The interface stays consistent across devices so that users can swap out devices with minimal interruption or confusion. CoughDrop is built on modern web standards and offers an open API and integration points to try to work with as many existing systems as possible.

CoughDrop has vocabulary sets for many different levels, with built-in supports and vocabulary progression tools to start basic and grow over time. It has support for eye tracking and switches, and also new input methods like joysticks and gesture control, to give the user more flexibility.

','mobility','CoughDrop','','','https://at.mada.org.qa/technology/coughdrop-aac/','https://at.mada.org.qa/technology/coughdrop-aac/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/CoughDrop.png','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T08:18:39.769Z',NULL,NULL,NULL);
