INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_scanmarker-reader_cognition_1792656917565','Scanmarker Reader','Scanmarker Reader','','','Operating System: Other','','','','The Scanmarker is a fast and simple way to scan full lines of text straight to your computer. With a processing speed 30 times faster than manual typing, the Scanmarker will let you scan textbooks, notebooks, invoices and magazines, so students, lawyers, researchers or anyone with learning difficulties can read, study or work confidently.

Tutorials: https://scanmarkersupport.zendesk.com/hc/en-us/categories/4403283004177-Tutorials

','cognition','Scanmarker','','','https://at.mada.org.qa/technology/scanmarker-reader/','https://at.mada.org.qa/technology/scanmarker-reader/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/scanmarker.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T08:14:24.873Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_xbox-adaptive-controller_cognition_1792656917565','Xbox Adaptive Controller','Xbox Adaptive Controller','','','Operating System: Windows','','','','Xbox Adaptive Controller creates a custom controller experience that makes gaming more accessible. Connect external switches, buttons, mounts and joysticks.

Designed primarily to meet the needs of gamers with limited mobility, the Xbox Adaptive Controller features large programmable buttons and connects to external switches, buttons, mounts and joysticks to help make gaming more accessible. Requires external devices for gameplay.

Manufacturer: Xbox ( https://www.xbox.com/en-US/accessories/controllers/xbox-adaptive-controller)

','cognition','Xbox','','','https://at.mada.org.qa/technology/xbox-adaptive-controller/','https://at.mada.org.qa/technology/xbox-adaptive-controller/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Xbox-accessible-game-controller.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T08:15:01.219Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_animated-sandbox_cognition_1792656917565','Animated SandBox','Animated SandBox','','','Operating System: Other','','','','The Animated Sandbox is an educational interactive experience in which users can change and redesign habitats and topography. Users will explore, create, and learn by using their imaginations and our augmented reality sandbox.

Users will pile up and dig out sand, while an interactive sensor detects the changes made to the sand and the projection adjusts accordingly in real time. Augmented reality layers will make mountains, plains, and bodies of water, teaching users about topography and different environments. Animals and objects will react to the changes and roam where they are found in their natural habitats. This interactive tabletop sandbox is perfect for schools, museums, science centers, and more!

','cognition','Breeze Creative LLC.','','','https://at.mada.org.qa/technology/animated-sandbox/','https://at.mada.org.qa/technology/animated-sandbox/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Sandbox.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T11:34:54.433Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_hopspot_mobility_1792656917565','Hopspot','Hopspot','','','Operating System: iOS','','','','Hopspots is an interactive learning tool designed to make it easy to create active learning. Hopspots challenges in movement, cognitive training, language learning, collaboration etc., and makes it possible for children to become digital co-creators of learning content when they produce games in the app.

Hopspots trains body and memory whilst playing and learning. Thus, Hopspots can be used at all ages. For instance, Hopspots can help 3-year-old children recognize animal sounds, 7-year-old children with learning the alphabet, 10-year-old children with multiplication and division, 15-year-old children with collaboration and discussion, and help elderly citizens with having fun while preventing dementia and other age-related illnesses.

Hopspot How-to guides: https://www.hopspots.dk/en/get-started/

','mobility','Hopspot','','','https://at.mada.org.qa/technology/hopspot/','https://at.mada.org.qa/technology/hopspot/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Hopspot.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T08:19:12.642Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_lego-learning-system_mobility_1792656917565','Lego Learning System','Lego Learning System','','','Operating System: Other','','','','The LEGO® Learning System is a series of solutions that work seamlessly together to deliver engaging, hands-on STEAM learning experiences for students of all ages. It combines standards-aligned curriculum units, stackable LEGO bricks, a simple coding progression, intelligent hardware, and professional development, creating limitless possibilities for playful STEAM learning.

A scalable learning system based on the familiar LEGO brick that is intuitive, inclusive, and adaptable. Learn how it is transforming the way educators teach and kids learn.

Future-proofs Students with STEAM and 21st Century Skills
Students become confident, life-long learners through unlimited possibilities for hands-on, playful STEAM learning.

It Grows as they Grow
Abstract concepts become tangible, allowing students to move from simple explorations to increasingly complex real-world challenges as they progress through different grades.

Easy Implementation
Offers a scalable design, making it easy to implement at the classroom, school, or district level.

Manufacturer: Lego Education (https://education.lego.com/en-us/learningsystem#the-lego-learning-system )

','mobility','Lego Education','','','https://at.mada.org.qa/technology/lego-spike-essential/','https://at.mada.org.qa/technology/lego-spike-essential/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/lego-learning-system.png','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T08:19:35.882Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_mabot_mobility_1792656917565','Mabot','Mabot','','','Operating System: Other','','','','Mabot is an AI STEAM toy to let kids build, customize, and program robots, exploring mechanics, engineering, coding, and developing STEAM skills.

Mabot integrates complex functions into quality ball modules, so kids can just simply plug and play. Multi-angle design allows numerous combinations and variations so kids can build just about anything they can imagine. In addition, Mabot’s compatibility with Lego toys allows kids to extend their play.

Mabot educational resources: https://www.bellrobot.com/education.html

','mobility','Bellrobot','','','https://at.mada.org.qa/technology/mabot/','https://at.mada.org.qa/technology/mabot/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/mabot.png','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T08:19:43.548Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_kai-s-clan_mobility_1792656917565','Kai’s Clan','Kai’s Clan','','','Operating System: Other','','','','Kai’s Clan is a collaborative coding platform that encompasses several technologies into an all-in-one learning platform.

Teach coding, robotics, AR, VR, and the Internet of Things (IoT) in one easy-to-use web platform that works seamlessly on just about any device. Students code their robots to navigate the mat in real life, in real-time, wherever they are in the world.  At the same time, their 3D Robot avatars collaborate in a virtual world.

Kai’s Clan User Guide: https://kaisclan.ai/support/

','mobility','Kai’s Clan','','','https://at.mada.org.qa/technology/kais-clan/','https://at.mada.org.qa/technology/kais-clan/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/kais-clan.png','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T08:19:26.394Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_amazon-alexa_vision_1792656917565','Amazon Alexa','Amazon Alexa','','','Operating System: Other','','','','Use the Amazon Alexa App to set up your Alexa-enabled devices, listen to music, create shopping lists, get news updates, and much more. The more you use Alexa, the more she adapts to your voice, vocabulary, and personal preferences.

Show and Tell is designed to help people who are blind or have low vision. Show and Tell identifies common grocery items and other products by using your Echo Show’s camera. Hold up a product such as a canned good in front of your Echo Show’s camera and say, “Alexa, what am I holding?“

Amazon announces accessibility upgrades to Alexa app for people with vision impairments.

Light and dark modes: Using their mobile device settings, users can choose between light and dark modes for benefits like increased readability and colour contrast. Dark mode will offer benefits such as screen viewing comfort in low-light environments and improved device battery life, while light mode will offer better readability and colour contrast that stands out in high-light environments. The Alexa app will default to light or dark mode, depending on the user’s mobile settings.
Text scaling for improved accessibility: Users can set their device’s font size to be larger than the standard size. This means the individual will see larger text on most screens of the Alexa app proportional to their preferred accessibility setting. This can be especially helpful for people with certain vision impairments.

','vision','Amazon Mobile LLC','','','https://at.mada.org.qa/technology/amazon-alexa-app/','https://at.mada.org.qa/technology/amazon-alexa-app/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Amazon-Alexa.png','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T08:21:29.021Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_orcam-read_cognition_1792656917565','OrCam Read','OrCam Read','','','Operating System: Other','','','','For people with mild low vision, reading fatigue, reading difficulties including dyslexia, and for anyone who consumes large amounts of text. OrCam Read is a first-of-its-kind handheld device with a smart camera that seamlessly reads text from any printed surface or digital screen. Enjoy the morning paper, read any book, and even read all that appears on your computer or smartphone screen.

OrCam Read User Guide and Tutorial: https://www.orcam.com/en/read-user-area/

','cognition','OrCam','','','https://at.mada.org.qa/technology/orcam-read/','https://at.mada.org.qa/technology/orcam-read/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/OrCam-Read.png','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T08:14:16.838Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_mogo-super-evaluation-kit_mobility_1792656917565','MOGO Super Evaluation Kit','MOGO Super Evaluation Kit','','','Operating System: Other','','','','Mogo Super Evaluation Kit offers virtually every Mogo item to fully test different configurations to see what works best for wheelchair mounts and accessories. Featuring a sample of the three arms; modular metal, flexible steel, and modular plastic, plus a handful of bases and accessories.

Manufacturer: Adaptive Tech Solutions Modular Hose MOGO DIY Mounting Super Kit. Save money by purchasing kits from Adaptive Tech Solutions.

Video: Master Guide to ModularHose & MOGO Mounts Adaptive Technology Mounting Solutions

','mobility','Adaptive Tech Solutions','','','https://at.mada.org.qa/technology/mogo-super-evaluation-kit/','https://at.mada.org.qa/technology/mogo-super-evaluation-kit/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2025/02/Screenshot-2025-02-13-105342.png','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T08:19:41.762Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_assessment-switch-kit_mobility_1792656917565','Assessment Switch Kit','Assessment Switch Kit','','','Operating System: Other','','','','The Assessment Switch Kit is a comprehensive, bespoke package designed for users with limited motor control, providing a diverse selection of highly sensitive switches that require zero to minimal pressure for activation. This kit allows educators, therapists, and caregivers to assess and determine the most suitable switch options for individual users, ensuring optimal accessibility and comfort.

','mobility','Inclusive Technology','','','https://at.mada.org.qa/technology/assessment-switch-kit/','https://at.mada.org.qa/technology/assessment-switch-kit/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2025/02/assessment-switch-kit-catalogue-2021.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T08:18:06.262Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_tobii-pceye-5_mobility_1792656917565','Tobii PCEye 5','Tobii PCEye 5','','','Operating System: Other','','','','PCEye 5 is a compact eye tracker that enables people with physical disabilities to control a Windows computer with their eyes.
Replace a traditional keyboard and mouse with your eyes and surf the web, connect on social media, play games, create documents and more. Simply connect the PCEye to your Windows device via USB, and access everything your computer has to offer, intuitively and independently with TD Control.

Manufacturer: TobiiDynavox (https://www.tobiidynavox.com)

Support Manuals: https://www.tobiidynavox.com/pages/pceye-product-support
https://www.tobiidynavox.com/pages/pceye-product-support?tab=1

