INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_amaneo-assistive-mouse-adapter_mobility_1792656917565','AMAneo Assistive Mouse Adapter','AMAneo Assistive Mouse Adapter','','','Operating System: Other','','','','The AMAneo Anti-Tremor Assistive Mouse Adapter enables people with a hand tremor to use a computer mouse. It electronically filters the trembling of the hand, which can be very strong, so that the mouse pointer on the display moves smoothly. With tablets, touchscreen control is replaced by a normal mouse or an alternative mouse such as one offering head or chin control. Not all mice function within the power rating of the AMAneo USB so we now also include a free Logitech wireless mouse to ensure compatibility.

Support Document: https://www.csslabs.de/downloads/CSS_Produktuebersicht_AMAneo_DE_V10-21.pdf

','mobility','CSS Microsystems','','','https://at.mada.org.qa/technology/amaneo-assistive-mouse-adapter/','https://at.mada.org.qa/technology/amaneo-assistive-mouse-adapter/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/amaneo-usb.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T08:17:54.611Z',NULL,NULL,NULL);
INSERT OR REPLACE INTO kb_products (id,title,title_en,title_ar,title_fr,description,description_en,description_ar,description_fr,content,category,brand,model,price_range,source_url,product_url,image_url,iso_codes,wcag_level,who_gate_area,status,featured,sort_order,language,created_by,created_at,updated_at,content_en,content_ar,content_fr) VALUES ('mada_esight-4_dailyliving_1792656917565','eSight 4','eSight 4','','','Operating System: Other','','','','eSight 4 takes sight enhancement to a new level. Experience best visual acuity, unmatched mobility, ease of use, and new mobile and cloud-based capabilities.

eSight’s low vision device, more commonly referred to as electronic eyewear, functions by stimulating synaptic activity from the remaining photoreceptor function of the user’s eyes. Using a cutting edge camera, smart algorithms, and high-resolution screens, the assistive technology maximizes the visual information provided to the brain to naturally compensate for gaps in the user’s field of view.

Manufacturer: eSight Corp. (https://esighteyewear.com/low-vision-device-for-visually-impaired/

','daily_living','eSight Corp.','','','https://at.mada.org.qa/technology/esight-4/','https://at.mada.org.qa/technology/esight-4/','https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/eSight.jpg','[]','','','published',1,0,'vi',NULL,'2026-10-22T08:15:17.565Z','2026-10-23T11:35:45.614Z',NULL,NULL,NULL);
